/* TOEIC grammar topics for the tutor (Part 5/6). Generated content; may contain errors. */
window.GRAMMAR=[{"id":"pos","title_zh":"詞性判斷","title_en":"Parts of speech","icon":"🧩","pattern":"形容詞 + 名詞／動詞 + 副詞／be + 形容詞","rule_zh":"先看空格前後的字，判斷空格需要哪一種詞性。冠詞、形容詞或所有格後面要接名詞；助動詞（will、must）後面接原形動詞。修飾名詞用形容詞，修飾動詞、形容詞或整句用副詞。","rule_en":"Look at the words around the blank to decide which part of speech is needed. Use a noun after a/the, an adjective or a possessive, an adjective before a noun or after be, and an adverb to describe a verb or an adjective.","spot_zh":"考題線索：四個選項是同一個字根的不同詞性（例如 care / careful / carefully / carefulness），就是詞性題。","examples":[{"en":"She is a careful driver.","zh":"她是個小心的駕駛。"},{"en":"She drives carefully.","zh":"她開車很小心。"},{"en":"Thanks for your help with the move.","zh":"謝謝你幫忙搬家。"}],"qs":[{"lvl":700,"s":"The manager gave a clear ___ of the new travel policy.","zh":"經理對新的差旅政策做了清楚的說明。","opts":["explanation","explain","explained","explanatory"],"a":0,"guide":[{"q":"空格前面是 a clear，clear 是什麼詞性？","en":"What part of speech is 'clear' before the blank?","opts":["副詞","形容詞","動詞"],"a":1,"say":"clear 是形容詞，形容詞後面要接名詞。"},{"q":"哪一個選項是名詞？","en":"Which option is a noun?","opts":["explanatory","explanation"],"a":1,"say":"-tion 結尾是名詞，所以選 explanation。"}],"why_zh":"a clear 後面需要名詞，explanation 是名詞。explanatory 是形容詞，不能放在形容詞 clear 後面當主要名詞。","why_en":"After 'a clear' we need a noun, so 'explanation' is correct."},{"lvl":700,"s":"Please read the safety instructions ___ before using the machine.","zh":"使用機器前請仔細閱讀安全說明。","opts":["careful","carefully","care","carefulness"],"a":1,"guide":[{"q":"空格在描述哪個動作「怎麼做」？","en":"The blank describes how someone does which action?","opts":["instructions","read"],"a":1,"say":"空格描述「怎麼讀」，修飾動詞要用副詞。"}],"why_zh":"空格修飾動詞 read，要用副詞 carefully。careful 是形容詞，只能修飾名詞。","why_en":"An adverb describes the verb 'read', so 'carefully' is correct."},{"lvl":700,"s":"The hotel staff were very ___ during our stay.","zh":"我們住宿期間，飯店員工非常樂於幫忙。","opts":["help","helpfully","helpful","helpfulness"],"a":2,"guide":[{"q":"空格前面是 were very，be 動詞後面描述主詞通常用什麼詞性？","en":"After 'were very', what describes the subject?","opts":["形容詞","副詞","動詞"],"a":0,"say":"be 動詞 + very 後面用形容詞來描述主詞。"}],"why_zh":"be 動詞 + very 後面要接形容詞 helpful。helpfully 是副詞，不能當 be 動詞的補語。","why_en":"After 'be very' we need an adjective, so 'helpful' is correct."},{"lvl":700,"s":"Our sales team will ___ the results at Friday's meeting.","zh":"我們的業務團隊將在週五的會議上分析結果。","opts":["analysis","analytical","analytically","analyze"],"a":3,"guide":[{"q":"空格前面是 will，will 後面要接什麼？","en":"What comes after 'will'?","opts":["名詞","原形動詞"],"a":1,"say":"助動詞 will 後面一定接原形動詞。"}],"why_zh":"will 後面要接原形動詞 analyze。analysis 是名詞，不能直接放在 will 後面。","why_en":"'Will' must be followed by a base verb, so 'analyze' is correct."},{"lvl":700,"s":"Ms. Chen is responsible for the ___ of new employees.","zh":"陳小姐負責新進員工的訓練。","opts":["train","training","trained","trainable"],"a":1,"guide":[{"q":"空格夾在 the 和 of 中間，需要什麼詞性？","en":"Between 'the' and 'of', what part of speech do we need?","opts":["形容詞","動詞","名詞"],"a":2,"say":"the ___ of 是典型的名詞位置。"}],"why_zh":"the ___ of 中間要放名詞，training 在這裡是名詞「訓練」。train 當名詞是「火車」，意思不對。","why_en":"The pattern 'the ___ of' needs a noun, so 'training' is correct."},{"lvl":700,"s":"The new software is ___ easier to use than the old version.","zh":"新軟體比舊版本好用得多。","opts":["considerably","considerable","consider","consideration"],"a":0,"guide":[{"q":"空格後面的 easier 是什麼詞性？","en":"What part of speech is 'easier'?","opts":["名詞","形容詞（比較級）"],"a":1,"say":"easier 是形容詞比較級，修飾形容詞要用副詞。"}],"why_zh":"修飾形容詞比較級 easier 要用副詞 considerably。considerable 是形容詞，不能修飾另一個形容詞。","why_en":"An adverb describes the adjective 'easier', so 'considerably' is correct."},{"lvl":700,"s":"Customers can make a ___ online or by phone.","zh":"顧客可以在網路上或打電話預約。","opts":["reserved","reserves","reservable","reservation"],"a":3,"guide":[{"q":"空格前面有冠詞 a，後面需要什麼？","en":"After the article 'a', what do we need?","opts":["單數名詞","形容詞","動詞"],"a":0,"say":"a 後面要接單數名詞，make a reservation 是固定用法。"}],"why_zh":"冠詞 a 後面需要單數名詞 reservation。reserves 是複數或動詞，不能接在 a 後面。","why_en":"After 'a' we need a singular noun, so 'reservation' is correct."},{"lvl":700,"s":"The restaurant offers a ___ selection of local dishes.","zh":"這家餐廳提供多樣的在地料理。","opts":["widely","widen","wide","width"],"a":2,"guide":[{"q":"空格後面的 selection 是什麼詞性？","en":"What part of speech is 'selection'?","opts":["名詞","動詞"],"a":0,"say":"selection 是名詞，修飾名詞要用形容詞。"}],"why_zh":"空格修飾名詞 selection，要用形容詞 wide。widely 是副詞，不能修飾名詞。","why_en":"An adjective describes the noun 'selection', so 'wide' is correct."},{"lvl":700,"s":"All visitors must ___ at the front desk.","zh":"所有訪客都必須在櫃檯登記。","opts":["register","registration","registered","registrant"],"a":0,"guide":[{"q":"must 後面要接什麼形式？","en":"What form comes after 'must'?","opts":["過去分詞","原形動詞","名詞"],"a":1,"say":"must 是助動詞，後面接原形動詞。"}],"why_zh":"must 後面接原形動詞 register。registration 是名詞，不能當動詞用。","why_en":"'Must' is followed by a base verb, so 'register' is correct."},{"lvl":700,"s":"The shipment was delayed ___ because of the storm.","zh":"這批貨因為暴風雨而短暫延誤。","opts":["brief","briefness","briefly","briefed"],"a":2,"guide":[{"q":"句子 The shipment was delayed 已經完整了嗎？","en":"Is 'The shipment was delayed' already a complete sentence?","opts":["還缺主詞","已經完整"],"a":1,"say":"句子已經完整，多出來的修飾語要用副詞。"}],"why_zh":"句子結構完整，空格修飾動詞 was delayed，要用副詞 briefly。brief 是形容詞，不能修飾動詞。","why_en":"The sentence is complete, so an adverb, 'briefly', describes the verb."},{"lvl":900,"s":"Despite the ___ rise in fuel costs, the airline has kept its ticket prices unchanged this quarter.","zh":"儘管燃料成本急遽上漲，這家航空公司本季仍維持票價不變。","opts":["sharpen","sharply","sharpness","sharp"],"a":3,"guide":[{"q":"the ___ rise 裡的 rise 在這裡是名詞還是動詞？","en":"In 'the ___ rise', is 'rise' a noun or a verb?","opts":["動詞","名詞"],"a":1,"say":"the 後面的 rise 是名詞，所以空格要用形容詞修飾它。"}],"why_zh":"rise 在 the 後面是名詞，修飾名詞要用形容詞 sharp。sharply 是副詞，容易被誤以為修飾動詞 rise。","why_en":"'Rise' is a noun here, so the adjective 'sharp' is correct."},{"lvl":900,"s":"The marketing department has ___ exceeded its sales targets for three consecutive quarters.","zh":"行銷部門已連續三季持續超越業績目標。","opts":["consistent","consistently","consistency","consist"],"a":1,"guide":[{"q":"空格在 has 和 exceeded 中間，這是什麼結構？","en":"The blank is between 'has' and 'exceeded'. What is this structure?","opts":["現在完成式動詞","名詞片語"],"a":0,"say":"has + p.p. 是動詞，中間插入的修飾語要用副詞。"}],"why_zh":"has 和 exceeded 中間要放副詞 consistently 修飾動詞。consistent 是形容詞，不能插在動詞中間。","why_en":"An adverb goes between 'has' and the past participle, so 'consistently' is correct."},{"lvl":900,"s":"Ms. Park's ___ to detail made her the obvious choice to lead the quality-control team.","zh":"朴小姐對細節的用心，讓她成為帶領品管團隊的不二人選。","opts":["attend","attentive","attention","attentively"],"a":2,"guide":[{"q":"所有格 Ms. Park's 後面要接什麼詞性？","en":"What comes after the possessive 'Ms. Park's'?","opts":["名詞","形容詞"],"a":0,"say":"所有格後面接名詞，而且這個名詞是句子的主詞。"},{"q":"這句的動詞是哪一個？","en":"What is the main verb of the sentence?","opts":["lead","made"],"a":1,"say":"動詞是 made，所以 Ms. Park's ___ 是主詞，要用名詞 attention。"}],"why_zh":"所有格後面要接名詞當主詞，attention to detail 是常見用法。attentive 是形容詞，雖然有 attentive to，但不能當主詞。","why_en":"A possessive needs a noun, and 'attention to detail' is the subject."},{"lvl":900,"s":"To remain ___, the company plans to lower prices and expand its online sales channels.","zh":"為了保持競爭力，公司計畫降價並擴大線上銷售通路。","opts":["competitive","competition","competitively","compete"],"a":0,"guide":[{"q":"remain 的用法和哪個動詞很像？","en":"Which verb works like 'remain'?","opts":["run","be"],"a":1,"say":"remain 是連綴動詞，像 be 一樣後面接形容詞。"}],"why_zh":"remain 是連綴動詞，後面接形容詞 competitive。competitively 是副詞，不能當連綴動詞的補語。","why_en":"'Remain' is followed by an adjective, so 'competitive' is correct."},{"lvl":900,"s":"The ___ of the new branch office has been postponed until the lease agreement is finalized.","zh":"新分公司的開幕已延後，直到租約確定為止。","opts":["open","opened","openly","opening"],"a":3,"guide":[{"q":"The ___ of the new branch office 是句子的什麼部分？","en":"What role does 'The ___ of the new branch office' play?","opts":["動詞","修飾語","主詞"],"a":2,"say":"它是主詞，the ___ of 中間要放名詞。"}],"why_zh":"主詞位置 the ___ of 需要名詞 opening（開幕）。open 主要當形容詞或動詞，不能當這裡的名詞。","why_en":"The subject needs a noun, so 'opening' is correct."}]},{"id":"tense","title_zh":"動詞時態","title_en":"Verb tenses","icon":"⏰","pattern":"時間線索 → 時態（since → have p.p.／yesterday → 過去式／next → will）","rule_zh":"時態題要先找句子裡的時間線索。yesterday、last week、ago 用過去式；next、tomorrow 用未來式；since、for、yet 常用現在完成式；currently、right now 用現在進行式。by + 未來時間用未來完成式，by the time + 過去事件用過去完成式。","rule_en":"Find the time clue first. Use past for yesterday or last week, future for next or tomorrow, present perfect for since or yet, and the progressive for right now or currently.","spot_zh":"考題線索：四個選項是同一個動詞的不同時態（works / worked / has worked / will work），就要找句中的時間詞。","examples":[{"en":"I have lived here since 2020.","zh":"我從 2020 年就住在這裡。"},{"en":"We watched a movie last night.","zh":"我們昨晚看了一部電影。"},{"en":"My sister is cooking dinner right now.","zh":"我姊姊正在煮晚餐。"}],"qs":[{"lvl":700,"s":"Mr. Lin ___ for this company since 2018.","zh":"林先生從 2018 年起就在這家公司工作。","opts":["has worked","works","worked","will work"],"a":0,"guide":[{"q":"句中的時間線索是哪個字？","en":"What is the time clue in the sentence?","opts":["company","since"],"a":1,"say":"since + 過去時間點，表示從過去持續到現在。"},{"q":"從過去持續到現在，要用哪一種時態？","en":"Which tense shows an action from the past until now?","opts":["過去式","現在完成式"],"a":1,"say":"since 搭配現在完成式 have/has + p.p.。"}],"why_zh":"since 2018 表示從過去持續到現在，要用現在完成式 has worked。worked 是過去式，表示已經結束，不能搭配 since。","why_en":"'Since 2018' needs the present perfect, 'has worked'."},{"lvl":700,"s":"The team ___ the report yesterday afternoon.","zh":"團隊昨天下午完成了報告。","opts":["finishes","finished","has finished","will finish"],"a":1,"guide":[{"q":"yesterday afternoon 是什麼時間？","en":"When is 'yesterday afternoon'?","opts":["過去","現在","未來"],"a":0,"say":"yesterday 是明確的過去時間，要用過去式。"}],"why_zh":"yesterday afternoon 是明確的過去時間，要用過去式 finished。has finished 不能和明確的過去時間一起用。","why_en":"'Yesterday' is a finished past time, so we use the past tense 'finished'."},{"lvl":700,"s":"We ___ the new product line at next month's trade show.","zh":"我們將在下個月的商展推出新產品線。","opts":["launched","have launched","will launch","were launching"],"a":2,"guide":[{"q":"next month's trade show 是過去還是未來？","en":"Is 'next month's trade show' past or future?","opts":["過去","未來"],"a":1,"say":"next month 是未來，要用 will + 原形動詞。"}],"why_zh":"next month 指未來，要用未來式 will launch。launched 和 have launched 都表示已經發生。","why_en":"'Next month' is in the future, so 'will launch' is correct."},{"lvl":700,"s":"Ms. Wang is busy right now; she ___ with a client.","zh":"王小姐現在很忙，她正在和客戶開會。","opts":["meets","met","has met","is meeting"],"a":3,"guide":[{"q":"right now 表示動作什麼時候發生？","en":"What does 'right now' tell us?","opts":["每天都做","此刻正在做"],"a":1,"say":"right now 表示此刻正在進行，要用現在進行式。"}],"why_zh":"right now 表示正在進行，要用現在進行式 is meeting。meets 是現在簡單式，用來說習慣或事實。","why_en":"'Right now' shows an action in progress, so 'is meeting' is correct."},{"lvl":700,"s":"By next Friday, the contractors ___ the renovation of the lobby.","zh":"到下週五之前，承包商將會完成大廳的整修。","opts":["complete","will have completed","completed","have completed"],"a":1,"guide":[{"q":"By next Friday 是說「到某個未來時間點為止」嗎？","en":"Does 'By next Friday' mean 'up to a future point'?","opts":["不是，是過去","是，是未來的期限"],"a":1,"say":"by + 未來時間，表示到那時動作已完成，用未來完成式 will have p.p.。"}],"why_zh":"by next Friday 表示在未來某時間點前完成，要用未來完成式 will have completed。have completed 只能說到現在為止。","why_en":"'By' plus a future time needs the future perfect, 'will have completed'."},{"lvl":700,"s":"These days, the store ___ at 9 a.m. on weekdays.","zh":"這陣子這家店平日早上九點開門。","opts":["opens","opened","will have opened","has opened"],"a":0,"guide":[{"q":"這句是在說一次的事件，還是現在的固定習慣？","en":"Is this one event or a regular habit now?","opts":["一次的事件","現在的固定習慣"],"a":1,"say":"現在的習慣或固定時間表，用現在簡單式。"}],"why_zh":"These days 和 on weekdays 表示現在的固定習慣，用現在簡單式 opens。has opened 表示完成，不用來描述每天的作息。","why_en":"A present routine uses the simple present, 'opens'."},{"lvl":700,"s":"When the fire alarm rang, the staff ___ a training session.","zh":"火災警報響起時，員工正在進行訓練課程。","opts":["have","have had","will have","were having"],"a":3,"guide":[{"q":"警報響的時候，訓練課程是什麼狀態？","en":"When the alarm rang, what was happening with the training?","opts":["正在進行中","還沒開始"],"a":0,"say":"過去某個時刻正在進行的動作，用過去進行式 was/were + V-ing。"}],"why_zh":"rang 是過去式，表示警報響時課程正在進行，用過去進行式 were having。have had 是現在完成式，和過去時間 when ... rang 不搭。","why_en":"An action in progress at a past moment uses the past progressive, 'were having'."},{"lvl":700,"s":"The shipment ___ yet, so we cannot confirm the delivery date.","zh":"貨還沒到，所以我們無法確認交貨日期。","opts":["had not arrived","does not arrive","has not arrived","will not arrive"],"a":2,"guide":[{"q":"句尾的 yet 常和哪一種時態搭配？","en":"Which tense often goes with 'yet'?","opts":["現在完成式","未來式"],"a":0,"say":"not ... yet「還沒」常用現在完成式。"}],"why_zh":"not ... yet 表示到現在為止還沒發生，用現在完成式 has not arrived。will not arrive 表示將來不會到，和 yet 不搭。","why_en":"'Not ... yet' goes with the present perfect, 'has not arrived'."},{"lvl":700,"s":"Our CEO ___ the Tokyo office last week.","zh":"我們的執行長上週拜訪了東京辦公室。","opts":["visited","visits","has visited","will visit"],"a":0,"guide":[{"q":"last week 是過去、現在還是未來？","en":"Is 'last week' past, present, or future?","opts":["未來","現在","過去"],"a":2,"say":"last week 是明確的過去時間，用過去式。"}],"why_zh":"last week 是明確的過去時間，要用過去式 visited。has visited 不能和 last week 這種明確的過去時間連用。","why_en":"'Last week' needs the simple past, 'visited'."},{"lvl":700,"s":"Please wait here; the manager ___ back in a few minutes.","zh":"請在這裡稍候，經理幾分鐘後就回來。","opts":["was","has been","will be","had been"],"a":2,"guide":[{"q":"in a few minutes 指的是什麼時候？","en":"When is 'in a few minutes'?","opts":["幾分鐘後","幾分鐘前"],"a":0,"say":"in + 一段時間 表示「再過多久」，是未來，用 will。"}],"why_zh":"in a few minutes 表示幾分鐘後，是未來，用 will be。was 是過去式，和未來時間矛盾。","why_en":"'In a few minutes' is future, so 'will be' is correct."},{"lvl":900,"s":"Sales of the new laptop ___ steadily since the company lowered its price in March.","zh":"自從公司在三月降價以來，新款筆電的銷量穩定成長。","opts":["rise","rose","will rise","have risen"],"a":3,"guide":[{"q":"since 後面的 lowered 是過去式，那主要子句要表達什麼？","en":"'Since' is followed by a past event. What should the main clause show?","opts":["從那時到現在的變化","過去已結束的事"],"a":0,"say":"since + 過去事件，主要子句表示從那時到現在，用現在完成式。"},{"q":"主詞 Sales 是單數還是複數？","en":"Is the subject 'Sales' singular or plural?","opts":["單數","複數"],"a":1,"say":"Sales 是複數，所以用 have risen。"}],"why_zh":"since 子句用過去式，主要子句要用現在完成式 have risen。rose 是過去式，容易因為 lowered 而誤選。","why_en":"With 'since' plus a past event, the main clause uses the present perfect, 'have risen'."},{"lvl":900,"s":"By the time the keynote speaker arrived, most of the guests ___ the conference hall.","zh":"等到主講人抵達時，大部分來賓都已經離開會議廳了。","opts":["leave","had already left","have already left","will already leave"],"a":1,"guide":[{"q":"來賓離開和主講人抵達，哪一件事先發生？","en":"Which happened first: the guests leaving or the speaker arriving?","opts":["主講人抵達","來賓離開"],"a":1,"say":"來賓先離開，在過去的過去，用過去完成式 had + p.p.。"}],"why_zh":"by the time + 過去式，表示在那之前已發生，用過去完成式 had already left。have already left 是現在完成式，不能搭配過去的 arrived。","why_en":"An action before another past action uses the past perfect, 'had already left'."},{"lvl":900,"s":"Currently, the IT department ___ a new security system that will protect customer data.","zh":"資訊部門目前正在安裝一套能保護客戶資料的新安全系統。","opts":["installed","has installed","is installing","will have installed"],"a":2,"guide":[{"q":"Currently 表示動作的狀態是？","en":"What does 'Currently' tell us about the action?","opts":["已經完成","目前進行中","未來才開始"],"a":1,"say":"currently 表示目前正在進行，用現在進行式。"}],"why_zh":"Currently 表示目前正在進行，用現在進行式 is installing。has installed 表示已完成，和 currently 的語意不合。","why_en":"'Currently' shows an action in progress, so 'is installing' is correct."},{"lvl":900,"s":"If the client approves the design tomorrow, we ___ production the following week.","zh":"如果客戶明天核准設計，我們將在下一週開始生產。","opts":["will begin","began","have begun","had begun"],"a":0,"guide":[{"q":"If 子句用了現在式 approves，但說的是什麼時候？","en":"The if-clause uses 'approves', but what time does it talk about?","opts":["過去","未來"],"a":1,"say":"條件句的 if 子句用現在式表未來，主要子句用 will。"}],"why_zh":"If 子句用現在式代替未來，主要子句要用未來式 will begin。began 和 had begun 是過去，和 tomorrow 矛盾。","why_en":"A future condition takes 'will' in the main clause, so 'will begin' is correct."},{"lvl":900,"s":"Ms. Ortiz ___ the Seoul branch for nearly five years before she was promoted to regional director last spring.","zh":"歐提茲小姐在去年春天升任區域總監之前，已經管理首爾分公司將近五年。","opts":["manages","has managed","will manage","had managed"],"a":3,"guide":[{"q":"管理首爾分公司是在升職之前還是之後？","en":"Did she manage the Seoul branch before or after her promotion?","opts":["之後","之前"],"a":1,"say":"在另一個過去事件之前持續的動作，用過去完成式。"}],"why_zh":"管理分公司發生在 last spring 升職之前，要用過去完成式 had managed。has managed 表示持續到現在，但她已經升職了。","why_en":"An action that lasted until another past event uses the past perfect, 'had managed'."}]},{"id":"passive","title_zh":"主動與被動語態","title_en":"Active and passive voice","icon":"🔁","pattern":"be + 過去分詞 (p.p.)","rule_zh":"主詞自己做動作用主動語態；主詞是「被」做動作的對象，就用被動語態 be + p.p.。被動也有時態變化，例如 is done、was done、will be done、has been done、is being done。助動詞後面的被動是 can/must + be + p.p.。","rule_en":"Use the active voice when the subject does the action. Use the passive (be + past participle) when the subject receives the action.","spot_zh":"考題線索：選項同時出現主動和被動形式（sends / is sent / has sent / was sending），而且空格後面常常沒有受詞，或有 by + 人。","examples":[{"en":"My phone was fixed yesterday.","zh":"我的手機昨天修好了。"},{"en":"This cake was made by my mom.","zh":"這個蛋糕是我媽媽做的。"},{"en":"The windows are cleaned every week.","zh":"窗戶每週都會清洗。"}],"qs":[{"lvl":700,"s":"All orders ___ within two business days.","zh":"所有訂單都會在兩個工作天內處理完成。","opts":["process","are processed","processing","have processed"],"a":1,"guide":[{"q":"訂單會自己處理東西，還是被人處理？","en":"Do the orders process something, or are they processed?","opts":["自己寄送","被寄送"],"a":1,"say":"訂單是被處理的對象，要用被動 be + p.p.。"}],"why_zh":"orders 是被處理的對象，要用被動 are processed。have processed 是主動，表示訂單自己處理了別的東西，而且後面沒有受詞。","why_en":"Orders receive the action, so the passive 'are processed' is correct."},{"lvl":700,"s":"All luggage ___ by security staff before boarding.","zh":"所有行李在登機前都會由安檢人員檢查。","opts":["checks","is checking","is checked","has checked"],"a":2,"guide":[{"q":"空格後面的 by security staff 是什麼意思？","en":"What does 'by security staff' tell us?","opts":["做動作的人","動作的地點"],"a":0,"say":"by + 人 表示動作者，主詞 luggage 是被檢查的，用被動。"}],"why_zh":"by security staff 表示行李被人檢查，用被動 is checked。is checking 是主動進行式，行李不會自己檢查。","why_en":"The luggage is checked by staff, so the passive 'is checked' is correct."},{"lvl":700,"s":"The new hotel ___ by a famous Japanese architect.","zh":"這家新飯店是由一位知名的日本建築師設計的。","opts":["was designed","designed","was designing","designs"],"a":0,"guide":[{"q":"飯店是設計者，還是被設計的東西？","en":"Is the hotel the designer or the thing designed?","opts":["設計者","被設計的東西"],"a":1,"say":"飯店是被設計的，而且後面有 by + 人，用被動。"}],"why_zh":"飯店是被建築師設計的，用被動 was designed。designed 是主動過去式，後面又沒有受詞，所以不對。","why_en":"The hotel was designed by someone, so the passive 'was designed' is correct."},{"lvl":700,"s":"Ms. Lee ___ the budget report to the director this morning.","zh":"李小姐今天早上把預算報告交給了主管。","opts":["was submitted","is submitted","been submitted","submitted"],"a":3,"guide":[{"q":"空格後面有受詞嗎？","en":"Is there an object after the blank?","opts":["有，the budget report","沒有"],"a":0,"say":"有受詞 the budget report，表示主詞自己做動作，用主動。"}],"why_zh":"李小姐自己繳交報告，後面有受詞，所以用主動 submitted。was submitted 是被動，表示李小姐被繳交出去，不合理。","why_en":"Ms. Lee does the action and there is an object, so the active 'submitted' is correct."},{"lvl":700,"s":"The meeting ___ until next Tuesday because the manager is sick.","zh":"因為經理生病，會議已延到下週二。","opts":["has postponed","postponed","has been postponed","is postponing"],"a":2,"guide":[{"q":"會議能自己延期嗎？","en":"Can a meeting postpone itself?","opts":["可以","不行，是被人延期"],"a":1,"say":"會議是被延期的，用被動 has been + p.p.。"}],"why_zh":"會議是被人延期，要用被動 has been postponed。has postponed 是主動，表示會議延期了別的東西。","why_en":"The meeting is postponed by someone, so 'has been postponed' is correct."},{"lvl":700,"s":"Employees ___ to wear their ID badges at all times.","zh":"員工必須隨時配戴識別證。","opts":["require","are required","requiring","have required"],"a":1,"guide":[{"q":"是員工要求別人，還是員工被公司要求？","en":"Do employees require others, or are they required by the company?","opts":["員工被要求","員工要求別人"],"a":0,"say":"員工是被要求的人，be required to + V 是常見被動用法。"}],"why_zh":"員工是被要求的對象，用被動 are required to。require 是主動，意思變成員工要求別人。","why_en":"Employees are asked by the company, so the passive 'are required' is correct."},{"lvl":700,"s":"The sales figures ___ at tomorrow's meeting.","zh":"銷售數字將在明天的會議上報告。","opts":["will be presented","will present","presented","are presenting"],"a":0,"guide":[{"q":"銷售數字會自己報告，還是被人報告？","en":"Do the figures present something, or are they presented?","opts":["自己報告","被人報告"],"a":1,"say":"數字是被報告的，用被動。"},{"q":"tomorrow 是什麼時間？","en":"When is 'tomorrow'?","opts":["未來","過去"],"a":0,"say":"未來的被動是 will be + p.p.。"}],"why_zh":"數字是被報告的，時間是明天，用未來被動 will be presented。will present 是主動，數字不會自己報告。","why_en":"The figures receive the action in the future, so 'will be presented' is correct."},{"lvl":700,"s":"Our chef ___ a special dessert for the anniversary dinner.","zh":"我們的主廚為週年晚宴準備了一道特別的甜點。","opts":["was prepared","has been prepared","is prepared","has prepared"],"a":3,"guide":[{"q":"主廚是做動作的人，還是被做的對象？","en":"Is the chef doing the action or receiving it?","opts":["被做的對象","做動作的人"],"a":1,"say":"主廚自己準備甜點，後面有受詞，用主動。"}],"why_zh":"主廚主動準備甜點，後面有受詞 a special dessert，用主動 has prepared。has been prepared 是被動，表示主廚被準備，不合理。","why_en":"The chef does the action, so the active 'has prepared' is correct."},{"lvl":700,"s":"Your room ___ right now, so please wait in the lobby.","zh":"您的房間正在打掃中，請在大廳稍候。","opts":["is cleaning","is being cleaned","cleans","has cleaned"],"a":1,"guide":[{"q":"房間是被打掃，而且是「正在」進行嗎？","en":"Is the room being cleaned at this moment?","opts":["是，被打掃且正在進行","不是"],"a":0,"say":"正在進行的被動用 is being + p.p.。"}],"why_zh":"房間被打掃且正在進行，用現在進行被動 is being cleaned。is cleaning 是主動，房間不會自己打掃。","why_en":"The room is cleaned at this moment, so 'is being cleaned' is correct."},{"lvl":700,"s":"The invoice must ___ by Friday.","zh":"這張發票必須在週五前付清。","opts":["pay","paying","be paid","been paid"],"a":2,"guide":[{"q":"發票會付錢，還是被付清？","en":"Does the invoice pay, or is it paid?","opts":["付錢","被付清"],"a":1,"say":"發票是被付的，助動詞後面的被動是 must be + p.p.。"}],"why_zh":"助動詞 must 後面的被動是 be paid。been paid 前面少了 have，不能直接接在 must 後面。","why_en":"After 'must', the passive is 'be paid'."},{"lvl":900,"s":"The new safety regulations, which ___ by the board last month, will take effect in January.","zh":"董事會上個月通過的新安全規定將於一月生效。","opts":["approved","have approved","were approving","were approved"],"a":3,"guide":[{"q":"which 指的是什麼？","en":"What does 'which' refer to?","opts":["the board","the new safety regulations"],"a":1,"say":"which 指規定，規定是被董事會通過的，用被動。"},{"q":"last month 表示什麼時態？","en":"What tense does 'last month' need?","opts":["過去式","現在完成式"],"a":0,"say":"last month 是過去，所以用 were + p.p.。"}],"why_zh":"which 指 regulations，是被董事會核准的，加上 last month，用過去被動 were approved。approved 是主動，會被句中的 board 誤導。","why_en":"'Which' refers to the regulations, which received the action last month: 'were approved'."},{"lvl":900,"s":"Applicants who ___ for the second interview will be contacted by e-mail before the end of the week.","zh":"獲選參加第二次面試的應徵者，將在本週結束前收到電子郵件通知。","opts":["have been selected","have selected","are selecting","selected"],"a":0,"guide":[{"q":"應徵者是挑選別人，還是被公司挑選？","en":"Do the applicants select someone, or are they selected?","opts":["挑選別人","被公司挑選"],"a":1,"say":"應徵者是被挑選的，關係子句也要用被動。"}],"why_zh":"應徵者是被挑選的，用被動 have been selected。selected 在這裡是主動過去式，後面沒有受詞，語意不通。","why_en":"Applicants are chosen by the company, so 'have been selected' is correct."},{"lvl":900,"s":"Since the hotel lobby ___ last year, guest satisfaction scores have improved significantly.","zh":"自從飯店大廳去年整修後，房客滿意度明顯提升。","opts":["renovated","has renovated","was renovated","was renovating"],"a":2,"guide":[{"q":"大廳會自己整修，還是被人整修？","en":"Does the lobby renovate something, or is it renovated?","opts":["自己整修","被人整修"],"a":1,"say":"大廳是被整修的，用被動。"},{"q":"last year 是什麼時間？","en":"When is 'last year'?","opts":["未來","過去"],"a":1,"say":"過去的被動是 was + p.p.。"}],"why_zh":"大廳是被整修的，last year 是過去，用 was renovated。renovated 是主動，大廳不會自己整修。","why_en":"The lobby received the action last year, so 'was renovated' is correct."},{"lvl":900,"s":"The quarterly report, ___ by the finance team, contains several errors that need to be corrected.","zh":"由財務團隊準備的季報中有幾個需要更正的錯誤。","opts":["prepare","prepared","preparing","to prepare"],"a":1,"guide":[{"q":"這句的主要動詞是哪一個？","en":"What is the main verb of the sentence?","opts":["contains","need"],"a":0,"say":"主要動詞是 contains，空格是修飾 report 的分詞。"},{"q":"報告是準備者，還是被準備的？","en":"Does the report prepare, or is it prepared?","opts":["準備者","被準備的"],"a":1,"say":"被動意思的分詞用過去分詞 p.p.。"}],"why_zh":"空格是修飾 report 的分詞，報告是被準備的，用過去分詞 prepared（= which was prepared）。preparing 是主動意思，後面也不會接 by。","why_en":"The report was prepared by the team, so the past participle 'prepared' is correct."},{"lvl":900,"s":"Guests ___ that the swimming pool will be closed for maintenance from June 3 to June 10.","zh":"提醒房客，游泳池將於 6 月 3 日至 6 月 10 日關閉維修。","opts":["are reminded","remind","are reminding","have reminded"],"a":0,"guide":[{"q":"是房客提醒別人，還是房客被飯店提醒？","en":"Do the guests remind someone, or are they reminded?","opts":["被提醒","提醒別人"],"a":0,"say":"房客是被提醒的對象，remind 後面也沒有人當受詞，用被動。"}],"why_zh":"remind 主動用法是 remind + 人 + that，這裡空格後沒有人，且房客是被提醒的，用被動 are reminded。remind 是主動，缺少受詞。","why_en":"The guests receive the reminder, so the passive 'are reminded' is correct."}]},{"id":"agree","title_zh":"主詞與動詞一致","title_en":"Subject-verb agreement","icon":"🤝","pattern":"單數主詞 + 單數動詞（-s）／複數主詞 + 複數動詞","rule_zh":"動詞要跟真正的主詞一致：單數主詞配單數動詞，複數主詞配複數動詞。主詞後面的介系詞片語（in the room、of the employees）不影響動詞。each、every、the number of 是單數；a number of 是複數。","rule_en":"The verb must match the real subject, not the nearest noun. Singular subjects take singular verbs, and plural subjects take plural verbs.","spot_zh":"考題線索：選項是同一個動詞的單複數變化（is / are、has / have、needs / need），就要找出真正的主詞。","examples":[{"en":"My brother likes pizza.","zh":"我弟弟喜歡披薩。"},{"en":"The keys on the table are mine.","zh":"桌上的鑰匙是我的。"},{"en":"Each of my friends has a bike.","zh":"我的每個朋友都有一台腳踏車。"}],"qs":[{"lvl":700,"s":"The manager ___ the weekly meeting every Monday.","zh":"經理每週一主持週會。","opts":["lead","are leading","leads","have led"],"a":2,"guide":[{"q":"主詞 The manager 是單數還是複數？","en":"Is 'The manager' singular or plural?","opts":["複數","單數"],"a":1,"say":"manager 是單數，現在簡單式動詞要加 -s。"}],"why_zh":"單數主詞 The manager 配單數動詞 leads。lead 是複數形，不能配單數主詞。","why_en":"A singular subject takes a singular verb, 'leads'."},{"lvl":700,"s":"The boxes in the storage room ___ to be moved today.","zh":"儲藏室裡的箱子今天需要搬走。","opts":["need","needs","is needing","has needed"],"a":0,"guide":[{"q":"真正的主詞是哪一個？","en":"What is the real subject?","opts":["the storage room","The boxes"],"a":1,"say":"in the storage room 只是修飾語，主詞是 The boxes。"}],"why_zh":"主詞是複數 The boxes，配複數動詞 need。needs 是被旁邊的單數 room 誤導。","why_en":"The subject 'boxes' is plural, so 'need' is correct."},{"lvl":700,"s":"Each of the employees ___ a parking pass.","zh":"每位員工都會收到一張停車證。","opts":["receive","are receiving","have received","receives"],"a":3,"guide":[{"q":"Each of the employees 的主詞是 each 還是 employees？","en":"Is the subject 'each' or 'employees'?","opts":["each","employees"],"a":0,"say":"Each of + 複數名詞，主詞是 each，看成單數。"}],"why_zh":"Each 是單數，配單數動詞 receives。receive 是被 employees 誤導的複數形。","why_en":"'Each' is singular, so 'receives' is correct."},{"lvl":700,"s":"Neither the manager nor the assistants ___ available this afternoon.","zh":"今天下午經理和助理們都沒有空。","opts":["is","are","was","has been"],"a":1,"guide":[{"q":"neither A nor B，動詞要跟哪一個一致？","en":"With 'neither A nor B', which noun does the verb agree with?","opts":["A（the manager）","B（the assistants）"],"a":1,"say":"neither A nor B 的動詞跟靠近的 B 一致。"},{"q":"this afternoon 是現在還是過去？","en":"Is 'this afternoon' present or past here?","opts":["現在／今天","過去"],"a":0,"say":"B 是複數 assistants，又是說今天，所以用 are。"}],"why_zh":"neither A nor B 的動詞跟 B（assistants，複數）一致，用 are。is 是跟 manager 一致，方向錯了。","why_en":"With 'neither ... nor', the verb agrees with the closer subject, 'assistants', so 'are'."},{"lvl":700,"s":"The information in these brochures ___ out of date.","zh":"這些小冊子裡的資訊已經過時了。","opts":["is","are","were","have been"],"a":0,"guide":[{"q":"information 是可數還是不可數名詞？","en":"Is 'information' countable or uncountable?","opts":["不可數","可數"],"a":0,"say":"information 是不可數名詞，當單數看。"}],"why_zh":"information 是不可數名詞，配單數動詞 is。are 是被 brochures 誤導的複數形。","why_en":"'Information' is uncountable and takes a singular verb, 'is'."},{"lvl":700,"s":"A number of customers ___ about the slow service.","zh":"許多顧客抱怨服務太慢。","opts":["has complained","complains","have complained","is complaining"],"a":2,"guide":[{"q":"A number of 是什麼意思？","en":"What does 'A number of' mean?","opts":["……的數量","許多"],"a":1,"say":"a number of = many「許多」，後面主詞是複數。"}],"why_zh":"a number of + 複數名詞 = 許多，配複數動詞 have complained。has complained 是把它和 the number of 搞混了。","why_en":"'A number of' means 'many', so the plural 'have complained' is correct."},{"lvl":700,"s":"Every room in the hotel ___ free Wi-Fi.","zh":"飯店的每個房間都有免費 Wi-Fi。","opts":["have","has","are having","were having"],"a":1,"guide":[{"q":"every + 名詞 是單數還是複數？","en":"Is 'every + noun' singular or plural?","opts":["複數","單數"],"a":1,"say":"every 後面接單數名詞，動詞也用單數。"}],"why_zh":"Every room 是單數，配單數動詞 has。have 是複數形，常因為「每個房間」聽起來很多而誤選。","why_en":"'Every room' is singular, so 'has' is correct."},{"lvl":700,"s":"The new sales figures ___ very encouraging.","zh":"新的銷售數字非常令人振奮。","opts":["is","was","has been","are"],"a":3,"guide":[{"q":"主詞 figures 是單數還是複數？","en":"Is 'figures' singular or plural?","opts":["複數","單數"],"a":0,"say":"figures 有 -s，是複數，用 are。"}],"why_zh":"主詞 figures 是複數，配 are。is、was、has been 都是單數形。","why_en":"'Figures' is plural, so 'are' is correct."},{"lvl":700,"s":"The number of applicants ___ increased this year.","zh":"今年應徵者的人數增加了。","opts":["have","are","has","were"],"a":2,"guide":[{"q":"The number of 的主詞是「數量」還是「應徵者」？","en":"Is the subject 'the number' or 'the applicants'?","opts":["應徵者","數量"],"a":1,"say":"the number of 的主詞是 number（數量），是單數。"}],"why_zh":"the number of 的主詞是 number，是單數，用 has increased。have 是被 applicants 誤導的複數形。","why_en":"'The number' is singular, so 'has' is correct."},{"lvl":700,"s":"Mr. Kim, together with his assistants, ___ the trade show every year.","zh":"金先生和他的助理們每年都參加這個商展。","opts":["attends","attend","are attending","have attended"],"a":0,"guide":[{"q":"together with his assistants 會改變主詞的單複數嗎？","en":"Does 'together with his assistants' change the subject?","opts":["會","不會"],"a":1,"say":"together with 只是插入語，主詞還是單數的 Mr. Kim。"}],"why_zh":"主詞是 Mr. Kim（單數），together with 片語不影響動詞，用 attends。attend 是被 assistants 誤導的複數形。","why_en":"The subject is 'Mr. Kim', so the singular 'attends' is correct."},{"lvl":900,"s":"The list of approved suppliers ___ updated by the purchasing department at the end of every quarter.","zh":"核准供應商名單在每季末由採購部門更新。","opts":["are","is","have","were"],"a":1,"guide":[{"q":"真正的主詞是哪一個？","en":"What is the real subject?","opts":["suppliers","The list"],"a":1,"say":"of approved suppliers 是修飾語，主詞是單數的 The list。"}],"why_zh":"主詞是 The list（單數），用 is updated。are 是被緊鄰的 suppliers 誤導。","why_en":"The subject is 'list', which is singular, so 'is' is correct."},{"lvl":900,"s":"Only one of the candidates who applied for the position ___ the required certification.","zh":"應徵這個職位的候選人中，只有一位具備所需的證照。","opts":["have","are having","possess","has"],"a":3,"guide":[{"q":"句子的主詞是哪一個？","en":"What is the subject of the sentence?","opts":["one","the candidates","the position"],"a":0,"say":"one of the candidates 的主詞是 one，是單數。"}],"why_zh":"主詞是 one（單數），用 has。have 和 possess 是被 candidates 誤導的複數形。","why_en":"The subject is 'one', so the singular 'has' is correct."},{"lvl":900,"s":"Customer feedback, as well as recent sales data, ___ that the new packaging design is effective.","zh":"顧客意見以及近期的銷售資料都顯示新包裝設計很有效。","opts":["suggests","suggest","are suggesting","have suggested"],"a":0,"guide":[{"q":"as well as 連接的部分，會讓主詞變成複數嗎？","en":"Does 'as well as' make the subject plural?","opts":["會，跟 and 一樣","不會，主詞看前面"],"a":1,"say":"A as well as B，動詞跟 A 一致。"},{"q":"feedback 是可數還是不可數？","en":"Is 'feedback' countable or uncountable?","opts":["不可數","可數"],"a":0,"say":"feedback 是不可數名詞，當單數，用 suggests。"}],"why_zh":"A as well as B 的動詞跟 A 一致，feedback 是不可數單數，用 suggests。suggest 是把 as well as 當成 and 的錯誤。","why_en":"With 'as well as', the verb agrees with 'feedback', which is singular: 'suggests'."},{"lvl":900,"s":"Attached to this e-mail ___ the updated schedule and a map of the conference venue.","zh":"隨信附上更新後的行程表與會場地圖。","opts":["is","has","are","was"],"a":2,"guide":[{"q":"這句是倒裝句，真正的主詞在動詞的前面還是後面？","en":"This sentence is inverted. Is the real subject before or after the verb?","opts":["前面","後面"],"a":1,"say":"主詞在後面：the updated schedule and a map。"},{"q":"the schedule and a map 是幾樣東西？","en":"How many things are 'the schedule and a map'?","opts":["兩樣（複數）","一樣（單數）"],"a":0,"say":"A and B 是複數主詞，用 are。"}],"why_zh":"倒裝句的主詞是 the updated schedule and a map，用 and 連接是複數，用 are。is 是只看到 schedule 或 e-mail 的陷阱。","why_en":"The real subject comes after the verb and is plural ('the schedule and a map'), so 'are'."},{"lvl":900,"s":"Twenty dollars ___ the standard fee for late returns at all of our rental locations.","zh":"我們所有租借據點的逾期歸還標準費用是二十美元。","opts":["are","is","were","have been"],"a":1,"guide":[{"q":"Twenty dollars 在這裡是指二十張鈔票，還是一筆金額？","en":"Does 'Twenty dollars' mean twenty bills or one amount of money?","opts":["一筆金額","二十張鈔票"],"a":0,"say":"金額、時間、距離當成一個整體時，視為單數。"}],"why_zh":"Twenty dollars 指一筆金額，看成單數整體，用 is。are 是被 dollars 的 -s 誤導。","why_en":"An amount of money is treated as one unit, so 'is' is correct."}]},{"id":"toving","title_zh":"不定詞與動名詞","title_en":"To-infinitive vs. -ing (gerund)","icon":"🔀","pattern":"plan/decide/agree + to V／avoid/mind/suggest + V-ing／介系詞 + V-ing","rule_zh":"有些動詞後面接 to + 原形動詞，例如 plan、decide、agree、want、hope、wish。有些動詞後面接 V-ing，例如 avoid、mind、suggest、finish、consider。介系詞（for、in、after、to 當介系詞時）後面一定接 V-ing。","rule_en":"Some verbs take 'to + verb' (plan, decide, agree), and some take '-ing' (avoid, mind, suggest). After a preposition, always use the -ing form.","spot_zh":"考題線索：選項同時有 to V、V-ing、原形和過去式（to open / opening / open / opened），就看空格前面是哪個動詞或介系詞。","examples":[{"en":"I want to buy a new bike.","zh":"我想買一台新腳踏車。"},{"en":"She enjoys cooking on weekends.","zh":"她週末喜歡下廚。"},{"en":"Thanks for inviting me to the party.","zh":"謝謝你邀請我參加派對。"}],"qs":[{"lvl":700,"s":"The company plans ___ a new branch in Kaohsiung.","zh":"公司計畫在高雄開設新分公司。","opts":["open","opening","opened","to open"],"a":3,"guide":[{"q":"plan 後面通常接什麼？","en":"What usually follows 'plan'?","opts":["V-ing","to + 原形動詞"],"a":1,"say":"plan to do 是固定用法，表示計畫未來要做的事。"}],"why_zh":"plan 後面接不定詞 to open。opening 是動名詞，plan 不接 V-ing。","why_en":"'Plan' is followed by 'to + verb', so 'to open' is correct."},{"lvl":700,"s":"Would you mind ___ the meeting to Thursday?","zh":"你介意把會議改到週四嗎？","opts":["to move","moving","move","moved"],"a":1,"guide":[{"q":"mind 後面接 to V 還是 V-ing？","en":"Does 'mind' take 'to V' or 'V-ing'?","opts":["to V","V-ing"],"a":1,"say":"mind 後面只能接 V-ing。"}],"why_zh":"mind 後面接動名詞 moving。to move 是常見陷阱，但 mind 不接不定詞。","why_en":"'Mind' is followed by -ing, so 'moving' is correct."},{"lvl":700,"s":"We look forward to ___ with you again.","zh":"我們期待再次與您合作。","opts":["working","work","worked","have worked"],"a":0,"guide":[{"q":"look forward to 的 to 是不定詞還是介系詞？","en":"Is 'to' in 'look forward to' part of an infinitive or a preposition?","opts":["介系詞","不定詞"],"a":0,"say":"這裡的 to 是介系詞，介系詞後面接 V-ing。"}],"why_zh":"look forward to 的 to 是介系詞，後面接動名詞 working。work 是把 to 誤當成不定詞的陷阱。","why_en":"'To' in 'look forward to' is a preposition, so 'working' is correct."},{"lvl":700,"s":"Mr. Tanaka decided ___ the job offer from the Tokyo office.","zh":"田中先生決定接受東京辦公室的工作邀約。","opts":["accepting","accepted","to accept","accept"],"a":2,"guide":[{"q":"decide 後面接什麼形式？","en":"What form follows 'decide'?","opts":["原形動詞","V-ing","to + 原形動詞"],"a":2,"say":"decide to do「決定做某事」。"}],"why_zh":"decide 後面接不定詞 to accept。accepting 是動名詞，decide 不接 V-ing。","why_en":"'Decide' takes 'to + verb', so 'to accept' is correct."},{"lvl":700,"s":"Please avoid ___ personal calls during work hours.","zh":"上班時間請避免打私人電話。","opts":["make","to make","made","making"],"a":3,"guide":[{"q":"avoid 後面接 to V 還是 V-ing？","en":"Does 'avoid' take 'to V' or 'V-ing'?","opts":["V-ing","to V"],"a":0,"say":"avoid 後面只能接 V-ing。"}],"why_zh":"avoid 後面接動名詞 making。to make 是常見陷阱，avoid 不接不定詞。","why_en":"'Avoid' is followed by -ing, so 'making' is correct."},{"lvl":700,"s":"Thank you for ___ our customer satisfaction survey.","zh":"感謝您填寫我們的顧客滿意度調查。","opts":["completing","complete","to complete","completed"],"a":0,"guide":[{"q":"空格前面的 for 是什麼詞性？","en":"What part of speech is 'for' before the blank?","opts":["動詞","介系詞"],"a":1,"say":"for 是介系詞，介系詞後面接 V-ing。"}],"why_zh":"介系詞 for 後面接動名詞 completing。to complete 不能放在介系詞後面。","why_en":"After the preposition 'for', use -ing: 'completing'."},{"lvl":700,"s":"The staff agreed ___ late to finish the project on time.","zh":"員工同意留下來加班，以便準時完成專案。","opts":["staying","stayed","to stay","stay"],"a":2,"guide":[{"q":"agree 後面接什麼形式？","en":"What form follows 'agree'?","opts":["V-ing","to + 原形動詞"],"a":1,"say":"agree to do「同意做某事」。"}],"why_zh":"agree 後面接不定詞 to stay。staying 是動名詞，agree 不直接接 V-ing。","why_en":"'Agree' takes 'to + verb', so 'to stay' is correct."},{"lvl":700,"s":"The hotel manager suggested ___ a free shuttle service for guests.","zh":"飯店經理建議為房客提供免費接駁服務。","opts":["to offer","offering","offer","offered"],"a":1,"guide":[{"q":"suggest 後面直接接動作時，要用哪一種形式？","en":"When 'suggest' is followed directly by an action, which form is used?","opts":["to V","V-ing"],"a":1,"say":"suggest 後面直接接動作要用 V-ing，不能接 to V。"}],"why_zh":"suggest 後面接動名詞 offering。to offer 是中文直覺的錯誤，suggest 不接不定詞。","why_en":"'Suggest' is followed by -ing, so 'offering' is correct."},{"lvl":700,"s":"Ms. Ho is interested in ___ the marketing team.","zh":"何小姐有興趣加入行銷團隊。","opts":["join","joining","to join","joined"],"a":1,"guide":[{"q":"空格前面的 in 是什麼詞性？","en":"What is 'in' before the blank?","opts":["介系詞","動詞"],"a":0,"say":"in 是介系詞，後面要接 V-ing。"}],"why_zh":"介系詞 in 後面接動名詞 joining。to join 不能接在介系詞後面。","why_en":"After the preposition 'in', use -ing: 'joining'."},{"lvl":700,"s":"Customers who wish ___ their orders should call our service center.","zh":"想取消訂單的顧客請致電我們的客服中心。","opts":["to cancel","canceling","cancel","canceled"],"a":0,"guide":[{"q":"wish 後面接動作時用什麼形式？","en":"What form follows 'wish' when it takes an action?","opts":["V-ing","原形動詞","to + 原形動詞"],"a":2,"say":"wish to do「希望做某事」，和 want to do 一樣。"}],"why_zh":"wish 後面接不定詞 to cancel。canceling 是動名詞，wish 不接 V-ing。","why_en":"'Wish' takes 'to + verb', so 'to cancel' is correct."},{"lvl":900,"s":"After ___ the contract carefully, the legal team recommended several changes to the payment terms.","zh":"法務團隊仔細審閱合約後，建議修改幾項付款條件。","opts":["review","to review","reviewing","reviewed"],"a":2,"guide":[{"q":"After 在這裡後面沒有主詞，它是當連接詞還是介系詞？","en":"There is no subject after 'After'. Is it a conjunction or a preposition here?","opts":["連接詞","介系詞"],"a":1,"say":"After 後面沒有主詞，當介系詞用，要接 V-ing。"}],"why_zh":"After 當介系詞時後面接動名詞 reviewing。reviewed 前面沒有主詞 they，不能當子句的動詞。","why_en":"After the preposition 'after', use -ing: 'reviewing'."},{"lvl":900,"s":"The new procedures are designed ___ the time customers spend waiting at the check-in counter.","zh":"新程序的目的是減少顧客在報到櫃檯的等候時間。","opts":["reducing","reduce","reduction","to reduce"],"a":3,"guide":[{"q":"be designed 後面接動作時，常用什麼形式表示「目的」？","en":"After 'be designed', what form shows the purpose?","opts":["to + 原形動詞","V-ing"],"a":0,"say":"be designed to do「設計用來做某事」，to V 表示目的。"}],"why_zh":"be designed to do 表示「目的是做某事」，用不定詞 to reduce。reducing 會被後面的 waiting 誤導。","why_en":"'Be designed to + verb' shows purpose, so 'to reduce' is correct."},{"lvl":900,"s":"Management is committed to ___ a safe and comfortable workplace for all employees.","zh":"管理階層致力於為所有員工提供安全舒適的工作環境。","opts":["provide","providing","provided","be provided"],"a":1,"guide":[{"q":"be committed to 的 to 是不定詞還是介系詞？","en":"Is 'to' in 'be committed to' an infinitive or a preposition?","opts":["不定詞","介系詞"],"a":1,"say":"be committed to 的 to 是介系詞，後面接 V-ing。"}],"why_zh":"be committed to 的 to 是介系詞，要接動名詞 providing。provide 是把 to 當成不定詞的陷阱。","why_en":"'To' in 'be committed to' is a preposition, so 'providing' is correct."},{"lvl":900,"s":"Although the sales team has finished the proposal, it is still waiting for the director ___ the final budget.","zh":"雖然業務團隊已完成提案，但仍在等主管核准最終預算。","opts":["to approve","approval","approve","approves"],"a":0,"guide":[{"q":"wait for + 人 後面，要用什麼形式說那個人要做的事？","en":"After 'wait for + person', what form describes what that person will do?","opts":["to + 原形動詞","原形動詞"],"a":0,"say":"wait for someone to do something「等某人做某事」。"}],"why_zh":"wait for + 人 + to V 是固定句型，用 to approve。approve 少了 to，approval 是名詞不能接受詞 the final budget。","why_en":"The pattern is 'wait for someone to do something', so 'to approve' is correct."},{"lvl":900,"s":"Despite the heavy rain, the outdoor event managed ___ a record number of visitors last weekend.","zh":"儘管下大雨，這場戶外活動上週末仍成功吸引了創紀錄的人潮。","opts":["attracting","attracted","attract","to attract"],"a":3,"guide":[{"q":"manage 表示「設法做到」時，後面接什麼？","en":"When 'manage' means 'succeed in doing', what follows it?","opts":["V-ing","to + 原形動詞"],"a":1,"say":"manage to do「設法做到某事」。"}],"why_zh":"manage 後面接不定詞 to attract。attracting 可能被 Despite 後面要接名詞／V-ing 的概念誤導。","why_en":"'Manage' takes 'to + verb', so 'to attract' is correct."}]},{"id":"participle","title_zh":"分詞形容詞（-ing / -ed）","title_en":"Participle adjectives and participle phrases","icon":"🎭","pattern":"V-ing（主動／令人…） vs. V-ed（被動／感到…）","rule_zh":"-ing 形容詞表示「令人…的」或主動在做，通常修飾事物；-ed 形容詞表示「感到…的」或被動被做，通常修飾人的感受。分詞片語放在名詞後面也一樣：名詞主動做動作用 -ing，被動被做用 -ed。","rule_en":"-ing means the noun causes the feeling or does the action. -ed means the noun feels it or receives the action.","spot_zh":"考題線索：空格在 be 動詞後或名詞前後，選項是同一動詞的 -ing、-ed、原形、名詞時，就要判斷主動／被動或「令人」／「感到」。","examples":[{"en":"The movie was boring, so I was bored.","zh":"那部電影很無聊，所以我覺得很無聊。"},{"en":"Look at the broken window!","zh":"你看那扇破掉的窗戶！"},{"en":"The girl wearing a red hat is my sister.","zh":"戴紅帽子的那個女生是我妹妹。"}],"qs":[{"lvl":700,"s":"The staff found the training session very ___.","zh":"員工們覺得這次訓練課程非常有趣。","opts":["interest","interested","interesting","interestingly"],"a":2,"guide":[{"q":"空格描述的是「人」的感受，還是「訓練課程」這件事？","en":"Does the blank describe people's feelings or the training session?","opts":["人的感受","訓練課程"],"a":1,"say":"空格說明 the training session，是事物本身「令人感到有趣」。"},{"q":"事物「令人…」要用哪一種形容詞？","en":"Which form means 'causing the feeling'?","opts":["-ed","-ing"],"a":1,"say":"令人有趣的事物用 -ing：interesting。"}],"why_zh":"find + 受詞 + 形容詞，受詞是課程，課程「令人感興趣」用 interesting。interested 是人「感到」有興趣。","why_en":"The session causes interest, so we use interesting."},{"lvl":700,"s":"Customers who are ___ in the new product line can sign up online.","zh":"對新產品系列有興趣的顧客可以上網登記。","opts":["interested","interesting","interest","interests"],"a":0,"guide":[{"q":"主詞 customers 是人還是物？","en":"Are customers people or things?","opts":["物","人"],"a":1,"say":"customers 是人，描述人「感到」有興趣要用 -ed。"},{"q":"空格後面接哪個介系詞？","en":"Which preposition follows the blank?","opts":["in","on","at"],"a":0,"say":"be interested in 是固定用法，表示「對…有興趣」。"}],"why_zh":"人「感到有興趣」用 be interested in。interesting 是「令人感興趣的」，用來形容事物。","why_en":"People feel interest, so we say they are interested in something."},{"lvl":700,"s":"Please review the ___ file before the meeting.","zh":"請在會議前看一下附加的檔案。","opts":["attach","attaching","attaches","attached"],"a":3,"guide":[{"q":"檔案是自己去附加，還是「被」附加上去？","en":"Does the file attach something, or is it attached?","opts":["自己附加","被附加"],"a":1,"say":"檔案是被人附加的，屬於被動。"},{"q":"表示被動的分詞形容詞是哪一種？","en":"Which participle shows a passive meaning?","opts":["-ing","-ed"],"a":1,"say":"被動用過去分詞 -ed，所以是 attached file。"}],"why_zh":"file 是「被附加」的，放在名詞前用過去分詞 attached。attaching 表示主動在附加，不合理。","why_en":"The file is attached by someone, so we use the past participle attached."},{"lvl":700,"s":"Several passengers were ___ by the long flight delay.","zh":"好幾位乘客因為航班長時間延誤而感到沮喪。","opts":["frustrating","frustrated","frustrate","frustration"],"a":1,"guide":[{"q":"主詞 passengers 是「感到沮喪」的人，還是「令人沮喪」的事？","en":"Do the passengers feel frustration or cause it?","opts":["令人沮喪","感到沮喪"],"a":1,"say":"乘客是「感到」沮喪的人，要用 -ed。"},{"q":"空格後面的 by 透露了什麼？","en":"What does 'by' after the blank tell you?","opts":["被動語意","主動語意"],"a":0,"say":"by the delay 表示是延誤造成的，乘客是接受者，用 frustrated。"}],"why_zh":"乘客「感到」沮喪，且後接 by，用 frustrated。frustrating 是「令人沮喪的」，應形容延誤本身。","why_en":"The passengers feel the emotion, so frustrated is correct."},{"lvl":700,"s":"The sales figures for the third quarter were ___.","zh":"第三季的銷售數字令人失望。","opts":["disappointed","disappoint","disappointing","disappointment"],"a":2,"guide":[{"q":"sales figures（銷售數字）會有感覺嗎？","en":"Can sales figures have feelings?","opts":["會","不會"],"a":1,"say":"數字是事物，不會「感到」失望，而是「令人」失望。"}],"why_zh":"數字是事物，表示「令人失望的」用 disappointing。disappointed 是人「感到」失望。","why_en":"Figures cause disappointment, so we use disappointing."},{"lvl":700,"s":"Applicants ___ for the interview will be contacted next week.","zh":"獲選參加面試的應徵者下週會接到通知。","opts":["selected","selecting","select","selects"],"a":0,"guide":[{"q":"句子的主要動詞是哪一個？","en":"What is the main verb of the sentence?","opts":["will be contacted","空格"],"a":0,"say":"主要動詞是 will be contacted，所以空格只能是修飾 applicants 的分詞。"},{"q":"應徵者是去「挑選」別人，還是「被挑選」？","en":"Do applicants select, or are they selected?","opts":["去挑選","被挑選"],"a":1,"say":"應徵者是被挑選的，用過去分詞 selected。"}],"why_zh":"selected for the interview 修飾 applicants，表示「被選上的」。selecting 表示主動去選，意思不對。","why_en":"The applicants are chosen, so the passive participle selected is correct."},{"lvl":700,"s":"The manager gave an ___ presentation on the merger.","zh":"經理針對合併案做了一場令人興奮的簡報。","opts":["excited","exciting","excite","excitement"],"a":1,"guide":[{"q":"空格修飾的名詞是什麼？","en":"Which noun does the blank describe?","opts":["manager","presentation","merger"],"a":1,"say":"空格在 an 和 presentation 之間，修飾簡報這件事。"},{"q":"簡報是「令人興奮」還是「感到興奮」？","en":"Does a presentation cause excitement or feel it?","opts":["感到興奮","令人興奮"],"a":1,"say":"事物「令人」興奮，用 exciting。"}],"why_zh":"presentation 是事物，「令人興奮的」用 exciting。excited 是人「感到」興奮。","why_en":"A presentation causes excitement, so exciting is correct."},{"lvl":700,"s":"Visitors ___ the factory must wear safety helmets.","zh":"進入工廠的訪客必須戴安全帽。","opts":["entered","enter","enters","entering"],"a":3,"guide":[{"q":"這句已經有主要動詞了嗎？","en":"Does the sentence already have a main verb?","opts":["有，must wear","沒有"],"a":0,"say":"must wear 是主要動詞，空格要用分詞來修飾 visitors。"},{"q":"訪客是主動「進入」工廠，還是被進入？","en":"Do visitors enter the factory, or are they entered?","opts":["被進入","主動進入"],"a":1,"say":"訪客主動進入，且後面有受詞 the factory，用現在分詞 entering。"}],"why_zh":"visitors entering the factory 表示「進入工廠的訪客」，主動用 -ing。entered 表被動，且後面不能直接接受詞。","why_en":"Visitors do the action of entering, so we use entering."},{"lvl":700,"s":"We were ___ to hear that the project was approved.","zh":"聽到專案獲得核准，我們很高興。","opts":["pleased","pleasing","please","pleasure"],"a":0,"guide":[{"q":"主詞 we 是「感到高興」還是「令人高興」？","en":"Do we feel pleased or cause pleasure?","opts":["令人高興","感到高興"],"a":1,"say":"我們是「感到」高興的人，用 -ed。"}],"why_zh":"人「感到」高興用 be pleased to。pleasing 是「令人愉快的」，用來形容事物。","why_en":"We feel happy, so pleased is correct."},{"lvl":700,"s":"Orders ___ after 3 P.M. will be shipped the next business day.","zh":"下午三點之後下的訂單會在下一個工作日出貨。","opts":["placing","place","placed","places"],"a":2,"guide":[{"q":"訂單是自己「下單」，還是「被下」的？","en":"Do orders place something, or are they placed?","opts":["被下的","自己下單"],"a":0,"say":"訂單是被顧客下的，屬於被動。"},{"q":"被動意思的分詞用哪一種？","en":"Which participle is passive?","opts":["V-ing","V-ed"],"a":1,"say":"被動用過去分詞，orders placed after 3 P.M.。"}],"why_zh":"placed after 3 P.M. 修飾 orders，表示「被下的訂單」。placing 是主動，訂單不會自己下單。","why_en":"Orders are placed by customers, so placed is correct."},{"lvl":900,"s":"Dr. Kim's lecture on market trends was so ___ that many attendees stayed afterward to ask questions.","zh":"金博士關於市場趨勢的演講非常吸引人，許多與會者會後留下來提問。","opts":["fascinated","fascinating","fascination","fascinate"],"a":1,"guide":[{"q":"so ___ that 中的空格在描述誰？","en":"What does the blank in 'so ___ that' describe?","opts":["attendees","the lecture"],"a":1,"say":"主詞是 lecture，空格說明演講本身。"},{"q":"演講是「令人著迷」還是「感到著迷」？","en":"Does a lecture cause fascination or feel it?","opts":["令人著迷","感到著迷"],"a":0,"say":"事物令人著迷，用 fascinating。"}],"why_zh":"lecture 是事物，「令人著迷的」用 fascinating。容易被後面的 attendees 誤導而選 fascinated，但空格描述的是演講。","why_en":"The lecture causes fascination, so fascinating is correct."},{"lvl":900,"s":"The information ___ in this brochure is subject to change without prior notice.","zh":"本手冊所包含的資訊可能會變更，恕不另行通知。","opts":["containing","contain","contains","contained"],"a":3,"guide":[{"q":"句子的主要動詞是哪一個？","en":"What is the main verb?","opts":["is","空格"],"a":0,"say":"主要動詞是 is，空格不能再放動詞，只能放分詞。"},{"q":"資訊是「包含」別的東西，還是「被包含」在手冊裡？","en":"Does the information contain something, or is it contained in the brochure?","opts":["包含別的東西","被包含在手冊裡"],"a":1,"say":"資訊是被包含在手冊中，用過去分詞 contained。"}],"why_zh":"the information contained in this brochure 表示「手冊中所含的資訊」，被動用 contained。containing 後面需要受詞，這裡接的是 in，不合。","why_en":"The information is contained in the brochure, so we use contained."},{"lvl":900,"s":"Employees ___ to work remotely must submit a request to their supervisor at least two weeks in advance.","zh":"希望遠端工作的員工必須至少提前兩週向主管提出申請。","opts":["wishing","wished","wish","wishes"],"a":0,"guide":[{"q":"員工是主動「希望」，還是「被希望」？","en":"Do employees wish, or are they wished?","opts":["被希望","主動希望"],"a":1,"say":"員工自己希望遠端工作，是主動。"},{"q":"主動的分詞片語修飾名詞，要用哪種形式？","en":"Which participle form shows an active meaning?","opts":["V-ed","V-ing"],"a":1,"say":"主動用現在分詞，employees wishing to ... = employees who wish to ...。"}],"why_zh":"wishing to work remotely 是 who wish to 的省略，主動用 -ing。wished 表被動，不合邏輯；wish 會造成兩個動詞。","why_en":"Employees do the wishing, so the active participle wishing is correct."},{"lvl":900,"s":"Although the presentation was lengthy, the board members seemed genuinely ___ by the proposed expansion plan.","zh":"雖然簡報很冗長，董事們似乎真的對提出的擴張計畫印象深刻。","opts":["impressing","impressive","impressed","impress"],"a":2,"guide":[{"q":"seemed 的主詞是誰？","en":"Who is the subject of 'seemed'?","opts":["the presentation","the board members","the plan"],"a":1,"say":"主詞是 board members，是人。"},{"q":"空格後的 by the plan 表示董事們是…？","en":"With 'by the plan', are the members the cause or the receivers of the feeling?","opts":["感受的接受者","感受的來源"],"a":0,"say":"董事們是被計畫打動的人，用 impressed by。"}],"why_zh":"人「感到印象深刻」用 impressed by。impressive 是「令人印象深刻的」，用來形容計畫，且不接 by。","why_en":"The members feel impressed by the plan, so impressed is correct."},{"lvl":900,"s":"The shipment, ___ from our Taoyuan warehouse last Tuesday, is expected to arrive at the store by Friday.","zh":"這批上週二從桃園倉庫寄出的貨物，預計週五前會送達門市。","opts":["dispatching","dispatched","dispatch","dispatches"],"a":1,"guide":[{"q":"插入的部分有主詞嗎？","en":"Does the inserted phrase have its own subject?","opts":["有","沒有"],"a":1,"say":"逗號間沒有主詞，是修飾 shipment 的分詞片語。"},{"q":"貨物是自己「寄出」，還是「被寄出」？","en":"Does the shipment dispatch something, or is it dispatched?","opts":["被寄出","自己寄出"],"a":0,"say":"貨物是被寄出的，用過去分詞 dispatched。"}],"why_zh":"dispatched from... 是 which was dispatched 的省略，被動用 -ed。dispatching 表示主動寄東西，與貨物不合。","why_en":"The shipment was sent by someone, so the passive participle dispatched is correct."}]},{"id":"relative","title_zh":"關係代名詞","title_en":"Relative pronouns","icon":"🔗","pattern":"名詞 + who / which / that / whose / whom / where + 子句","rule_zh":"關係代名詞用來連接名詞和補充說明它的子句。先行詞是人用 who（主格）或 whom（受格），是物用 which；that 人、物都可用，但不能放在逗號後或介系詞後。whose 表示「…的」，後面直接接名詞；where 代替地點，後面接完整句子。","rule_en":"Use who/whom for people, which for things, and that for both (not after a comma or preposition). Whose + noun shows possession. Where refers to a place and is followed by a complete clause.","spot_zh":"考題線索：空格在名詞後面、後面還有一個子句，選項是 who / which / whose / where 等，就要看先行詞是人還是物，以及空格後缺主詞、受詞還是名詞。","examples":[{"en":"I have a friend who lives in Tainan.","zh":"我有一個住在台南的朋友。"},{"en":"This is the bag which I bought yesterday.","zh":"這是我昨天買的包包。"},{"en":"That is the park where we played as kids.","zh":"那是我們小時候玩耍的公園。"}],"qs":[{"lvl":700,"s":"The employee ___ won the sales award will speak at the dinner.","zh":"贏得業績獎的那位員工將在晚宴上致詞。","opts":["which","whose","who","whom"],"a":2,"guide":[{"q":"先行詞 employee 是人還是物？","en":"Is 'employee' a person or a thing?","opts":["物","人"],"a":1,"say":"employee 是人，所以不用 which。"},{"q":"空格後面直接接 won，空格是在當主詞還是受詞？","en":"The blank is followed by 'won'. Is it a subject or an object?","opts":["受詞","主詞"],"a":1,"say":"空格當 won 的主詞，人的主格用 who。"}],"why_zh":"先行詞是人，且空格後缺主詞，用主格 who。whom 是受格，不能當主詞。","why_en":"The clause needs a subject for a person, so who is correct."},{"lvl":700,"s":"The printer ___ we bought last month is already broken.","zh":"我們上個月買的印表機已經壞了。","opts":["which","who","whose","where"],"a":0,"guide":[{"q":"先行詞 printer 是人、物，還是地點？","en":"Is 'printer' a person, a thing, or a place?","opts":["人","地點","物"],"a":2,"say":"印表機是物，用 which 或 that。"}],"why_zh":"先行詞是物，且 bought 後面缺受詞，用 which。where 要接完整子句，這裡 bought 缺受詞。","why_en":"The printer is a thing and is the object of 'bought', so which is correct."},{"lvl":700,"s":"Ms. Chen is the manager ___ team handles overseas clients.","zh":"陳小姐是負責海外客戶那個團隊的經理。","opts":["who","which","whom","whose"],"a":3,"guide":[{"q":"空格後面緊接著的是什麼詞性？","en":"What comes right after the blank?","opts":["名詞 team","動詞"],"a":0,"say":"空格後直接接名詞 team。"},{"q":"team 和 manager 是什麼關係？","en":"What is the relation between 'team' and 'manager'?","opts":["經理的團隊","沒有關係"],"a":0,"say":"是「經理的團隊」，表示所有格要用 whose。"}],"why_zh":"whose + 名詞表示「…的」，whose team = the manager's team。who 後面要接動詞，不能直接接名詞再接動詞。","why_en":"Whose shows possession: the manager's team."},{"lvl":700,"s":"This is the hotel ___ the conference will be held.","zh":"這就是會議將要舉辦的飯店。","opts":["which","where","who","whose"],"a":1,"guide":[{"q":"空格後的 the conference will be held 是完整的句子嗎？","en":"Is 'the conference will be held' a complete clause?","opts":["不完整","完整"],"a":1,"say":"它有主詞也有動詞，不缺任何成分，是完整句子。"},{"q":"完整句子前，代替地點的關係詞是？","en":"Which word refers to a place before a complete clause?","opts":["where","which"],"a":0,"say":"先行詞是地點且後面句子完整，用 where（= in which）。"}],"why_zh":"hotel 是地點，後面子句完整，用 where。which 後面要缺主詞或受詞，這裡不缺。","why_en":"The clause is complete and hotel is a place, so where is correct."},{"lvl":700,"s":"Applicants ___ résumés are incomplete will not be considered.","zh":"履歷不完整的應徵者將不予考慮。","opts":["who","which","whose","whom"],"a":2,"guide":[{"q":"空格後面先出現的是名詞還是動詞？","en":"After the blank, do you see a noun or a verb first?","opts":["動詞","名詞 résumés"],"a":1,"say":"空格後是名詞 résumés，接著才是動詞 are。"}],"why_zh":"résumés 屬於應徵者，「應徵者的履歷」用 whose + 名詞。who 後面要直接接動詞。","why_en":"The résumés belong to the applicants, so whose is correct."},{"lvl":700,"s":"The candidate ___ we interviewed yesterday has accepted the offer.","zh":"我們昨天面試的那位應徵者已經接受了錄取。","opts":["whom","whose","where","what"],"a":0,"guide":[{"q":"空格後 we interviewed，interviewed 缺了什麼？","en":"In 'we interviewed', what is missing?","opts":["主詞","受詞"],"a":1,"say":"interviewed 後面少了受詞，空格要當受詞。"},{"q":"人當受詞的關係代名詞是？","en":"Which relative pronoun is the object form for people?","opts":["whose","whom"],"a":1,"say":"人的受格用 whom。"}],"why_zh":"先行詞是人，在子句中當 interviewed 的受詞，用 whom。what 本身已含先行詞，不能接在名詞後。","why_en":"The candidate is the object of 'interviewed', so whom is correct."},{"lvl":700,"s":"We need a supplier ___ can deliver parts within 48 hours.","zh":"我們需要一家能在 48 小時內交貨的供應商。","opts":["what","that","whom","where"],"a":1,"guide":[{"q":"空格後直接接 can deliver，空格扮演什麼角色？","en":"The blank is followed by 'can deliver'. What role does it play?","opts":["受詞","主詞"],"a":1,"say":"空格是子句的主詞。"}],"why_zh":"先行詞 supplier 後面子句缺主詞，用 that。whom 是受格，what 不能接在名詞後面。","why_en":"The clause needs a subject, so that is correct."},{"lvl":700,"s":"The report, ___ was released on Monday, shows strong growth.","zh":"這份週一公布的報告顯示強勁的成長。","opts":["that","who","what","which"],"a":3,"guide":[{"q":"空格前面有什麼標點？","en":"What punctuation comes before the blank?","opts":["逗號","沒有標點"],"a":0,"say":"前面有逗號，是非限定用法。"},{"q":"逗號後面可以用 that 嗎？","en":"Can 'that' follow a comma here?","opts":["可以","不可以"],"a":1,"say":"that 不能用在逗號後，物要用 which。"}],"why_zh":"逗號後的非限定子句修飾物用 which。that 不能放在逗號後面。","why_en":"After a comma, use which for things, not that."},{"lvl":700,"s":"Please contact the person ___ name appears on the invoice.","zh":"請聯絡名字出現在發票上的那個人。","opts":["whose","who","whom","which"],"a":0,"guide":[{"q":"name 屬於誰？","en":"Whose name is it?","opts":["發票的","那個人的"],"a":1,"say":"是那個人的名字，表示所有格。"}],"why_zh":"the person's name 用 whose name。who 後面不能直接接名詞再接動詞。","why_en":"It is the person's name, so whose is correct."},{"lvl":700,"s":"The restaurant ___ we had lunch yesterday has excellent service.","zh":"我們昨天吃午餐的那家餐廳服務很好。","opts":["which","whose","where","who"],"a":2,"guide":[{"q":"we had lunch 這個句子缺少主詞或受詞嗎？","en":"Is 'we had lunch' missing a subject or object?","opts":["缺受詞","不缺，很完整"],"a":1,"say":"we had lunch 是完整句子。"},{"q":"先行詞 restaurant 是什麼？","en":"What kind of noun is 'restaurant'?","opts":["地點","人"],"a":0,"say":"地點 + 完整句子，用 where。"}],"why_zh":"餐廳是地點，後面子句完整，用 where（= at which）。which 要用在子句缺主詞或受詞時。","why_en":"The restaurant is a place and the clause is complete, so where is correct."},{"lvl":900,"s":"The consultant to ___ you sent the proposal has requested additional financial data before the meeting.","zh":"你寄提案給他的那位顧問，要求在會議前提供更多財務資料。","opts":["who","whom","whose","that"],"a":1,"guide":[{"q":"空格前面是什麼字？","en":"What word comes right before the blank?","opts":["介系詞 to","動詞"],"a":0,"say":"空格前有介系詞 to，介系詞後要接受格。"},{"q":"介系詞後面可以接 that 嗎？","en":"Can 'that' come right after a preposition?","opts":["不可以","可以"],"a":0,"say":"that 不能放在介系詞後，人的受格用 whom。"}],"why_zh":"介系詞 to 後面要接受格，人用 whom。that 不能直接放在介系詞後，who 是主格。","why_en":"After a preposition, use whom for people."},{"lvl":900,"s":"Brightway Logistics, ___ headquarters are located in Kaohsiung, has opened three new warehouses this year.","zh":"總部位於高雄的 Brightway 物流公司今年新開了三座倉庫。","opts":["which","who","that","whose"],"a":3,"guide":[{"q":"空格後面先出現什麼？","en":"What comes right after the blank?","opts":["動詞 are","名詞 headquarters"],"a":1,"say":"空格後接名詞 headquarters。"},{"q":"headquarters 是誰的？","en":"Whose headquarters are they?","opts":["公司的","倉庫的"],"a":0,"say":"是公司的總部，所有格用 whose，物也可以用 whose。"}],"why_zh":"the company's headquarters 用 whose headquarters，whose 也可修飾物。which 和 who 後面不能直接接名詞再接動詞，that 不能放在逗號後。","why_en":"The headquarters belong to the company, so whose is correct."},{"lvl":900,"s":"The factory in ___ the components are assembled will be inspected by safety officials next month.","zh":"組裝這些零件的工廠下個月將由安全人員進行檢查。","opts":["which","where","that","whom"],"a":0,"guide":[{"q":"空格前面已經有哪個介系詞？","en":"Which preposition comes before the blank?","opts":["in","at","by"],"a":0,"say":"前面已經有 in，所以空格要放可接在介系詞後的關係代名詞。"},{"q":"in where 可以嗎？","en":"Can we say 'in where'?","opts":["可以","不可以"],"a":1,"say":"where 本身已含介系詞意思，in 後面要用 which；factory 是物，不用 whom。"}],"why_zh":"介系詞 + which 修飾物，in which = where。in where 重複，that 不能放在介系詞後。","why_en":"After a preposition, use which for things: in which."},{"lvl":900,"s":"Ms. Lin, ___ the board appointed as regional director last year, will oversee the new branch in Tainan.","zh":"董事會去年任命為區域總監的林小姐，將負責督導台南的新分公司。","opts":["which","whose","whom","where"],"a":2,"guide":[{"q":"在子句 the board appointed ___ 中，林小姐是主詞還是受詞？","en":"In the clause, is Ms. Lin the subject or the object of 'appointed'?","opts":["主詞","受詞"],"a":1,"say":"董事會任命林小姐，林小姐是受詞。"}],"why_zh":"先行詞是人，在子句中當 appointed 的受詞，用 whom。whose 後面要接名詞，the board 不是屬於她的。","why_en":"Ms. Lin is the object of 'appointed', so whom is correct."},{"lvl":900,"s":"Only staff members ___ have completed the safety training are allowed to operate the new equipment.","zh":"只有完成安全訓練的員工才可以操作新設備。","opts":["whom","who","whose","which"],"a":1,"guide":[{"q":"空格後直接接 have completed，空格當什麼？","en":"The blank is followed by 'have completed'. What role does it play?","opts":["受詞","所有格","主詞"],"a":2,"say":"空格是子句的主詞。"},{"q":"人當主詞的關係代名詞是？","en":"Which pronoun is the subject form for people?","opts":["who","whom"],"a":0,"say":"人的主格用 who。"}],"why_zh":"先行詞 staff members 是人，子句缺主詞，用 who。whom 是受格，不能當主詞。","why_en":"The clause needs a subject for people, so who is correct."}]},{"id":"conjprep","title_zh":"連接詞與介系詞","title_en":"Conjunctions vs. prepositions","icon":"🔀","pattern":"連接詞 + 子句（主詞＋動詞）／介系詞 + 名詞（片語）","rule_zh":"連接詞（although, because, while, unless, so that, in case）後面要接完整子句，有主詞和動詞。介系詞（despite, because of, during, thanks to）後面只能接名詞或名詞片語。意思相近的字要看空格後面接的是子句還是名詞來決定。","rule_en":"Conjunctions are followed by a clause (subject + verb). Prepositions are followed by a noun or noun phrase.","spot_zh":"考題線索：選項同時出現 although / despite、because / because of、while / during 這種意思相近的組合時，先看空格後是子句還是名詞。","examples":[{"en":"Although it was cold, we went swimming.","zh":"雖然天氣很冷，我們還是去游泳了。"},{"en":"Despite the cold, we went swimming.","zh":"儘管天氣冷，我們還是去游泳了。"},{"en":"I fell asleep during the movie.","zh":"我在看電影的時候睡著了。"}],"qs":[{"lvl":700,"s":"___ the heavy rain, the outdoor event was held as planned.","zh":"儘管下大雨，戶外活動仍照原定計畫舉行。","opts":["Although","Even though","Despite","Because"],"a":2,"guide":[{"q":"空格後面的 the heavy rain 是子句還是名詞片語？","en":"Is 'the heavy rain' a clause or a noun phrase?","opts":["子句","名詞片語"],"a":1,"say":"the heavy rain 沒有動詞，是名詞片語，要用介系詞。"},{"q":"下大雨和活動照常舉行，是因果還是相反的關係？","en":"Is the relation cause-result or contrast?","opts":["相反（讓步）","因果"],"a":0,"say":"下雨卻照常舉行，是讓步關係，用 despite。"}],"why_zh":"名詞片語前表示「儘管」用介系詞 despite。although 和 even though 是連接詞，後面要接子句。","why_en":"Despite is a preposition and is followed by a noun phrase."},{"lvl":700,"s":"___ the train was delayed, Mr. Park arrived at the meeting on time.","zh":"雖然火車誤點，朴先生還是準時抵達會議。","opts":["Although","Despite","In spite of","Because of"],"a":0,"guide":[{"q":"the train was delayed 有沒有動詞？","en":"Does 'the train was delayed' have a verb?","opts":["沒有","有，was delayed"],"a":1,"say":"有主詞也有動詞，是完整子句，要用連接詞。"}],"why_zh":"子句前表示「雖然」要用連接詞 although。despite 和 in spite of 是介系詞，只能接名詞。","why_en":"A clause follows the blank, so we need the conjunction although."},{"lvl":700,"s":"The flight was canceled ___ the storm.","zh":"班機因為暴風雨而取消。","opts":["because","so","although","because of"],"a":3,"guide":[{"q":"空格後面接的是什麼？","en":"What follows the blank?","opts":["名詞 the storm","完整子句"],"a":0,"say":"後面只有名詞 the storm，要用介系詞。"},{"q":"暴風雨是取消的原因還是結果？","en":"Is the storm the cause or the result?","opts":["結果","原因"],"a":1,"say":"暴風雨是原因，表示原因的介系詞是 because of。"}],"why_zh":"名詞前表示原因用 because of。because 是連接詞，後面要接子句。","why_en":"Because of is followed by a noun; because needs a clause."},{"lvl":700,"s":"Please do not use your phone ___ the presentation.","zh":"簡報期間請勿使用手機。","opts":["while","during","when","as"],"a":1,"guide":[{"q":"the presentation 是名詞還是子句？","en":"Is 'the presentation' a noun or a clause?","opts":["名詞","子句"],"a":0,"say":"the presentation 是名詞，需要介系詞。"}],"why_zh":"名詞前表示「在…期間」用介系詞 during。while、when、as 是連接詞，要接子句。","why_en":"During is a preposition and comes before a noun."},{"lvl":700,"s":"Ms. Wang answered e-mails ___ she was waiting for her flight.","zh":"王小姐在等班機的時候回覆電子郵件。","opts":["during","despite","while","because of"],"a":2,"guide":[{"q":"空格後面 she was waiting 是什麼？","en":"What is 'she was waiting...'?","opts":["名詞片語","子句"],"a":1,"say":"有主詞 she 和動詞 was waiting，是子句。"},{"q":"哪一個選項是連接詞？","en":"Which option is a conjunction?","opts":["during","while"],"a":1,"say":"while 是連接詞，表示「當…的時候」。"}],"why_zh":"子句前表示「當…時」用連接詞 while。during 是介系詞，只能接名詞。","why_en":"While is a conjunction and introduces a clause."},{"lvl":700,"s":"Mr. Kim stayed late at the office ___ he could finish the report.","zh":"金先生在辦公室待到很晚，好讓自己能完成報告。","opts":["so that","in order to","because of","despite"],"a":0,"guide":[{"q":"空格後面是子句還是動詞原形？","en":"Is a clause or a base verb after the blank?","opts":["動詞原形","子句 he could finish"],"a":1,"say":"後面有主詞 he 和動詞 could finish，是子句。"}],"why_zh":"子句前表示「為了、以便」用連接詞 so that。in order to 後面要接動詞原形，不能接主詞。","why_en":"So that is followed by a clause; in order to is followed by a base verb."},{"lvl":700,"s":"___ its high price, the new laptop has sold very well.","zh":"儘管價格很高，新筆電仍賣得很好。","opts":["Although","Despite","Because","Even if"],"a":1,"guide":[{"q":"its high price 有動詞嗎？","en":"Does 'its high price' have a verb?","opts":["沒有","有"],"a":0,"say":"its high price 是名詞片語，要用介系詞。"}],"why_zh":"名詞片語前表示讓步用 despite。although 和 even if 是連接詞，要接子句。","why_en":"Despite is followed by a noun phrase."},{"lvl":700,"s":"The meeting was postponed ___ the manager was sick.","zh":"會議因為經理生病而延期。","opts":["due to","despite","because of","because"],"a":3,"guide":[{"q":"the manager was sick 是子句還是名詞？","en":"Is 'the manager was sick' a clause or a noun?","opts":["名詞","子句"],"a":1,"say":"有主詞和動詞 was，是子句。"},{"q":"表示原因又能接子句的是？","en":"Which one shows a reason and takes a clause?","opts":["because","because of"],"a":0,"say":"because 是連接詞，可以接子句。"}],"why_zh":"子句前表示原因用連接詞 because。due to 和 because of 是介系詞，只能接名詞。","why_en":"Because is a conjunction and is followed by a clause."},{"lvl":700,"s":"Bring an umbrella ___ it rains this afternoon.","zh":"帶把傘，以防今天下午下雨。","opts":["in case","in case of","because of","despite"],"a":0,"guide":[{"q":"it rains 是子句還是名詞？","en":"Is 'it rains' a clause or a noun?","opts":["名詞","子句"],"a":1,"say":"it rains 有主詞和動詞，是子句。"}],"why_zh":"子句前表示「以防」用連接詞 in case。in case of 是介系詞片語，後面要接名詞，例如 in case of rain。","why_en":"In case takes a clause; in case of takes a noun."},{"lvl":700,"s":"Sales increased this quarter ___ the successful advertising campaign.","zh":"多虧了成功的廣告活動，這一季的銷售成長了。","opts":["because","although","thanks to","even though"],"a":2,"guide":[{"q":"空格後是子句還是名詞片語？","en":"Is a clause or a noun phrase after the blank?","opts":["名詞片語","子句"],"a":0,"say":"the successful advertising campaign 是名詞片語。"},{"q":"廣告活動和銷售成長是什麼關係？","en":"What is the relation between the campaign and the sales increase?","opts":["相反","原因"],"a":1,"say":"廣告是成長的原因，名詞前用 thanks to。"}],"why_zh":"名詞片語前表示正面原因用介系詞 thanks to。because 是連接詞，後面要接子句。","why_en":"Thanks to is a preposition that shows a reason before a noun."},{"lvl":900,"s":"___ the company's revenue fell slightly last year, management decided to increase the budget for employee training.","zh":"雖然公司去年營收略為下滑，管理階層仍決定增加員工訓練的預算。","opts":["Despite","Although","In spite of","Because of"],"a":1,"guide":[{"q":"空格到逗號之間，有沒有動詞？","en":"Is there a verb between the blank and the comma?","opts":["沒有","有，fell"],"a":1,"say":"fell 是動詞，所以是完整子句，要用連接詞。"},{"q":"營收下滑卻增加預算，是什麼關係？","en":"Revenue fell but the budget increased. What is the relation?","opts":["讓步（相反）","因果"],"a":0,"say":"前後相反，用表示讓步的連接詞 although。"}],"why_zh":"the company's revenue fell 是子句，要用連接詞 although。despite 和 in spite of 看起來後面是名詞 revenue，但後面還有動詞 fell，所以不行。","why_en":"A full clause follows the blank, so the conjunction although is correct."},{"lvl":900,"s":"___ the fact that the venue was quite small, more than 200 people attended the product launch.","zh":"儘管場地相當小，仍有超過 200 人參加了產品發表會。","opts":["Although","Even though","Because","Despite"],"a":3,"guide":[{"q":"空格後面緊接的是什麼？","en":"What comes right after the blank?","opts":["名詞 the fact","主詞 + 動詞"],"a":0,"say":"空格後是名詞 the fact，後面的 that 子句只是說明 fact 的內容。"},{"q":"名詞前要用連接詞還是介系詞？","en":"Before a noun, do we need a conjunction or a preposition?","opts":["連接詞","介系詞"],"a":1,"say":"名詞前用介系詞，despite the fact that 是常見用法。"}],"why_zh":"despite the fact that + 子句是固定說法，despite 後接名詞 the fact。although 和 even though 是連接詞，不能直接接名詞 the fact。","why_en":"Despite is followed by the noun 'the fact', which then takes a that-clause."},{"lvl":900,"s":"The shipment will be delivered on Friday ___ the customs inspection takes longer than expected.","zh":"除非海關檢查比預期花更久，否則貨物將在週五送達。","opts":["unless","without","except for","in spite of"],"a":0,"guide":[{"q":"the customs inspection takes longer 是子句嗎？","en":"Is 'the customs inspection takes longer' a clause?","opts":["不是","是"],"a":1,"say":"有主詞 inspection 和動詞 takes，是子句。"},{"q":"哪一個選項是連接詞，意思是「除非」？","en":"Which option is a conjunction meaning 'if not'?","opts":["without","unless"],"a":1,"say":"unless 是連接詞，表示「除非」。"}],"why_zh":"子句前表示「除非」用連接詞 unless。without 和 except for 是介系詞，後面只能接名詞。","why_en":"Unless is a conjunction and takes a clause."},{"lvl":900,"s":"___ the new accounting software was installed, the finance team has been able to process invoices much faster.","zh":"自從安裝了新的會計軟體，財務團隊處理發票的速度快了許多。","opts":["During","Because of","Since","Despite"],"a":2,"guide":[{"q":"空格到逗號之間的部分有動詞嗎？","en":"Is there a verb before the comma?","opts":["有，was installed","沒有"],"a":0,"say":"was installed 是動詞，所以是子句，要用連接詞。"},{"q":"主要子句用了 has been able，暗示什麼時間關係？","en":"The main clause uses 'has been able'. What time idea does this suggest?","opts":["從過去某時到現在","未來"],"a":0,"say":"現在完成式常搭配 since，表示「自從…以來」。"}],"why_zh":"since 可當連接詞接子句，表示「自從」，搭配現在完成式。during、because of、despite 都是介系詞，不能接子句。","why_en":"Since is a conjunction here and fits the present perfect."},{"lvl":900,"s":"The renovation project was completed on schedule ___ several unexpected problems with the suppliers.","zh":"儘管和供應商之間出現了幾個意外問題，翻修工程仍如期完工。","opts":["although","in spite of","even though","because"],"a":1,"guide":[{"q":"several unexpected problems with the suppliers 有動詞嗎？","en":"Does 'several unexpected problems with the suppliers' contain a verb?","opts":["有","沒有"],"a":1,"say":"這是一個較長的名詞片語，沒有動詞。"}],"why_zh":"名詞片語前表示讓步用介系詞 in spite of。although 和 even though 意思對，但是連接詞，要接子句。","why_en":"In spite of is a preposition and is followed by a noun phrase."}]},{"id":"paired","title_zh":"成對連接詞","title_en":"Paired conjunctions","icon":"👯","pattern":"both A and B／either A or B／neither A nor B／not only A but (also) B／whether A or B","rule_zh":"成對連接詞的搭配是固定的：both 配 and、either 配 or、neither 配 nor、not only 配 but also、whether 配 or。當主詞是 both A and B 時動詞用複數；either A or B、neither A nor B、not only A but also B 的動詞要跟最靠近的 B 一致。","rule_en":"Each pair has a fixed partner: both...and, either...or, neither...nor, not only...but also, whether...or. With both...and, use a plural verb; with the others, the verb agrees with the closer noun (B).","spot_zh":"考題線索：句中出現 both、either、neither、not only、whether 其中一個，而空格在後面另一半的位置（或反過來），直接找它的固定搭檔。","examples":[{"en":"I like both tea and coffee.","zh":"茶和咖啡我都喜歡。"},{"en":"We can eat either pizza or noodles tonight.","zh":"我們今晚可以吃披薩或麵。"},{"en":"Neither my brother nor my sister can drive.","zh":"我哥哥和我姊姊都不會開車。"}],"qs":[{"lvl":700,"s":"Both the manager ___ her assistant will attend the conference.","zh":"經理和她的助理都會出席研討會。","opts":["or","nor","and","but"],"a":2,"guide":[{"q":"句子開頭用了哪個字？","en":"Which word starts the pair?","opts":["Either","Both","Neither"],"a":1,"say":"句首是 Both，它的固定搭檔是 and。"}],"why_zh":"both A and B 是固定搭配，表示「A 和 B 兩者都」。or 要搭配 either。","why_en":"Both always goes with and."},{"lvl":700,"s":"You can pay either by credit card ___ in cash.","zh":"您可以用信用卡或現金付款。","opts":["or","and","nor","but"],"a":0,"guide":[{"q":"前面出現的是哪一個字？","en":"Which word appears before the blank?","opts":["both","either"],"a":1,"say":"前面有 either，要搭配 or。"}],"why_zh":"either A or B 表示「A 或 B 其中一個」。nor 要搭配 neither，and 要搭配 both。","why_en":"Either always goes with or."},{"lvl":700,"s":"___ the hotel nor the restaurant accepts pets.","zh":"飯店和餐廳都不接受寵物。","opts":["Either","Both","Not only","Neither"],"a":3,"guide":[{"q":"句中後半出現了哪個字？","en":"Which word appears later in the sentence?","opts":["nor","or","and"],"a":0,"say":"後面有 nor，它的搭檔是 neither。"}],"why_zh":"neither A nor B 表示「A 和 B 都不」。either 要配 or，both 要配 and。","why_en":"Nor goes with neither."},{"lvl":700,"s":"The new phone is not only light ___ also very fast.","zh":"這支新手機不但輕巧，而且速度很快。","opts":["and","but","or","nor"],"a":1,"guide":[{"q":"前面出現的是哪一個片語？","en":"Which phrase appears earlier?","opts":["not only","neither"],"a":0,"say":"not only 要搭配 but also。"}],"why_zh":"not only A but also B 是固定搭配。and 雖然有「而且」的意思，但不能和 not only 搭配。","why_en":"Not only goes with but also."},{"lvl":700,"s":"We have not decided ___ to hold the party indoors or outdoors.","zh":"我們還沒決定派對要辦在室內還是戶外。","opts":["if","both","whether","neither"],"a":2,"guide":[{"q":"空格後面接的是什麼形式？","en":"What form comes after the blank?","opts":["主詞 + 動詞","to + 動詞原形"],"a":1,"say":"後面是 to hold，不定詞前只能用 whether，不能用 if。"},{"q":"後面的 or 表示什麼？","en":"What does 'or' show here?","opts":["兩個選擇","兩者都要"],"a":0,"say":"室內或戶外二選一，用 whether A or B 表示「是…還是…」。"}],"why_zh":"whether + to V + A or B 表示「要 A 還是 B」。if 不能接不定詞，both 要配 and。","why_en":"Whether...or shows a choice, and only whether can be followed by to + verb."},{"lvl":700,"s":"___ Mr. Chen and Ms. Lin are responsible for the budget.","zh":"陳先生和林小姐兩人都負責預算。","opts":["Both","Either","Neither","Whether"],"a":0,"guide":[{"q":"句中的連接詞是哪一個？","en":"Which connecting word appears in the sentence?","opts":["or","nor","and"],"a":2,"say":"句中有 and，搭檔是 both。"},{"q":"動詞 are 是單數還是複數？","en":"Is 'are' singular or plural?","opts":["複數","單數"],"a":0,"say":"both A and B 指兩個人，動詞用複數 are。"}],"why_zh":"both A and B 搭配複數動詞 are。either 要配 or，neither 要配 nor。","why_en":"Both...and takes a plural verb."},{"lvl":700,"s":"The manager was neither surprised ___ upset by the news.","zh":"經理對這個消息既不驚訝也不難過。","opts":["or","nor","and","but"],"a":1,"guide":[{"q":"前面出現了哪一個字？","en":"Which word appears before the blank?","opts":["either","both","neither"],"a":2,"say":"前面有 neither，要搭配 nor。"}],"why_zh":"neither A nor B 表示「既不 A 也不 B」。or 要搭配 either。","why_en":"Neither always goes with nor."},{"lvl":700,"s":"Either the sales representatives or the manager ___ going to meet the client.","zh":"不是業務代表們就是經理會去和客戶見面。","opts":["are","were","have","is"],"a":3,"guide":[{"q":"either A or B 的動詞要跟哪一個一致？","en":"With either A or B, which noun does the verb agree with?","opts":["A（較遠的）","B（較近的）"],"a":1,"say":"動詞跟最靠近的 B 一致。"},{"q":"最靠近動詞的 the manager 是單數還是複數？","en":"Is 'the manager' singular or plural?","opts":["單數","複數"],"a":0,"say":"the manager 是單數，用 is。"}],"why_zh":"either A or B 的動詞和 B 一致，the manager 是單數用 is。are 是被前面的 representatives 誤導。","why_en":"The verb agrees with the closer noun, 'the manager', so is is correct."},{"lvl":700,"s":"The training is ___ for new staff but also for experienced employees.","zh":"這項訓練不只適合新進員工，也適合資深員工。","opts":["not only","both","either","neither"],"a":0,"guide":[{"q":"後半句出現了什麼？","en":"What appears in the second half?","opts":["but also","and","or"],"a":0,"say":"but also 的搭檔是 not only。"}],"why_zh":"not only A but also B 是固定搭配。both 要配 and，either 要配 or。","why_en":"But also goes with not only."},{"lvl":700,"s":"Both the hotel and the airport ___ easy to reach by train.","zh":"飯店和機場搭火車都很容易到達。","opts":["is","has","are","was"],"a":2,"guide":[{"q":"both A and B 指的是幾樣東西？","en":"How many things does 'both A and B' refer to?","opts":["一樣","兩樣"],"a":1,"say":"是兩樣東西，所以主詞是複數。"}],"why_zh":"both A and B 永遠用複數動詞，所以是 are。is 和 was 是單數，不能用在 both 後。","why_en":"Both...and always takes a plural verb."},{"lvl":900,"s":"___ the marketing director nor the sales team members were informed of the change in the product launch date.","zh":"行銷總監和業務團隊成員都沒有被告知產品上市日期的變更。","opts":["Either","Neither","Both","Not only"],"a":1,"guide":[{"q":"在長句中找一找，後面出現的連接詞是？","en":"Look through the sentence. Which connecting word appears later?","opts":["and","or","nor"],"a":2,"say":"後面有 nor，搭檔是 neither。"},{"q":"動詞 were 為什麼用複數？","en":"Why is 'were' plural?","opts":["因為最靠近的 members 是複數","因為有兩個主詞就一定用複數"],"a":0,"say":"neither A nor B 的動詞跟 B 一致，members 是複數。"}],"why_zh":"neither A nor B 是固定搭配。看到複數動詞 were 容易誤選 Both，但 Both 要配 and，不能配 nor。","why_en":"Nor must pair with neither."},{"lvl":900,"s":"The new customer service policy aims to improve ___ response times and customer satisfaction across all regional branches.","zh":"新的客服政策旨在同時提升所有區域分公司的回應速度和顧客滿意度。","opts":["either","neither","whether","both"],"a":3,"guide":[{"q":"response times 和 customer satisfaction 之間用什麼連接？","en":"What word joins 'response times' and 'customer satisfaction'?","opts":["or","and"],"a":1,"say":"中間是 and，搭檔是 both。"}],"why_zh":"both A and B 表示兩者都要提升。either 要配 or，whether 要配 or，所以都不能配 and。","why_en":"And pairs with both."},{"lvl":900,"s":"Not only the regional managers but also the CEO ___ expected to attend the quarterly review in Taichung.","zh":"不只是區域經理們，連執行長也預計會出席在台中舉行的季度檢討會。","opts":["is","are","were","have been"],"a":0,"guide":[{"q":"not only A but also B 的動詞跟誰一致？","en":"With not only A but also B, which noun does the verb agree with?","opts":["A","B"],"a":1,"say":"動詞跟最靠近的 B 一致。"},{"q":"the CEO 是單數還是複數？","en":"Is 'the CEO' singular or plural?","opts":["複數","單數"],"a":1,"say":"the CEO 是單數，所以用 is。"}],"why_zh":"not only A but also B 的動詞和 B（the CEO）一致，用單數 is。are 是被前面的 managers 誤導。","why_en":"The verb agrees with 'the CEO', which is singular."},{"lvl":900,"s":"Participants may submit their registration forms ___ online or at the front desk of the convention center before Friday.","zh":"參加者可以在週五前透過線上或在會展中心櫃台繳交報名表。","opts":["both","neither","either","not only"],"a":2,"guide":[{"q":"online 和 at the front desk 之間用哪個字連接？","en":"Which word joins 'online' and 'at the front desk'?","opts":["and","or","nor"],"a":1,"say":"中間是 or，表示二選一。"},{"q":"和 or 搭配、表示「兩者之一」的是？","en":"Which word pairs with or to mean 'one of the two'?","opts":["either","neither"],"a":0,"say":"either A or B 表示擇一。"}],"why_zh":"either A or B 表示「A 或 B 擇一」。neither 要配 nor，both 要配 and。","why_en":"Either pairs with or to show one of two choices."},{"lvl":900,"s":"Ms. Ho has not yet decided ___ she will accept the transfer to the Singapore office or remain at headquarters.","zh":"何小姐還沒決定是要接受調派到新加坡辦公室，還是留在總部。","opts":["that","whether","either","both"],"a":1,"guide":[{"q":"decided 後面的內容是確定的事，還是還在選擇？","en":"Is what follows 'decided' a fact or a choice still being made?","opts":["確定的事","還在選擇"],"a":1,"say":"她還在兩個選項中考慮，要用表示「是否、是…還是…」的字。"},{"q":"空格後面接的是子句還是名詞？","en":"Is a clause or a noun after the blank?","opts":["子句 she will accept","名詞"],"a":0,"say":"後面是子句，可以引導子句又能配 or 的是 whether。"}],"why_zh":"whether A or B 引導名詞子句，表示「是 A 還是 B」。either 後面不接完整子句，that 不能表示選擇。","why_en":"Whether...or introduces a clause about a choice between two options."}]},{"id":"prep","title_zh":"介系詞","title_en":"Prepositions","icon":"📍","pattern":"at + 時刻／on + 日期、星期／in + 月份、年份；by（截止）vs. until（持續）；固定搭配","rule_zh":"時間：at 接時刻，on 接日期和星期，in 接月份、年份和早上下午。by 表示「最晚在…之前完成」，until 表示「一直持續到…」。另外多益常考固定搭配，例如 in charge of、on behalf of、in advance、at full capacity、in case，要整組記起來。","rule_en":"Use at for clock times, on for days and dates, and in for months and years. By means 'no later than'; until means 'continuing up to'. Learn fixed phrases like in charge of and on behalf of as whole units.","spot_zh":"考題線索：四個選項都是介系詞（in / on / at / by…）時，看空格後的名詞是時間、地點，還是和前後字組成固定搭配。","examples":[{"en":"My birthday is on May 5.","zh":"我的生日在五月五日。"},{"en":"Let's meet at 7 o'clock.","zh":"我們七點見面吧。"},{"en":"Please give the book back by Sunday.","zh":"請在星期天之前把書還來。"}],"qs":[{"lvl":700,"s":"The meeting will start ___ 9:30 A.M.","zh":"會議將在早上九點半開始。","opts":["in","on","at","for"],"a":2,"guide":[{"q":"9:30 A.M. 是日期、月份還是時刻？","en":"Is 9:30 A.M. a date, a month, or a clock time?","opts":["日期","時刻","月份"],"a":1,"say":"9:30 是時刻，時刻前用 at。"}],"why_zh":"具體時刻前用 at。on 用在日期或星期，in 用在月份或年份。","why_en":"We use at with clock times."},{"lvl":700,"s":"The annual sale begins ___ Monday.","zh":"年度特賣會在星期一開始。","opts":["on","in","at","to"],"a":0,"guide":[{"q":"Monday 是星期幾，還是月份？","en":"Is Monday a day or a month?","opts":["月份","星期幾"],"a":1,"say":"星期幾前面用 on。"}],"why_zh":"星期和日期前用 on。in 用在月份、年份，at 用在時刻。","why_en":"We use on with days of the week."},{"lvl":700,"s":"Please submit your expense report ___ Friday.","zh":"請在星期五之前繳交你的費用報告。","opts":["until","in","at","by"],"a":3,"guide":[{"q":"「繳交」是一次就完成的動作，還是持續的動作？","en":"Is 'submit' a one-time action or a continuing action?","opts":["一次完成","持續"],"a":0,"say":"繳交是一次完成的動作，要表示「最晚期限」。"},{"q":"表示「在…之前完成」的是哪一個？","en":"Which word means 'no later than'?","opts":["until","by"],"a":1,"say":"by 表示截止期限。"}],"why_zh":"by + 時間表示「最晚在…之前」，搭配 submit 這種一次完成的動作。until 要搭配持續的動作，例如 stay、wait。","why_en":"By shows a deadline for a one-time action like submit."},{"lvl":700,"s":"Ms. Chang is in charge ___ the marketing department.","zh":"張小姐負責行銷部門。","opts":["for","of","with","to"],"a":1,"guide":[{"q":"「負責…」的固定說法是 in charge ___？","en":"What is the fixed phrase for 'responsible for'?","opts":["in charge of","in charge for"],"a":0,"say":"固定搭配是 in charge of。"}],"why_zh":"in charge of 是固定片語，表示「負責」。不要和 responsible for 混淆而選 for。","why_en":"The fixed phrase is in charge of."},{"lvl":700,"s":"I am writing ___ behalf of the hiring committee.","zh":"我代表招募委員會寫這封信。","opts":["with","at","on","by"],"a":2,"guide":[{"q":"「代表某人」的固定片語是？","en":"What is the fixed phrase for 'representing someone'?","opts":["by behalf of","on behalf of"],"a":1,"say":"多益常考的是 on behalf of。"}],"why_zh":"on behalf of 表示「代表」，是固定搭配。with、at、by 都不能和 behalf 搭配。","why_en":"The fixed phrase is on behalf of."},{"lvl":700,"s":"The store will remain open ___ 10 P.M. tonight.","zh":"店家今晚會一直營業到晚上十點。","opts":["until","by","on","in"],"a":0,"guide":[{"q":"remain open 是一次的動作，還是持續的狀態？","en":"Is 'remain open' a one-time action or a continuing state?","opts":["持續的狀態","一次的動作"],"a":0,"say":"持續開著到某個時間點，用 until。"}],"why_zh":"until 表示狀態「一直持續到」某時間，搭配 remain open。by 表示期限，用在一次完成的動作。","why_en":"Until shows a state continuing up to a time."},{"lvl":700,"s":"Our office is located ___ the third floor.","zh":"我們的辦公室位於三樓。","opts":["in","on","at","to"],"a":1,"guide":[{"q":"樓層的介系詞要用哪一個？","en":"Which preposition do we use with floors?","opts":["in","on"],"a":1,"say":"在某一樓層用 on，例如 on the third floor。"}],"why_zh":"樓層前用 on。in 用在建築物或房間「裡面」，例如 in the building。","why_en":"We say on the third floor."},{"lvl":700,"s":"The new product will be launched ___ March.","zh":"新產品將在三月推出。","opts":["on","at","to","in"],"a":3,"guide":[{"q":"March 是日期還是月份？","en":"Is March a date or a month?","opts":["月份","日期"],"a":0,"say":"只有月份沒有日期，用 in。"}],"why_zh":"月份前用 in。如果有日期，例如 March 5，才用 on。","why_en":"We use in with months."},{"lvl":700,"s":"Customer complaints have decreased ___ 20 percent this year.","zh":"今年顧客抱怨減少了百分之二十。","opts":["by","at","on","for"],"a":0,"guide":[{"q":"20 percent 表示的是「變化的幅度」還是「時間」？","en":"Does '20 percent' show the amount of change or a time?","opts":["時間","變化幅度"],"a":1,"say":"表示增減的幅度用 by。"}],"why_zh":"increase / decrease by + 數字表示「增減了多少」。at 表示在某個數值，不表示變化量。","why_en":"By shows the amount of change."},{"lvl":700,"s":"Please keep your receipt ___ case you need to return the item.","zh":"請保留收據，以防您需要退貨。","opts":["on","at","in","for"],"a":2,"guide":[{"q":"「以防萬一」的固定片語是？","en":"What is the fixed phrase for 'just in case'?","opts":["on case","in case"],"a":1,"say":"固定說法是 in case。"}],"why_zh":"in case 表示「以防」，是固定搭配。on、at、for 都不能和 case 組成這個意思。","why_en":"The fixed phrase is in case."},{"lvl":900,"s":"All travel expenses must be approved by a department head ___ advance, according to the company's revised reimbursement policy.","zh":"根據公司修訂後的報銷政策，所有差旅費用都必須事先經部門主管核准。","opts":["on","in","at","by"],"a":1,"guide":[{"q":"「事先、預先」的固定片語是？","en":"What is the fixed phrase for 'beforehand'?","opts":["in advance","by advance"],"a":0,"say":"固定片語是 in advance。"},{"q":"句中前面已經有一個 by，它是在表示什麼？","en":"There is already a 'by' earlier. What does it show?","opts":["期限","被動的動作者"],"a":1,"say":"by a department head 表示由主管核准，和空格無關，別被干擾。"}],"why_zh":"in advance 表示「事先」。前面的 by a department head 是被動語態的動作者，容易誘導選 by，但 by advance 不是正確說法。","why_en":"The fixed phrase is in advance."},{"lvl":900,"s":"The warehouse has been operating ___ full capacity since the holiday shopping season began in November.","zh":"自從十一月假期購物季開始以來，倉庫一直以滿載產能運作。","opts":["in","on","for","at"],"a":3,"guide":[{"q":"「以滿載產能、全速」的固定片語是？","en":"What is the fixed phrase for 'at maximum output'?","opts":["in full capacity","at full capacity"],"a":1,"say":"固定說法是 at full capacity。"}],"why_zh":"at full capacity 表示「以最大產能」，at 常用於速度、比率、程度。in、on、for 都不搭配 capacity 這個意思。","why_en":"The fixed phrase is at full capacity."},{"lvl":900,"s":"___ the terms of the contract, the supplier must replace any damaged goods within 30 days of delivery.","zh":"根據合約條款，供應商必須在交貨後 30 天內更換任何受損商品。","opts":["Under","Over","Among","Into"],"a":0,"guide":[{"q":"合約條款和供應商的義務是什麼關係？","en":"How are the contract terms related to the supplier's duty?","opts":["條款規定了義務","沒有關係"],"a":0,"say":"是「依據、在…規定之下」，用 under。"}],"why_zh":"under the terms of the contract 表示「根據合約條款」，under 表示受某規定約束。among 用在三者以上之間，意思不合。","why_en":"Under the terms of means 'according to the rules of'."},{"lvl":900,"s":"Mr. Huang has worked as a financial analyst ___ Sunrise Investment Group for more than ten years.","zh":"黃先生在旭日投資集團擔任財務分析師已經超過十年。","opts":["to","into","for","about"],"a":2,"guide":[{"q":"「替某公司工作」英文怎麼說？","en":"How do we say 'work for a company'?","opts":["work to a company","work for a company"],"a":1,"say":"替公司工作用 work for。"}],"why_zh":"work for + 公司表示「為…工作、受雇於」。to、into、about 都不能表示受雇於某公司。","why_en":"We say work for a company."},{"lvl":900,"s":"Applications received ___ the May 31 deadline will not be considered by the selection committee.","zh":"五月三十一日截止期限之後收到的申請，甄選委員會將不予考慮。","opts":["between","after","among","upon"],"a":1,"guide":[{"q":"「不予考慮」的申請，是在截止前還是截止後收到的？","en":"Were the rejected applications received before or after the deadline?","opts":["截止前","截止後"],"a":1,"say":"不被考慮表示是遲交的，也就是截止後。"},{"q":"between 需要幾個時間點？","en":"How many points does 'between' need?","opts":["兩個","一個"],"a":0,"say":"between 需要兩個時間點（between A and B），這裡只有一個期限。"}],"why_zh":"after the deadline 表示「截止之後」，符合不予考慮的語意。between 要有兩個時間點，among 用在三者以上。","why_en":"Late applications arrive after the deadline."}]},{"id":"compare","title_zh":"比較級與最高級","title_en":"Comparatives and superlatives","icon":"⚖️","pattern":"比較級 + than ／ the + 最高級 ／ as + 原級 + as","rule_zh":"兩者比較用比較級（-er 或 more + 形容詞），後面常接 than。三者以上比較用最高級（the + -est 或 the most + 形容詞）。as ... as 中間要放原級。強調比較級時用 much、far、even、considerably，不能用 very。","rule_en":"Use the comparative (-er / more) with than for two things, and the superlative (the -est / the most) for three or more. Use the base form in as ... as. Use much or far, not very, before a comparative.","spot_zh":"考題線索：看到 than、of all、of the three、as ___ as、much／far ___，就是在考比較級或最高級。","examples":[{"en":"My sister is taller than me.","zh":"我姊姊比我高。"},{"en":"This is the cheapest bakery in our neighborhood.","zh":"這是我們社區最便宜的麵包店。"},{"en":"His dog is as friendly as mine.","zh":"他的狗和我的狗一樣友善。"}],"qs":[{"lvl":700,"s":"Our new laptop model is much ___ than the previous one.","zh":"我們的新款筆電比前一款輕很多。","opts":["light","lighter","lightest","lightly"],"a":1,"guide":[{"q":"空格後面出現哪個關鍵字？","en":"Which key word comes after the blank?","opts":["of all","than"],"a":1,"say":"看到 than，就知道是兩者比較，要用比較級。"}],"why_zh":"than 前面要用比較級 lighter。lightest 是最高級，要搭配 the 和三者以上的比較。","why_en":"Than needs a comparative, so lighter is correct."},{"lvl":700,"s":"Of all the candidates, Mr. Park has the ___ experience in overseas sales.","zh":"在所有應徵者中，朴先生的海外銷售經驗最多。","opts":["more","much","many","most"],"a":3,"guide":[{"q":"句首 Of all the candidates 是在比較幾個人？","en":"How many people are compared in 'Of all the candidates'?","opts":["兩個人","三個人以上"],"a":1,"say":"「所有應徵者中」是三者以上的比較，要用最高級。"},{"q":"the ___ experience 要選哪一個最高級？","en":"Which superlative fits 'the ___ experience'?","opts":["most","more"],"a":0,"say":"much 的最高級是 most，所以是 the most experience。"}],"why_zh":"Of all 表示三者以上比較，要用最高級 the most。more 是比較級，不能搭配 of all。","why_en":"Of all signals a superlative, so the most is correct."},{"lvl":700,"s":"The Bayview is the ___ of the three hotels near the airport.","zh":"Bayview 是機場附近三家飯店中最大的一家。","opts":["large","larger","largest","largely"],"a":2,"guide":[{"q":"of the three hotels 表示比較幾家？","en":"How many hotels are compared?","opts":["三家","兩家"],"a":0,"say":"三家以上的比較要用最高級 the -est。"}],"why_zh":"三家飯店比較要用最高級 the largest。larger 只能用在兩者比較（the larger of the two）。","why_en":"With three hotels we need the superlative: the largest."},{"lvl":700,"s":"The updated software is just as ___ as the old version.","zh":"更新後的軟體和舊版一樣可靠。","opts":["reliable","reliably","more reliable","most reliable"],"a":0,"guide":[{"q":"as ___ as 中間要放什麼形式？","en":"What form goes between as ... as?","opts":["比較級","原級"],"a":1,"say":"as ... as 中間永遠放原級，不加 -er 或 more。"},{"q":"前面的動詞是 is，後面需要形容詞還是副詞？","en":"After 'is', do we need an adjective or an adverb?","opts":["形容詞","副詞"],"a":0,"say":"be 動詞後面接形容詞，所以用 reliable。"}],"why_zh":"as ... as 中間用原級，is 後面接形容詞，所以是 reliable。more reliable 是比較級，不能放在 as ... as 中間。","why_en":"As ... as takes the base adjective: as reliable as."},{"lvl":700,"s":"Sales this quarter were ___ higher than the team had expected.","zh":"這一季的業績比團隊預期的高出許多。","opts":["very","much","most","more"],"a":1,"guide":[{"q":"higher 是原級還是比較級？","en":"Is 'higher' a base form or a comparative?","opts":["原級","比較級"],"a":1,"say":"higher 已經是比較級，前面只能用 much、far 等字來加強。"}],"why_zh":"修飾比較級要用 much（或 far、even）。very 只能修飾原級，more higher 則是重複比較級。","why_en":"Use much, not very, to make a comparative stronger."},{"lvl":700,"s":"The express train is more convenient ___ the bus for most commuters.","zh":"對大多數通勤族來說，快車比公車方便。","opts":["as","that","then","than"],"a":3,"guide":[{"q":"前面的 more convenient 是什麼形式？","en":"What form is 'more convenient'?","opts":["比較級","原級","最高級"],"a":0,"say":"more + 形容詞是比較級，後面要接 than。"}],"why_zh":"比較級 more convenient 後面要接 than。then 是「然後」，拼法很像但意思不同。","why_en":"A comparative is followed by than, not then."},{"lvl":700,"s":"Please submit your expense report no ___ than Friday.","zh":"請最晚在星期五前繳交你的費用報告。","opts":["late","lately","later","latest"],"a":2,"guide":[{"q":"空格後面有 than，前面要放什麼？","en":"There is 'than' after the blank. What do we need?","opts":["比較級","最高級"],"a":0,"say":"than 前面用比較級，no later than 是「不晚於」的固定說法。"}],"why_zh":"no later than 意思是「最晚在……之前」，要用比較級 later。lately 是「最近」，不是比較級。","why_en":"No later than means 'by this time at the latest'."},{"lvl":700,"s":"This year's trade fair attracted ___ visitors than last year's event.","zh":"今年的商展吸引的參觀者比去年多。","opts":["more","many","much","most"],"a":0,"guide":[{"q":"句子後面有 than，要用哪一種形式？","en":"There is 'than' later. Which form do we need?","opts":["原級 many","比較級 more"],"a":1,"say":"有 than 就要用比較級，many 的比較級是 more。"}],"why_zh":"than 前面要用比較級 more。many 是原級，most 是最高級，都不能接 than。","why_en":"Than needs the comparative more."},{"lvl":700,"s":"Our Tokyo office is not as ___ as our Osaka office in December.","zh":"我們東京辦公室在十二月沒有大阪辦公室那麼忙。","opts":["busier","busiest","busily","busy"],"a":3,"guide":[{"q":"not as ___ as 中間要放什麼？","en":"What goes between not as ... as?","opts":["原級形容詞","比較級","副詞"],"a":0,"say":"as ... as 中間放原級，而 is 後面要接形容詞，所以是 busy。"}],"why_zh":"as ... as 中間用原級形容詞 busy。busier 是比較級，要搭配 than；busily 是副詞，不能接在 is 後面。","why_en":"As ... as takes the base adjective busy."},{"lvl":700,"s":"The ___ you register for the seminar, the larger the discount you will receive.","zh":"你越早報名研討會，得到的折扣就越大。","opts":["early","earlier","earliest","earliness"],"a":1,"guide":[{"q":"句子後半是 the larger ...，這是什麼句型？","en":"The second half says 'the larger ...'. What pattern is this?","opts":["the + 最高級","the + 比較級, the + 比較級"],"a":1,"say":"「越……就越……」要用 the + 比較級, the + 比較級。"}],"why_zh":"the + 比較級, the + 比較級 表示「越……越……」，所以前半也要用比較級 earlier。earliest 是最高級，不符合這個句型。","why_en":"The pattern 'the + comparative, the + comparative' needs earlier."},{"lvl":900,"s":"The revised budget is considerably ___ than the original estimate submitted by the finance team last month.","zh":"修訂後的預算比財務團隊上個月提出的原始估算低了許多。","opts":["lower","low","lowest","lowly"],"a":0,"guide":[{"q":"considerably 後面、than 前面，要放什麼形式？","en":"Between 'considerably' and 'than', which form is needed?","opts":["原級","比較級"],"a":1,"say":"considerably 可以加強比較級，加上 than，答案一定是比較級。"}],"why_zh":"considerably 修飾比較級，後面又有 than，所以用 lower。low 是原級，不能直接接 than。","why_en":"Considerably + comparative + than: considerably lower than."},{"lvl":900,"s":"Of the two applicants interviewed for the position, Ms. Tanaka is clearly the ___ qualified.","zh":"在面試這個職位的兩位應徵者中，田中小姐顯然比較符合資格。","opts":["most","much","more","many"],"a":2,"guide":[{"q":"Of the two applicants 是比較幾個人？","en":"How many applicants are compared?","opts":["三個人以上","兩個人"],"a":1,"say":"只有兩個人比較時，要用 the + 比較級（the more ...）。"}],"why_zh":"「兩者之中比較……的那一個」要用 the + 比較級，所以是 the more qualified。看到 the 就選 most 是常見陷阱，但 most 用於三者以上。","why_en":"With only two people, use the + comparative: the more qualified."},{"lvl":900,"s":"Thanks to its automated shelving system, the new warehouse can store twice as ___ inventory as the old facility.","zh":"多虧自動化貨架系統，新倉庫能存放的庫存量是舊倉庫的兩倍。","opts":["many","more","most","much"],"a":3,"guide":[{"q":"twice as ___ as 中間要放原級還是比較級？","en":"Base form or comparative between twice as ... as?","opts":["原級","比較級"],"a":0,"say":"倍數 + as ... as 中間仍然用原級，所以排除 more 和 most。"},{"q":"inventory（庫存）是可數還是不可數名詞？","en":"Is 'inventory' countable or uncountable here?","opts":["可數","不可數"],"a":1,"say":"inventory 在這裡是不可數名詞，要用 much 而不是 many。"}],"why_zh":"as ... as 中間用原級，inventory 不可數，所以是 much。many 只能修飾可數複數名詞。","why_en":"Inventory is uncountable, so we say twice as much inventory as."},{"lvl":900,"s":"Customer satisfaction scores this quarter were by ___ the highest the company has ever recorded.","zh":"這一季的顧客滿意度分數是公司有史以來最高的，遙遙領先。","opts":["far","much","very","more"],"a":0,"guide":[{"q":"the highest 是比較級還是最高級？","en":"Is 'the highest' a comparative or a superlative?","opts":["比較級","最高級"],"a":1,"say":"the highest 是最高級，可以用固定片語 by far 來加強。"}],"why_zh":"by far + 最高級表示「遠遠是最……的」，是固定用法。by much 和 by very 都不是正確的片語。","why_en":"By far is the set phrase used to strengthen a superlative."},{"lvl":900,"s":"The updated model consumes ___ less energy than its predecessor, making it ideal for small offices.","zh":"新款機型比前一代耗電少得多，非常適合小型辦公室。","opts":["significance","significant","significantly","more significant"],"a":2,"guide":[{"q":"空格後面的 less 是什麼詞性？","en":"What part of speech is 'less' here?","opts":["名詞","比較級形容詞","動詞"],"a":1,"say":"less 是比較級，修飾它要用副詞。"},{"q":"哪一個選項是副詞？","en":"Which option is an adverb?","opts":["significantly","significant"],"a":0,"say":"-ly 結尾的 significantly 是副詞，可以加強比較級。"}],"why_zh":"修飾比較級 less 要用副詞 significantly（大幅地）。significant 是形容詞，more significant 則會形成兩個比較級。","why_en":"An adverb like significantly can strengthen a comparative."}]},{"id":"pronoun","title_zh":"代名詞","title_en":"Pronouns","icon":"👤","pattern":"主格 he ／ 受格 him ／ 所有格 his + 名詞 ／ 所有代名詞 his ／ 反身 himself","rule_zh":"當主詞用主格（I, he, they），在動詞或介系詞後用受格（me, him, them）。名詞前面用所有格（my, its, their），單獨使用表示「……的東西」用所有代名詞（mine, yours）。by oneself 表示「獨自」，反身代名詞也可強調「親自」。單數名詞用 its，複數名詞用 their；one／ones 代替前面提過的可數名詞。","rule_en":"Use subject forms before verbs, object forms after verbs and prepositions, and possessive forms before nouns. Its goes with singular nouns and their with plural nouns. Reflexives (himself) mean 'alone' or 'personally', and one/ones replace a countable noun.","spot_zh":"考題線索：四個選項是同一個人稱的不同格（he / him / his / himself），先看空格是在動詞前、動詞後、名詞前，還是句尾單獨出現。","examples":[{"en":"She made the cake by herself.","zh":"她自己一個人做了這個蛋糕。"},{"en":"This bag is mine, and that one is yours.","zh":"這個包包是我的，那個是你的。"},{"en":"My cat loves its new bed.","zh":"我的貓很喜歡牠的新床。"}],"qs":[{"lvl":700,"s":"Ms. Lee asked ___ assistant to book a meeting room for Thursday.","zh":"李小姐請她的助理預約星期四的會議室。","opts":["she","her","hers","herself"],"a":1,"guide":[{"q":"空格後面緊接著什麼？","en":"What comes right after the blank?","opts":["動詞","名詞 assistant"],"a":1,"say":"名詞前面要用所有格，表示「誰的」助理。"}],"why_zh":"名詞 assistant 前面要用所有格 her。hers 是所有代名詞，後面不能再接名詞。","why_en":"A possessive adjective (her) comes before a noun."},{"lvl":700,"s":"Mr. Chen prepared the entire presentation by ___ over the weekend.","zh":"陳先生週末獨自準備了整份簡報。","opts":["him","his","himself","he"],"a":2,"guide":[{"q":"by ___ 在這裡是什麼意思？","en":"What does 'by ___' mean here?","opts":["獨自一人","在他旁邊"],"a":0,"say":"by + 反身代名詞 = 獨自、靠自己。"}],"why_zh":"by himself 表示「獨自」，主詞是 Mr. Chen，所以用 himself。by him 會指「由另一位男士」或「在他旁邊」，不能表示陳先生自己獨力完成。","why_en":"By himself means 'alone, without help'."},{"lvl":700,"s":"The company announced that ___ profits rose by 10 percent last year.","zh":"公司宣布其去年的利潤成長了百分之十。","opts":["it","it's","itself","its"],"a":3,"guide":[{"q":"空格後面的 profits 是什麼詞性？","en":"What is 'profits'?","opts":["名詞","動詞"],"a":0,"say":"名詞前面要用所有格。"},{"q":"it's 是什麼的縮寫？","en":"What is 'it's' short for?","opts":["it is","it 的所有格"],"a":0,"say":"it's = it is，所有格是沒有撇號的 its。"}],"why_zh":"company 是單數，名詞 profits 前面用所有格 its。it's 是 it is 的縮寫，常被誤選。","why_en":"Its is the possessive; it's means 'it is'."},{"lvl":700,"s":"Please give the signed documents to Mr. Wang or ___ before noon.","zh":"請在中午前把簽好的文件交給王先生或我。","opts":["me","I","my","mine"],"a":0,"guide":[{"q":"空格前面的 to 是什麼？","en":"What is 'to' before the blank?","opts":["連接詞","介系詞"],"a":1,"say":"介系詞後面要接受格，即使中間有 Mr. Wang or 也一樣。"}],"why_zh":"介系詞 to 後面要用受格 me。很多人覺得 I 比較正式，但 I 是主格，不能放在介系詞後面。","why_en":"After a preposition we use the object form me."},{"lvl":700,"s":"The blue umbrella by the door is mine, and the black one is ___.","zh":"門邊的藍色雨傘是我的，黑色那把是你的。","opts":["you","your","yourself","yours"],"a":3,"guide":[{"q":"空格後面還有名詞嗎？","en":"Is there a noun after the blank?","opts":["有","沒有"],"a":1,"say":"空格後面沒有名詞，要用能單獨使用的所有代名詞。"}],"why_zh":"空格單獨表示「你的（雨傘）」，要用所有代名詞 yours，對應前面的 mine。your 後面必須接名詞。","why_en":"Yours stands alone and means 'your umbrella'."},{"lvl":700,"s":"Ms. Park and ___ will lead the training session for new staff.","zh":"朴小姐和我將帶領新員工的訓練課程。","opts":["I","me","my","mine"],"a":0,"guide":[{"q":"Ms. Park and ___ 在句子裡是什麼角色？","en":"What role does 'Ms. Park and ___' play?","opts":["主詞","受詞"],"a":0,"say":"它在動詞 will lead 前面，是主詞，所以用主格。"}],"why_zh":"空格是主詞的一部分，要用主格 I。me 是受格，不能當主詞。","why_en":"The blank is part of the subject, so we use I."},{"lvl":700,"s":"The managers met the visiting clients and gave ___ a tour of the factory.","zh":"經理們接待來訪的客戶，並帶他們參觀工廠。","opts":["they","their","them","theirs"],"a":2,"guide":[{"q":"空格在動詞 gave 的前面還是後面？","en":"Is the blank before or after the verb 'gave'?","opts":["前面","後面"],"a":1,"say":"動詞後面當受詞，要用受格。"}],"why_zh":"gave 後面需要受詞，指客戶要用受格 them。their 是所有格，後面要接名詞。","why_en":"After the verb gave we need the object form them."},{"lvl":700,"s":"___ who wish to attend the workshop should sign up by Friday.","zh":"想參加研習會的人應在星期五前報名。","opts":["They","Those","Them","These"],"a":1,"guide":[{"q":"空格後面接的 who 是什麼？","en":"What is 'who' after the blank?","opts":["關係代名詞","疑問詞"],"a":0,"say":"「……的人」固定說成 those who。"}],"why_zh":"those who 表示「那些……的人」，是固定用法。They who 和 These who 都不是正確的說法。","why_en":"Those who means 'the people who'."},{"lvl":700,"s":"All employees must keep ___ ID badges visible at all times.","zh":"所有員工必須隨時讓識別證保持可見。","opts":["they","them","theirs","their"],"a":3,"guide":[{"q":"空格後面是什麼？","en":"What follows the blank?","opts":["名詞 ID badges","動詞"],"a":0,"say":"名詞前要用所有格。"},{"q":"employees 是單數還是複數？","en":"Is 'employees' singular or plural?","opts":["單數","複數"],"a":1,"say":"複數主詞用 their。"}],"why_zh":"名詞 ID badges 前要用所有格，主詞 employees 是複數，所以用 their。theirs 是所有代名詞，後面不接名詞。","why_en":"Their is the possessive for a plural noun."},{"lvl":700,"s":"Mr. Ford said that ___ will train the new sales staff himself.","zh":"福特先生說他會親自訓練新的業務人員。","opts":["him","he","his","himself"],"a":1,"guide":[{"q":"空格後面緊接著什麼？","en":"What comes right after the blank?","opts":["名詞","助動詞 will"],"a":1,"say":"will 前面需要主詞，要用主格。"}],"why_zh":"that 子句中的主詞要用主格 he。himself 不能單獨當主詞，句尾的 himself 只是強調「親自」。","why_en":"The clause needs a subject, so he is correct."},{"lvl":900,"s":"Although the two firms compete in the same market, ___ products target very different groups of customers.","zh":"雖然這兩家公司在同一個市場競爭，但它們的產品鎖定的客群非常不同。","opts":["their","its","they","theirs"],"a":0,"guide":[{"q":"products 屬於誰？","en":"Whose products are they?","opts":["the two firms","the same market"],"a":0,"say":"產品屬於兩家公司，是複數。"},{"q":"複數名詞的所有格是 its 還是 their？","en":"For a plural owner, its or their?","opts":["its","their"],"a":1,"say":"複數名詞要用 their。"}],"why_zh":"the two firms 是複數，名詞 products 前要用 their。its 是單數所有格，是本題陷阱。","why_en":"The two firms is plural, so we use their."},{"lvl":900,"s":"Ms. Rivera prefers to handle serious client complaints ___ rather than pass them on to her team.","zh":"里維拉小姐比較喜歡親自處理嚴重的客訴，而不是交給她的團隊。","opts":["her","hers","herself","she"],"a":2,"guide":[{"q":"句子已經有完整的主詞和受詞了嗎？","en":"Does the clause already have a full subject and object?","opts":["有，空格只是補充","沒有，缺受詞"],"a":0,"say":"handle complaints 已經完整，空格是用來強調「親自」。"}],"why_zh":"句子結構完整，用反身代名詞 herself 強調「親自」處理。her 和 she 放在這裡會多出一個受詞或主詞。","why_en":"Herself emphasizes that she does it personally."},{"lvl":900,"s":"The hotel renovated all of ___ guest rooms last year, and the results have impressed returning visitors.","zh":"這家飯店去年翻修了所有客房，成果讓回訪的旅客印象深刻。","opts":["it","its","their","it's"],"a":1,"guide":[{"q":"guest rooms 屬於誰？","en":"Who owns the guest rooms?","opts":["the hotel","visitors"],"a":0,"say":"房間屬於 the hotel，是單數。"},{"q":"單數的「它的」要怎麼寫？","en":"How do we write the singular possessive 'its'?","opts":["it's","its"],"a":1,"say":"所有格 its 沒有撇號。"}],"why_zh":"the hotel 是單數，所以用 its。their 會誤以為是 rooms 或 visitors 的所有格，it's 則是 it is。","why_en":"The hotel is singular, so its is correct."},{"lvl":900,"s":"The old chairs in the lobby were uncomfortable, but the new ___ that arrived yesterday are much better.","zh":"大廳的舊椅子坐起來不舒服，但昨天送到的新椅子好多了。","opts":["one","it","ones","them"],"a":2,"guide":[{"q":"空格代替前面的哪個名詞？","en":"Which noun does the blank replace?","opts":["chairs","lobby"],"a":0,"say":"空格代替 chairs，是可數複數名詞。"},{"q":"後面的動詞是 are 還是 is？","en":"Is the verb 'are' or 'is'?","opts":["is","are"],"a":1,"say":"動詞是 are，要用複數的 ones。"}],"why_zh":"形容詞 new 後面要用 one／ones 代替名詞，動詞 are 是複數，所以用 ones。one 是單數，和 are 不一致；them 不能接在形容詞後。","why_en":"Ones replaces a plural countable noun after an adjective."},{"lvl":900,"s":"We can offer advice, but the final decision on whether to extend the contract is ultimately ___, not the board's.","zh":"我們可以提供建議，但是否續約的最終決定權在你，而不是董事會。","opts":["your","you","yourself","yours"],"a":3,"guide":[{"q":"後面的 the board's 是什麼形式？","en":"What form is 'the board's'?","opts":["所有格，單獨使用","主格"],"a":0,"say":"the board's 是單獨使用的所有格，前面也要對應「……的」。"}],"why_zh":"is 後面單獨表示「你的（決定）」，要用所有代名詞 yours，與 the board's 對應。your 後面必須接名詞。","why_en":"Yours stands alone and means 'your decision'."}]},{"id":"quant","title_zh":"數量詞","title_en":"Quantifiers","icon":"🔢","pattern":"each／every + 單數名詞 ／ many, a few + 可數複數 ／ much, a little + 不可數","rule_zh":"each、every 接單數可數名詞，動詞用單數；all、most、many 接複數名詞。many、few、a few 修飾可數名詞，much、little、a little 修飾不可數名詞。few／little 表示「幾乎沒有」（負面），a few／a little 表示「有一些」（正面）。a number of + 複數名詞 + 複數動詞；the number of + 複數名詞 + 單數動詞。","rule_en":"Each and every take a singular noun. Many and (a) few go with countable nouns; much and (a) little go with uncountable nouns. A number of takes a plural verb, but the number of takes a singular verb.","spot_zh":"考題線索：四個選項都是數量詞（each / all / many / much），先判斷後面名詞是單數、複數還是不可數，再看動詞單複數。","examples":[{"en":"Every student has a locker.","zh":"每個學生都有一個置物櫃。"},{"en":"I have a few friends in Tainan.","zh":"我在台南有幾個朋友。"},{"en":"There is a little milk in the fridge.","zh":"冰箱裡還有一點牛奶。"}],"qs":[{"lvl":700,"s":"___ employee must wear a name badge inside the building.","zh":"每位員工在大樓內都必須配戴名牌。","opts":["All","Every","Many","Few"],"a":1,"guide":[{"q":"employee 是單數還是複數？","en":"Is 'employee' singular or plural?","opts":["複數","單數"],"a":1,"say":"employee 沒有 -s，是單數。"},{"q":"哪個數量詞後面接單數名詞？","en":"Which quantifier takes a singular noun?","opts":["every","all","many"],"a":0,"say":"every 後面接單數名詞。"}],"why_zh":"every 接單數名詞 employee。All、Many、Few 都要接複數名詞（employees）。","why_en":"Every is followed by a singular noun."},{"lvl":700,"s":"There is only ___ time left before the meeting, so please hurry.","zh":"離會議開始只剩一點時間了，請快一點。","opts":["a few","few","a little","many"],"a":2,"guide":[{"q":"time 在這裡是可數還是不可數？","en":"Is 'time' countable or uncountable here?","opts":["可數","不可數"],"a":1,"say":"表示「時間」的 time 是不可數名詞。"}],"why_zh":"time（時間）不可數，要用 a little；動詞 is 也是單數。a few 和 many 只能修飾可數複數名詞。","why_en":"Time is uncountable, so we use a little."},{"lvl":700,"s":"___ of the staff members attended the safety training session.","zh":"大部分的員工都參加了安全訓練課程。","opts":["Every","Much","Almost","Most"],"a":3,"guide":[{"q":"空格後面是 of the + 什麼名詞？","en":"What noun follows 'of the'?","opts":["可數複數 staff members","不可數名詞"],"a":0,"say":"of the + 複數名詞前面可以用 most、many、all 等。"}],"why_zh":"Most of the + 複數名詞表示「大部分的……」。Every 不能直接接 of；Almost 是副詞，不能當主詞；Much 用於不可數名詞。","why_en":"Most of the + plural noun means 'the majority of'."},{"lvl":700,"s":"How ___ information do you need for the sales report?","zh":"你的業務報告需要多少資訊？","opts":["many","much","few","a few"],"a":1,"guide":[{"q":"information 是可數還是不可數？","en":"Is 'information' countable or uncountable?","opts":["不可數","可數"],"a":0,"say":"information 是不可數名詞，沒有複數形。"}],"why_zh":"不可數名詞 information 要用 How much。How many 只能接可數複數名詞。","why_en":"Information is uncountable, so we ask how much."},{"lvl":700,"s":"___ number of customers have asked about the new product line.","zh":"有許多顧客詢問了新的產品系列。","opts":["A","The","Every","Much"],"a":0,"guide":[{"q":"句子的動詞是 have 還是 has？","en":"Is the verb 'have' or 'has'?","opts":["has（單數）","have（複數）"],"a":1,"say":"動詞是複數 have。"},{"q":"哪一個搭配複數動詞？","en":"Which one takes a plural verb?","opts":["a number of","the number of"],"a":0,"say":"a number of =「許多」，接複數動詞。"}],"why_zh":"a number of 表示「許多」，後接複數動詞 have。the number of 表示「……的數量」，要接單數動詞 has。","why_en":"A number of means 'many' and takes a plural verb."},{"lvl":700,"s":"The number of job applicants ___ increased sharply this year.","zh":"今年應徵者的人數大幅增加。","opts":["have","are","has","were"],"a":2,"guide":[{"q":"這句的主詞核心是 the number 還是 applicants？","en":"Is the main subject 'the number' or 'applicants'?","opts":["applicants","the number"],"a":1,"say":"主詞是 the number（數量），是單數。"}],"why_zh":"the number of 的主詞是 number，要用單數動詞 has。have 是被 applicants 誤導的陷阱。","why_en":"The number of takes a singular verb: has."},{"lvl":700,"s":"___ of the rooms on this floor has a view of the ocean.","zh":"這層樓的每一間房間都看得到海景。","opts":["Every","Each","All","Many"],"a":1,"guide":[{"q":"動詞是 has 還是 have？","en":"Is the verb 'has' or 'have'?","opts":["has（單數）","have（複數）"],"a":0,"say":"動詞 has 是單數，所以 All 和 Many 不行。"},{"q":"Every 和 Each 哪一個可以直接接 of the？","en":"Which one can be followed directly by 'of the'?","opts":["Every","Each"],"a":1,"say":"Each of the + 複數名詞是正確的，every 不能直接接 of。"}],"why_zh":"Each of the + 複數名詞 + 單數動詞。Every 不能直接接 of；All、Many 要接複數動詞 have。","why_en":"Each of the + plural noun takes a singular verb."},{"lvl":700,"s":"Unfortunately, very ___ people came to the product launch, so it was considered a failure.","zh":"很遺憾，幾乎沒什麼人來參加產品發表會，所以被視為失敗。","opts":["a few","little","much","few"],"a":3,"guide":[{"q":"people 是可數還是不可數？","en":"Is 'people' countable or uncountable?","opts":["可數","不可數"],"a":0,"say":"people 是可數複數，排除 little 和 much。"},{"q":"Unfortunately 和 failure 表示人多還是人少？","en":"Do 'unfortunately' and 'failure' suggest many or almost no people?","opts":["幾乎沒有人","有一些人"],"a":0,"say":"負面意思用 few（幾乎沒有），而且 very 只能放在 few 前面。"}],"why_zh":"very few + 可數複數表示「非常少」，符合負面語意。very a few 不是正確用法，little 和 much 修飾不可數名詞。","why_en":"Very few means 'almost no' and goes with countable nouns."},{"lvl":700,"s":"We need ___ more chairs for the meeting room this afternoon.","zh":"今天下午會議室還需要幾張椅子。","opts":["a few","a little","much","little"],"a":0,"guide":[{"q":"chairs 是可數還是不可數？","en":"Is 'chairs' countable or uncountable?","opts":["不可數","可數複數"],"a":1,"say":"chairs 是可數複數名詞。"}],"why_zh":"可數複數名詞 chairs 要用 a few（幾個）。a little、much、little 都只能修飾不可數名詞。","why_en":"A few goes with plural countable nouns like chairs."},{"lvl":700,"s":"___ the employees are invited to the year-end party at the Grand Hotel.","zh":"所有員工都受邀參加在君悅飯店舉辦的尾牙。","opts":["Every","Each","All","Much"],"a":2,"guide":[{"q":"空格後面是 the employees，動詞是 are，這是單數還是複數？","en":"With 'the employees ... are', is it singular or plural?","opts":["複數","單數"],"a":0,"say":"複數名詞和複數動詞，要用 all。"}],"why_zh":"All (of) the + 複數名詞，動詞用 are。Every 和 Each 不能直接接 the，也要搭配單數名詞。","why_en":"All the + plural noun takes a plural verb."},{"lvl":900,"s":"Although ___ progress has been made on the merger, several legal issues remain unresolved.","zh":"雖然合併案已有些許進展，但仍有幾個法律問題尚未解決。","opts":["a few","a little","many","few"],"a":1,"guide":[{"q":"progress 是可數還是不可數？","en":"Is 'progress' countable or uncountable?","opts":["可數","不可數"],"a":1,"say":"progress（進展）是不可數名詞，動詞也用單數 has。"}],"why_zh":"不可數名詞 progress 要用 a little（一些）。a few、many、few 都修飾可數複數名詞。","why_en":"Progress is uncountable, so a little is correct."},{"lvl":900,"s":"Almost ___ applicant for the marketing position had previous experience working with international clients.","zh":"幾乎每位應徵行銷職位的人都有與國際客戶合作的經驗。","opts":["every","all","most","each"],"a":0,"guide":[{"q":"applicant 是單數還是複數？","en":"Is 'applicant' singular or plural?","opts":["單數","複數"],"a":0,"say":"單數名詞前面只能用 every 或 each，排除 all 和 most。"},{"q":"almost 可以修飾 every 還是 each？","en":"Can 'almost' go with every or each?","opts":["each","every"],"a":1,"say":"almost every 是正確搭配，almost each 不自然也不正確。"}],"why_zh":"almost every + 單數名詞表示「幾乎每一個」。almost each 不是正確搭配；all 和 most 要接複數名詞。","why_en":"We say almost every, not almost each, before a singular noun."},{"lvl":900,"s":"___ of the information in the current brochure is outdated and needs to be revised before the trade show.","zh":"目前手冊中有很多資訊已經過時，需要在商展前修改。","opts":["Many","Few","Every","Much"],"a":3,"guide":[{"q":"the information 是可數還是不可數？","en":"Is 'the information' countable or uncountable?","opts":["不可數","可數"],"a":0,"say":"information 不可數，動詞也是單數 is。"}],"why_zh":"Much of the + 不可數名詞 + 單數動詞。Many 和 Few 用於可數複數名詞；Every 不能接 of。","why_en":"Much of the + uncountable noun takes a singular verb."},{"lvl":900,"s":"The number of overseas visitors to the museum ___ steadily since the new exhibition opened in March.","zh":"自從新展覽三月開幕以來，博物館的海外遊客人數穩定成長。","opts":["have risen","are rising","has risen","rise"],"a":2,"guide":[{"q":"主詞是 the number 還是 visitors？","en":"Is the subject 'the number' or 'visitors'?","opts":["visitors","the number"],"a":1,"say":"主詞是 the number，要用單數動詞。"},{"q":"since + 過去時間點，要用什麼時態？","en":"With 'since + a past time', which tense?","opts":["現在完成式","簡單現在式"],"a":0,"say":"since 搭配現在完成式，所以是 has risen。"}],"why_zh":"the number of 接單數動詞，加上 since 要用現在完成式，所以是 has risen。have risen 是被 visitors 誤導的陷阱。","why_en":"The number of is singular, and since needs the present perfect."},{"lvl":900,"s":"Only ___ of the shipments were delayed by the storm, so most customers received their orders on time.","zh":"只有少數幾批貨因暴風雨延誤，所以大多數顧客都準時收到訂單。","opts":["a little","much","every","a few"],"a":3,"guide":[{"q":"shipments 是可數還是不可數？","en":"Is 'shipments' countable or uncountable?","opts":["不可數","可數複數"],"a":1,"say":"shipments 是可數複數，動詞也是 were。"}],"why_zh":"only a few of the + 可數複數名詞表示「只有少數幾個」。a little 和 much 用於不可數名詞，every 不能接 of。","why_en":"A few of the + plural countable noun means 'a small number of'."}]},{"id":"article","title_zh":"可數、不可數與冠詞","title_en":"Countable and uncountable nouns, articles","icon":"📦","pattern":"a／an + 單數可數名詞 ／ 不可數名詞（無 -s，不加 a/an）／ the + 特定的人事物","rule_zh":"單數可數名詞前面一定要有冠詞或限定詞（a、an、the、my 等）。不可數名詞（information、equipment、advice、furniture、baggage）沒有複數形，前面不能加 a／an，動詞用單數。a 用在子音開頭的音前，an 用在母音開頭的音前（an hour）。說話雙方都知道是哪一個、或獨一無二的東西，用 the。","rule_en":"A singular countable noun needs a, an, the or another determiner. Uncountable nouns like information, equipment and advice have no plural and never take a/an. Use the for something specific or already known.","spot_zh":"考題線索：選項是同一個名詞的單複數（equipment / equipments）或是 a / an / the，先判斷名詞可不可數，再看是不是特定的東西。","examples":[{"en":"Can you give me some advice?","zh":"你可以給我一些建議嗎？"},{"en":"I ate an apple and a banana.","zh":"我吃了一顆蘋果和一根香蕉。"},{"en":"Please close the window.","zh":"請把窗戶關上。"}],"qs":[{"lvl":700,"s":"We need more ___ before we make a final decision.","zh":"在做出最後決定前，我們需要更多資訊。","opts":["informations","information","an information","the informations"],"a":1,"guide":[{"q":"information 是可數還是不可數？","en":"Is 'information' countable or uncountable?","opts":["可數","不可數"],"a":1,"say":"information 是不可數名詞，不能加 -s，也不能加 an。"}],"why_zh":"information 不可數，沒有複數形，所以是 more information。informations 是台灣學生常見的錯誤。","why_en":"Information is uncountable, so it has no -s."},{"lvl":700,"s":"The new branch office will need a lot of ___ before it opens.","zh":"新分公司開幕前需要大量家具。","opts":["furnitures","a furniture","furnish","furniture"],"a":3,"guide":[{"q":"a lot of 後面要接名詞還是動詞？","en":"Does 'a lot of' take a noun or a verb?","opts":["動詞","名詞"],"a":1,"say":"a lot of 後面接名詞，所以 furnish（動詞）不行。"},{"q":"furniture 可以加 -s 嗎？","en":"Can 'furniture' take -s?","opts":["可以","不可以"],"a":1,"say":"furniture 是不可數名詞，不加 -s。"}],"why_zh":"furniture 是不可數名詞，不能加 -s 或 a。furnish 是動詞「裝設家具」，不能接在 a lot of 後面。","why_en":"Furniture is uncountable, so we say a lot of furniture."},{"lvl":700,"s":"Ms. Lin gave me ___ useful advice about the job interview.","zh":"林小姐給了我一些關於工作面試的實用建議。","opts":["a","an","some","many"],"a":2,"guide":[{"q":"advice 是可數還是不可數？","en":"Is 'advice' countable or uncountable?","opts":["不可數","可數"],"a":0,"say":"advice 不可數，不能用 a／an 或 many。"}],"why_zh":"advice 是不可數名詞，前面可用 some。a 和 many 只能用在可數名詞前。","why_en":"Advice is uncountable, so we use some, not a or many."},{"lvl":700,"s":"It took us almost ___ hour to get to the airport by taxi.","zh":"我們搭計程車花了將近一個小時才到機場。","opts":["a","an","the","some"],"a":1,"guide":[{"q":"hour 的第一個發音是什麼？","en":"What is the first sound of 'hour'?","opts":["子音 /h/","母音 /aʊ/"],"a":1,"say":"hour 的 h 不發音，開頭是母音，所以用 an。"}],"why_zh":"a／an 看的是發音，hour 以母音開頭，所以是 an hour。只看字母選 a 是常見陷阱。","why_en":"Hour starts with a vowel sound, so we say an hour."},{"lvl":700,"s":"The monthly meeting will be held on ___ third floor of the main building.","zh":"月會將在主大樓的三樓舉行。","opts":["the","a","an","some"],"a":0,"guide":[{"q":"third 是什麼詞？","en":"What kind of word is 'third'?","opts":["序數（第三）","一般形容詞"],"a":0,"say":"序數表示特定的那一個，前面要用 the。"}],"why_zh":"序數（first、second、third）前面要用 the，表示特定的樓層。a third floor 不符合用法。","why_en":"Ordinal numbers like third take the."},{"lvl":700,"s":"Our team needs ___ new printer because the old one is broken.","zh":"我們團隊需要一台新印表機，因為舊的壞了。","opts":["an","much","some","a"],"a":3,"guide":[{"q":"printer 是可數還是不可數？是單數嗎？","en":"Is 'printer' countable and singular?","opts":["單數可數","不可數"],"a":0,"say":"單數可數名詞前要有冠詞，排除 much 和 some。"},{"q":"空格後面第一個字 new 的開頭是母音還是子音？","en":"Does 'new' start with a vowel or consonant sound?","opts":["母音","子音"],"a":1,"say":"new 以子音 /n/ 開頭，所以用 a。"}],"why_zh":"單數可數名詞 printer 前要用 a／an，而 new 以子音開頭，所以用 a。an 要看下一個字的發音，不是名詞本身。","why_en":"New starts with a consonant sound, so we use a."},{"lvl":700,"s":"Several ___ were made to the conference schedule last week.","zh":"上週會議行程做了幾項變更。","opts":["change","changes","a change","changing"],"a":1,"guide":[{"q":"several 後面要接單數還是複數名詞？","en":"Does 'several' take a singular or plural noun?","opts":["單數","複數"],"a":1,"say":"several 表示「幾個」，接可數複數名詞，動詞也是 were。"}],"why_zh":"several + 可數複數名詞，所以是 changes。change 和 a change 是單數，不能搭配 several 和 were。","why_en":"Several takes a plural countable noun: changes."},{"lvl":700,"s":"There ___ a lot of useful information on the company website.","zh":"公司網站上有很多實用的資訊。","opts":["is","are","were","have"],"a":0,"guide":[{"q":"真正的主詞是哪個名詞？","en":"What is the real subject noun?","opts":["website","information"],"a":1,"say":"There is/are 句型的主詞在後面，是 information。"},{"q":"information 要搭配單數還是複數動詞？","en":"Does 'information' take a singular or plural verb?","opts":["複數","單數"],"a":1,"say":"不可數名詞用單數動詞，就算前面有 a lot of 也一樣。"}],"why_zh":"information 不可數，動詞用單數 is。看到 a lot of 就選 are 是常見陷阱。","why_en":"Uncountable nouns take a singular verb: there is."},{"lvl":700,"s":"Please turn off ___ lights when you leave the office tonight.","zh":"今晚離開辦公室時請把燈關掉。","opts":["a","an","the","much"],"a":2,"guide":[{"q":"lights 是單數還是複數？","en":"Is 'lights' singular or plural?","opts":["單數","複數"],"a":1,"say":"複數名詞前不能用 a／an。"},{"q":"說的是哪裡的燈？雙方知道嗎？","en":"Do both people know which lights?","opts":["知道，辦公室的燈","不知道"],"a":0,"say":"特定、雙方都知道的東西用 the。"}],"why_zh":"lights 是複數，而且指辦公室裡特定的燈，所以用 the。a、an 不能接複數名詞，much 用於不可數名詞。","why_en":"We use the for specific things both people know."},{"lvl":700,"s":"The airline allows only one piece of carry-on ___ per passenger.","zh":"這家航空公司每位乘客只能攜帶一件隨身行李。","opts":["baggages","a baggage","the baggages","baggage"],"a":3,"guide":[{"q":"one piece of 後面通常接什麼名詞？","en":"What kind of noun usually follows 'one piece of'?","opts":["不可數名詞","可數複數名詞"],"a":0,"say":"a piece of 是用來計算不可數名詞的單位。"}],"why_zh":"baggage 是不可數名詞，要用 a piece of baggage 來計算。baggages 和 a baggage 都是錯誤形式。","why_en":"Baggage is uncountable, so we count it with a piece of."},{"lvl":900,"s":"The logistics consultant provided ___ valuable advice on how to reduce our overseas shipping costs.","zh":"物流顧問針對如何降低我們的海外運費提供了許多寶貴建議。","opts":["much","many","several","a"],"a":0,"guide":[{"q":"空格修飾的名詞是 valuable 還是 advice？","en":"Which noun does the blank describe?","opts":["advice","costs"],"a":0,"say":"空格後面的名詞是 advice，valuable 只是形容詞。"},{"q":"advice 要用哪一種數量詞？","en":"Which kind of quantifier goes with 'advice'?","opts":["可數用的 many／several","不可數用的 much"],"a":1,"say":"advice 不可數，要用 much。"}],"why_zh":"advice 是不可數名詞，要用 much。many、several 和 a 都只能接可數名詞。","why_en":"Advice is uncountable, so much is correct."},{"lvl":900,"s":"Before installing the accounting software, please read ___ instructions that came with the package carefully.","zh":"安裝會計軟體前，請仔細閱讀包裝內附的說明書。","opts":["a","the","an","much"],"a":1,"guide":[{"q":"instructions 是單數還是複數？","en":"Is 'instructions' singular or plural?","opts":["複數","單數"],"a":0,"say":"複數名詞前不能用 a／an。"},{"q":"that came with the package 讓 instructions 變得特定了嗎？","en":"Does 'that came with the package' make it specific?","opts":["沒有","有，是特定的說明書"],"a":1,"say":"後面有子句限定是哪一份說明書，所以用 the。"}],"why_zh":"instructions 是複數，又被 that 子句限定為特定的說明書，所以用 the。a／an 不能接複數，much 用於不可數名詞。","why_en":"The is used because the clause makes the instructions specific."},{"lvl":900,"s":"Because of the large number of ___ received after the product launch, responses may take up to three business days.","zh":"由於產品發表後收到大量詢問，回覆可能需要最多三個工作天。","opts":["inquiry","an inquiry","inquiries","inquiring"],"a":2,"guide":[{"q":"the number of 後面要接什麼樣的名詞？","en":"What kind of noun follows 'the number of'?","opts":["不可數名詞","可數複數名詞"],"a":1,"say":"the number of 是在數「個數」，後面接可數複數名詞。"}],"why_zh":"the number of + 可數複數名詞，所以是 inquiries。inquiry 和 an inquiry 是單數，數不出「數量」。","why_en":"The number of is followed by a plural countable noun."},{"lvl":900,"s":"The research team has requested additional laboratory ___ in order to complete the project on schedule.","zh":"研究團隊要求增加實驗室設備，以便如期完成專案。","opts":["equipments","an equipment","equips","equipment"],"a":3,"guide":[{"q":"additional laboratory 後面需要名詞還是動詞？","en":"After 'additional laboratory', noun or verb?","opts":["名詞","動詞"],"a":0,"say":"形容詞 additional 後面要接名詞，排除 equips。"},{"q":"equipment 能加 -s 或 an 嗎？","en":"Can 'equipment' take -s or an?","opts":["可以","不可以"],"a":1,"say":"equipment 是不可數名詞，永遠沒有 -s。"}],"why_zh":"equipment 是不可數名詞，不能加 -s 或 an。equipments 看起來像複數，是最常見的陷阱。","why_en":"Equipment is uncountable and never takes -s."},{"lvl":900,"s":"The client was impressed by ___ quality of the samples we sent to her office last week.","zh":"客戶對我們上週寄到她辦公室的樣品品質印象深刻。","opts":["the","an","many","few"],"a":0,"guide":[{"q":"quality 後面的 of the samples 是在說「哪一種」品質？","en":"Does 'of the samples' tell us which quality?","opts":["是，指樣品的品質","沒有特別指定"],"a":0,"say":"of 片語把名詞限定成特定的東西，要用 the。"}],"why_zh":"the + 名詞 + of ... 表示特定的「樣品的品質」，所以用 the。an 不能接子音開頭的 quality，many 和 few 要接可數複數名詞。","why_en":"The quality of ... refers to a specific quality, so we use the."}]},{"id":"cond","title_zh":"條件句","title_en":"Conditional sentences (real conditions)","icon":"🔀","pattern":"If／Unless + 現在式, 主詞 + will + 原形動詞","rule_zh":"表示未來可能發生的條件時，if 子句用現在式，主要子句用 will + 原形動詞（或祈使句）。unless = if ... not（除非）；as long as、provided that = 只要；in case = 以防萬一。這些連接詞後面接完整的子句，不能接名詞片語。","rule_en":"In a real condition about the future, the if-clause uses the present tense and the main clause uses will or a command. Unless means 'if not', as long as and provided that mean 'only if', and in case means 'to be prepared if'.","spot_zh":"考題線索：空格在 if／unless 子句的動詞位置（選現在式，不選 will），或是選項是 if / unless / as long as / in case 等連接詞，要看前後句意的邏輯關係。","examples":[{"en":"If it rains, we will stay home.","zh":"如果下雨，我們就待在家。"},{"en":"Take a jacket in case it gets cold.","zh":"帶件外套，以防天氣變冷。"},{"en":"You can borrow my bike as long as you return it today.","zh":"只要你今天還，就可以借我的腳踏車。"}],"qs":[{"lvl":700,"s":"If it ___ tomorrow, the outdoor company picnic will be moved indoors.","zh":"如果明天下雨，公司的戶外野餐將改在室內舉行。","opts":["will rain","rained","rains","raining"],"a":2,"guide":[{"q":"空格在 if 子句裡還是主要子句裡？","en":"Is the blank in the if-clause or the main clause?","opts":["if 子句","主要子句"],"a":0,"say":"空格在 if 子句，即使說的是明天，也要用現在式。"}],"why_zh":"表示未來條件時，if 子句用現在式 rains，主要子句才用 will。選 will rain 是最常見的陷阱。","why_en":"The if-clause uses the present tense even for the future."},{"lvl":700,"s":"We will not ship your order ___ we receive full payment.","zh":"除非收到全額付款，否則我們不會出貨。","opts":["if","unless","because","so"],"a":1,"guide":[{"q":"出貨的條件是「收到付款」還是「沒收到付款」？","en":"Is shipping conditional on receiving payment or not receiving it?","opts":["沒收到付款","收到付款"],"a":1,"say":"要收到錢才出貨，所以是「除非收到付款，否則不出貨」。"}],"why_zh":"unless = if ... not，「除非收到付款，否則不出貨」。用 if 會變成「收到錢就不出貨」，語意不合理。","why_en":"Unless means 'if not': no shipping until payment arrives."},{"lvl":700,"s":"You may use the conference room after hours ___ you return the key by 9 p.m.","zh":"只要你在晚上九點前歸還鑰匙，下班後就可以使用會議室。","opts":["unless","even","in case","as long as"],"a":3,"guide":[{"q":"「歸還鑰匙」和「可以使用會議室」是什麼關係？","en":"How does 'return the key' relate to 'may use the room'?","opts":["使用的條件","以防萬一","相反的情況"],"a":0,"say":"歸還鑰匙是能使用會議室的條件，要用「只要」。"}],"why_zh":"as long as 表示「只要……就……」，符合條件關係。in case 是「以防萬一」，unless 是「除非」，語意都不對；even 不是連接詞。","why_en":"As long as means 'on the condition that'."},{"lvl":700,"s":"Please bring an umbrella ___ it rains during the factory tour this afternoon.","zh":"請帶把傘，以防今天下午參觀工廠時下雨。","opts":["in case","unless","as long as","even"],"a":0,"guide":[{"q":"帶傘的目的是什麼？","en":"Why should you bring an umbrella?","opts":["只有下雨才帶","預防可能下雨"],"a":1,"say":"現在先帶傘，是為了預防萬一，所以用 in case。"}],"why_zh":"in case 表示「以防萬一」，先做準備。as long as 是「只要」，unless 是「除非」，放進句子語意不通。","why_en":"In case means 'to be prepared if it happens'."},{"lvl":700,"s":"If you ___ any questions about your bill, please contact our customer service team.","zh":"如果您對帳單有任何疑問，請聯絡我們的客服團隊。","opts":["will have","have","has","having"],"a":1,"guide":[{"q":"if 子句說未來可能的情況，動詞要用什麼時態？","en":"Which tense does the if-clause use for a possible situation?","opts":["will + 原形","現在式"],"a":1,"say":"if 子句用現在式，不用 will。"},{"q":"主詞 you 要搭配 have 還是 has？","en":"Does 'you' take have or has?","opts":["have","has"],"a":0,"say":"you 搭配 have。"}],"why_zh":"if 子句用現在式，主詞 you 用 have。will have 違反 if 子句不用 will 的規則；has 是第三人稱單數。","why_en":"The if-clause uses the present tense: if you have."},{"lvl":700,"s":"If the client ___ the contract this week, we will start the project on Monday.","zh":"如果客戶這週簽約，我們將在星期一開始執行專案。","opts":["will sign","signing","sign","signs"],"a":3,"guide":[{"q":"the client 是第幾人稱、單數還是複數？","en":"Is 'the client' third person singular?","opts":["第三人稱單數","複數"],"a":0,"say":"第三人稱單數的現在式要加 -s。"}],"why_zh":"if 子句用現在式，主詞 the client 是第三人稱單數，所以用 signs。will sign 是把未來式放錯在 if 子句。","why_en":"If-clause, present tense, third person: the client signs."},{"lvl":700,"s":"___ the weather is good, the city tour will include a boat ride on the river.","zh":"只要天氣好，市區導覽就會包含遊河行程。","opts":["Unless","Although","Provided that","Despite"],"a":2,"guide":[{"q":"「天氣好」是「搭船」的條件，還是讓步（雖然）？","en":"Is good weather a condition or a contrast?","opts":["讓步","條件"],"a":1,"say":"天氣好才能搭船，是條件關係。"}],"why_zh":"provided that 表示「只要、在……的條件下」。Unless 會變成「天氣不好時才會包含遊河行程」，語意相反；Despite 是介系詞，不能接子句。","why_en":"Provided that means 'only if'."},{"lvl":700,"s":"If you register online today, you ___ a 10 percent discount on the seminar fee.","zh":"如果你今天線上報名，就能享有研討會費用九折優惠。","opts":["will receive","received","receiving","had received"],"a":0,"guide":[{"q":"空格在 if 子句還是主要子句？","en":"Is the blank in the if-clause or the main clause?","opts":["if 子句","主要子句"],"a":1,"say":"主要子句說的是未來的結果，要用 will + 原形動詞。"}],"why_zh":"if 子句用現在式，主要子句用 will receive 表示未來結果。received 和 had received 是過去時態，與 today 的條件不合。","why_en":"The main clause uses will for the future result."},{"lvl":700,"s":"Unless the train ___ late, we will arrive at the hotel by noon.","zh":"除非火車誤點，否則我們中午前會抵達飯店。","opts":["will be","be","being","is"],"a":3,"guide":[{"q":"unless 子句和 if 子句一樣，要用什麼時態？","en":"Like an if-clause, what tense does an unless-clause use?","opts":["will + 原形","現在式"],"a":1,"say":"unless 子句表示條件，也用現在式代替未來。"}],"why_zh":"unless 子句跟 if 子句一樣，用現在式 is 表示未來。will be 是本題陷阱。","why_en":"An unless-clause uses the present tense for the future."},{"lvl":700,"s":"Call the IT help desk ___ you need assistance with the new software.","zh":"如果你在使用新軟體時需要協助，請打電話給資訊服務台。","opts":["unless","so","if","although"],"a":2,"guide":[{"q":"「需要協助」是打電話的條件，還是原因相反？","en":"Is needing help the condition for calling?","opts":["是條件","是相反的情況"],"a":0,"say":"需要協助時才打電話，用 if 表示條件。"}],"why_zh":"if 表示「如果需要協助就打電話」。unless 會變成「不需要協助時才打電話」，語意相反；although 是讓步。","why_en":"If introduces the condition: call if you need help."},{"lvl":900,"s":"___ the shipment from our supplier arrives on schedule, the new products will be available in stores by the end of the month.","zh":"只要供應商的貨如期送達，新產品將在月底前於門市上架。","opts":["Otherwise","Provided that","In spite of","Unless"],"a":1,"guide":[{"q":"空格後面是名詞片語還是完整子句？","en":"Is a noun phrase or a full clause after the blank?","opts":["完整子句","名詞片語"],"a":0,"say":"後面有主詞 the shipment 和動詞 arrives，需要連接詞，排除 In spite of 和 Otherwise。"},{"q":"如期到貨是上架的條件，還是相反？","en":"Is on-time arrival the condition for the products being available?","opts":["相反","條件"],"a":1,"say":"準時到貨才能上架，是條件，用 provided that。"}],"why_zh":"provided that 是連接詞，表示「只要」，符合語意。Unless 會變成「如果沒有準時到貨，新產品就會上架」，邏輯相反；In spite of 是介系詞，Otherwise 是副詞。","why_en":"Provided that is a conjunction meaning 'only if'."},{"lvl":900,"s":"Employees may work from home on Fridays ___ they remain available by phone and e-mail during regular office hours.","zh":"只要員工在正常上班時間保持電話和電子郵件聯繫，星期五就可以在家工作。","opts":["in case","unless","so that","as long as"],"a":3,"guide":[{"q":"「保持聯繫」是在家工作的什麼？","en":"What is 'remain available' for working from home?","opts":["目的","條件","以防萬一"],"a":1,"say":"保持聯繫是允許在家工作的條件，要用「只要」。"}],"why_zh":"as long as 表示「只要……就可以」，是條件。so that 表示目的，in case 表示預防，unless 則會讓語意相反。","why_en":"As long as gives the condition for working from home."},{"lvl":900,"s":"Please keep a copy of the invoice ___ there is a problem with your payment after the transaction is processed.","zh":"請保留一份發票副本，以防交易處理後付款出現問題。","opts":["in case","as long as","provided that","unless"],"a":0,"guide":[{"q":"保留發票是因為已經出問題，還是預防可能出問題？","en":"Do you keep the invoice because of a problem, or to be ready for one?","opts":["預防可能出問題","只有出問題時才保留"],"a":0,"say":"現在先保留發票，是預防萬一，用 in case。"}],"why_zh":"in case 表示「以防萬一」，先採取預防措施。as long as 和 provided that 會變成「只有出問題才保留」，不合邏輯。","why_en":"In case means you prepare now for a possible problem."},{"lvl":900,"s":"If the board of directors ___ the proposal at next week's meeting, construction on the new branch will begin in March.","zh":"如果董事會在下週的會議中通過提案，新分公司將在三月開工。","opts":["will approve","approving","approves","approval"],"a":2,"guide":[{"q":"空格需要動詞還是名詞？","en":"Does the blank need a verb or a noun?","opts":["名詞","動詞"],"a":1,"say":"if 子句缺動詞，排除 approval 和 approving。"},{"q":"雖然是 next week，if 子句要用什麼時態？","en":"Even with 'next week', what tense goes in the if-clause?","opts":["現在式","will + 原形"],"a":0,"say":"if 子句用現在式代替未來，主詞單數，所以是 approves。"}],"why_zh":"if 子句用現在式表示未來，the board 是單數，所以用 approves。句中的 next week 容易誘導考生選 will approve。","why_en":"Even with next week, the if-clause uses the present: approves."},{"lvl":900,"s":"The security update will not be installed on your device ___ the user restarts the computer after downloading it.","zh":"除非使用者在下載後重新啟動電腦，否則安全性更新不會安裝到你的裝置上。","opts":["in case","unless","despite","without"],"a":1,"guide":[{"q":"空格後面是完整子句嗎？","en":"Is there a full clause after the blank?","opts":["是","不是"],"a":0,"say":"後面有主詞和動詞，despite 和 without 是介系詞，不能接子句。"},{"q":"「重新啟動」是安裝的必要條件，還是預防措施？","en":"Is restarting a required condition or a precaution?","opts":["預防措施","必要條件"],"a":1,"say":"不重新啟動就不會安裝，用 unless（除非）。"}],"why_zh":"not ... unless 表示「除非……否則不……」。in case 是「以防萬一」，語意不合；despite 和 without 是介系詞，不能接子句。","why_en":"Unless means the update installs only after a restart."}]},{"id":"subj","title_zh":"假設語氣","title_en":"Unreal conditionals and wishes","icon":"💭","pattern":"If + 過去式, would + V ／ If + had p.p., would have p.p. ／ wish + 過去式","rule_zh":"假設語氣用來說「和事實相反」的情況。與現在事實相反：If + 過去式（be 動詞一律用 were），主句用 would/could + 原形。與過去事實相反：If + had + p.p.，主句用 would/could have + p.p.。wish 後面也要「往過去退一格」：現在的願望用過去式，過去的遺憾用 had + p.p.。","rule_en":"Use unreal conditionals for things that are not true. Present unreal: If + past (were), would + V. Past unreal: If + had + p.p., would have + p.p.; wish follows the same backshift.","spot_zh":"考題線索：看到 If 子句或主句裡有 would / would have，或句中有 wish、as if、It is time，就要判斷是和現在還是過去事實相反。","examples":[{"en":"If I were rich, I would buy a big house.","zh":"如果我很有錢，我就會買一間大房子。"},{"en":"I wish I had a dog.","zh":"真希望我有一隻狗。"},{"en":"If you had called me, I would have picked you up.","zh":"如果你當時有打給我，我就會去接你了。"}],"qs":[{"lvl":700,"s":"If I ___ the manager, I would approve the budget immediately.","zh":"如果我是經理，我會立刻核准這筆預算。","opts":["am","were","have been","will be"],"a":1,"guide":[{"q":"主句用 would approve，這是真實情況還是和現在事實相反的假設？","en":"The main clause uses 'would approve'. Is this real or an unreal present situation?","opts":["真實情況","與現在事實相反"],"a":1,"say":"would + 原形代表與現在事實相反的假設，我其實不是經理。"},{"q":"與現在事實相反時，If 子句的 be 動詞要用什麼？","en":"In a present unreal if-clause, which form of 'be' do we use?","opts":["am","were"],"a":1,"say":"與現在事實相反時，be 動詞一律用 were。"}],"why_zh":"主句 would approve 表示與現在事實相反，If 子句要用過去式，be 動詞用 were。am 是真實條件的用法，和 would 不搭。","why_en":"A present unreal condition uses 'were' in the if-clause with 'would' in the main clause."},{"lvl":700,"s":"If the shipment had arrived on time, we ___ the order to the client yesterday.","zh":"如果貨物準時送達，我們昨天就會把訂單交給客戶了。","opts":["will deliver","would deliver","would have delivered","had delivered"],"a":2,"guide":[{"q":"If 子句用 had arrived，是和哪個時間的事實相反？","en":"The if-clause uses 'had arrived'. Which time is it unreal about?","opts":["現在","過去"],"a":1,"say":"had + p.p. 表示和過去事實相反，貨物其實沒準時到。"},{"q":"與過去事實相反時，主句要用哪個形式？","en":"For a past unreal condition, what form does the main clause use?","opts":["would + V","would have + p.p."],"a":1,"say":"與過去事實相反，主句用 would have + p.p.。"}],"why_zh":"If 子句 had arrived 加上 yesterday，是和過去事實相反，主句要用 would have delivered。would deliver 是和現在事實相反，時間不對。","why_en":"A past unreal condition needs 'would have + p.p.' in the main clause."},{"lvl":700,"s":"Ms. Chen wishes she ___ more time to prepare for tomorrow's presentation.","zh":"陳小姐希望她有更多時間準備明天的簡報。","opts":["had","has","will have","having"],"a":0,"guide":[{"q":"她現在真的有足夠的時間嗎？","en":"Does she really have enough time now?","opts":["有","沒有"],"a":1,"say":"她沒有足夠時間，所以這是和現在事實相反的願望。"},{"q":"wish 表達現在的願望時，後面的動詞要用什麼時態？","en":"After 'wish' for a present situation, which tense do we use?","opts":["現在式","過去式","未來式"],"a":1,"say":"wish 後面要往過去退一格，現在的願望用過去式 had。"}],"why_zh":"wish 表示與現在事實相反的願望，動詞要用過去式 had。has 和 will have 是一般陳述，不能放在 wish 後面。","why_en":"After 'wish' about the present, we use the past tense: had."},{"lvl":700,"s":"If we ___ the earlier train, we would have reached the hotel before dinner.","zh":"如果我們搭了早一點的火車，就能在晚餐前抵達飯店了。","opts":["take","took","would take","had taken"],"a":3,"guide":[{"q":"主句用 would have reached，代表什麼時間的假設？","en":"The main clause uses 'would have reached'. Which time is this about?","opts":["過去","現在"],"a":0,"say":"would have + p.p. 表示和過去事實相反。"},{"q":"那 If 子句應該用什麼形式？","en":"Then what form does the if-clause need?","opts":["過去式","had + p.p."],"a":1,"say":"與過去事實相反時，If 子句用 had + p.p.。"}],"why_zh":"主句 would have reached 是與過去事實相反，If 子句要用 had taken。took 是與現在事實相反的用法，時間不搭。","why_en":"With 'would have reached', the if-clause needs 'had + p.p.': had taken."},{"lvl":700,"s":"If the printer were working, I ___ the reports for you right now.","zh":"如果印表機能用，我現在就幫你印報告。","opts":["will print","would print","printed","had printed"],"a":1,"guide":[{"q":"If 子句用 were working，是和現在還是過去事實相反？","en":"The if-clause uses 'were working'. Unreal about now or the past?","opts":["過去","現在"],"a":1,"say":"were 搭配 right now，表示和現在事實相反，印表機現在壞了。"},{"q":"與現在事實相反，主句要用什麼？","en":"For a present unreal condition, what does the main clause use?","opts":["would + V","will + V"],"a":0,"say":"主句用 would + 原形，所以是 would print。"}],"why_zh":"If 子句用 were，是與現在事實相反，主句用 would print。will print 用於真實條件，不能和 were 搭配。","why_en":"A present unreal condition takes 'would + V' in the main clause."},{"lvl":700,"s":"The sales team wishes it ___ the contract with that supplier last month.","zh":"業務團隊希望上個月有和那家供應商簽約。","opts":["signs","has signed","had signed","will sign"],"a":2,"guide":[{"q":"last month 表示這個願望是關於什麼時間？","en":"'Last month' shows the wish is about which time?","opts":["過去","未來","現在"],"a":0,"say":"這是對過去的遺憾，團隊上個月其實沒簽約。"},{"q":"wish 表達對過去的遺憾時，後面用什麼？","en":"After 'wish' for a past regret, what form do we use?","opts":["had + p.p.","過去式"],"a":0,"say":"對過去的遺憾要用 had + p.p.。"}],"why_zh":"wish 加上 last month，是與過去事實相反，要用 had signed。has signed 是現在完成式，不能表達遺憾。","why_en":"A wish about the past uses 'had + p.p.': had signed."},{"lvl":700,"s":"If I were you, I ___ the hotel room at least a month in advance.","zh":"如果我是你，我會至少提前一個月訂飯店房間。","opts":["would book","will book","booked","had booked"],"a":0,"guide":[{"q":"「If I were you」我可能真的變成你嗎？","en":"In 'If I were you', can I really be you?","opts":["可以","不可能"],"a":1,"say":"這是不可能的假設，所以是與現在事實相反。"},{"q":"那主句要用 will 還是 would？","en":"So should the main clause use 'will' or 'would'?","opts":["will","would"],"a":1,"say":"與現在事實相反，主句用 would + 原形。"}],"why_zh":"If I were you 是常見的建議句型，主句固定用 would + 原形，所以是 would book。will book 不能和 were 的假設搭配。","why_en":"'If I were you' is followed by 'would + V' in the main clause."},{"lvl":700,"s":"If the restaurant ___ open on Mondays, we could hold the team lunch there.","zh":"如果那家餐廳週一有營業，我們就可以在那裡辦團隊午餐。","opts":["is","be","has been","were"],"a":3,"guide":[{"q":"主句用 could hold，表示這件事是真的能做到，還是假設？","en":"The main clause uses 'could hold'. Is this real or imagined?","opts":["假設，餐廳其實週一沒開","真的可以"],"a":0,"say":"could + 原形表示與現在事實相反，餐廳週一其實沒開。"},{"q":"那 If 子句的 be 動詞要用？","en":"Then which 'be' verb goes in the if-clause?","opts":["is","were"],"a":1,"say":"與現在事實相反，be 動詞用 were。"}],"why_zh":"主句 could hold 是與現在事實相反，If 子句 be 動詞用 were。is 用於真實條件，和 could 的假設不搭。","why_en":"With 'could' in an unreal present condition, the if-clause uses 'were'."},{"lvl":700,"s":"Mr. Lin would have joined the conference call if he ___ the invitation.","zh":"如果林先生有收到邀請，他就會參加那場電話會議了。","opts":["receives","had received","would receive","has received"],"a":1,"guide":[{"q":"主句在前面，用的是 would have joined。這是和哪個時間相反？","en":"The main clause comes first with 'would have joined'. Which time is unreal?","opts":["現在","過去"],"a":1,"say":"would have + p.p. 表示和過去事實相反。"},{"q":"If 子句不管放前面或後面，都要用？","en":"Whether it comes first or last, what does the if-clause use?","opts":["had + p.p.","would + V"],"a":0,"say":"與過去事實相反，If 子句用 had + p.p.，而且 If 子句不能用 would。"}],"why_zh":"主句 would have joined 是與過去事實相反，If 子句要用 had received。would receive 不能放在 If 子句裡。","why_en":"A past unreal if-clause uses 'had + p.p.', even when it comes second."},{"lvl":700,"s":"Many employees wish our office ___ closer to the train station.","zh":"很多員工希望我們辦公室離火車站近一點。","opts":["is","will be","were","being"],"a":2,"guide":[{"q":"辦公室現在離車站近嗎？","en":"Is the office close to the station now?","opts":["不近","很近"],"a":0,"say":"辦公室其實不近，這是和現在事實相反的願望。"},{"q":"wish 後面的 be 動詞要用什麼？","en":"What 'be' verb follows 'wish' for a present wish?","opts":["is","were"],"a":1,"say":"wish 表達現在的願望，be 動詞用 were。"}],"why_zh":"wish 表示與現在事實相反，be 動詞要用 were。is 和 will be 是一般陳述，不能用在 wish 後面。","why_en":"After 'wish' about now, the 'be' verb is 'were'."},{"lvl":900,"s":"If the marketing department had followed the original plan, the company ___ in a much stronger position today.","zh":"如果行銷部當初照原本的計畫進行，公司現在的處境會好得多。","opts":["would be","would have been","will be","had been"],"a":0,"guide":[{"q":"If 子句講過去（had followed），但主句最後的時間詞是什麼？","en":"The if-clause is about the past, but what time word ends the main clause?","opts":["yesterday","today"],"a":1,"say":"主句有 today，講的是現在的結果。"},{"q":"過去的條件、現在的結果，主句要用？","en":"Past condition, present result: what does the main clause use?","opts":["would + V","would have + p.p."],"a":0,"say":"這是混合假設：If 用 had + p.p.，主句講現在用 would + 原形。"}],"why_zh":"這是混合假設語氣：過去沒照計畫（had followed），影響到現在（today），主句用 would be。would have been 是講過去的結果，和 today 衝突。","why_en":"A past condition with a present result (today) takes 'would + V': would be."},{"lvl":900,"s":"Without the generous support of our sponsors, the annual charity dinner ___ possible last year.","zh":"如果沒有贊助商的大力支持，去年的年度慈善晚宴就不可能舉辦。","opts":["is not","will not be","would not be","would not have been"],"a":3,"guide":[{"q":"Without the support 在這裡相當於哪個 If 子句？","en":"What if-clause does 'Without the support' stand for here?","opts":["If we had not had the support","If we have the support"],"a":0,"say":"Without... 等於「如果當時沒有……」，是和過去事實相反的假設。"},{"q":"句尾 last year 告訴我們主句要用哪種形式？","en":"What form does 'last year' tell us the main clause needs?","opts":["would + V","would have + p.p."],"a":1,"say":"講過去的假設結果，主句用 would have + p.p.。"}],"why_zh":"Without 可代替 If 子句，加上 last year 是和過去事實相反，要用 would not have been。would not be 是講現在，和 last year 不符。","why_en":"'Without' replaces a past if-clause here, so we need 'would not have been'."},{"lvl":900,"s":"Given the rising costs, it is high time the board ___ a final decision on the proposed merger.","zh":"考量到成本上漲，董事會早該對擬議中的合併案做出最終決定了。","opts":["make","made","has made","will make"],"a":1,"guide":[{"q":"「It is high time」表示董事會已經做決定了嗎？","en":"Does 'It is high time' mean the board has already decided?","opts":["還沒，而且早該做了","已經做了"],"a":0,"say":"It is high time 表示「早該做卻還沒做」，是與現在事實相反。"},{"q":"It is high time + 主詞後面的動詞要用什麼時態？","en":"After 'It is high time + subject', which tense do we use?","opts":["現在式","過去式"],"a":1,"say":"這個句型固定接過去式，所以用 made。"}],"why_zh":"It is (high) time + 主詞 + 過去式，表示早該做了，所以用 made。has made 表示已經做了，意思相反。","why_en":"'It is high time' + subject takes the past tense: made."},{"lvl":900,"s":"If the supplier ___ the defective parts last week, our production line would be running normally now.","zh":"如果供應商上週有更換瑕疵零件，我們的生產線現在就能正常運作了。","opts":["replaces","would replace","had replaced","has replaced"],"a":2,"guide":[{"q":"If 子句的時間詞是什麼？","en":"What is the time word in the if-clause?","opts":["now","last week"],"a":1,"say":"If 子句講 last week，是過去沒發生的事。"},{"q":"和過去事實相反的 If 子句要用？","en":"What form does a past unreal if-clause use?","opts":["過去式","had + p.p."],"a":1,"say":"過去的條件用 had + p.p.，主句講現在用 would be running。"}],"why_zh":"這是混合假設：上週沒換零件（had replaced），導致現在的狀況（would be running now）。would replace 不能放在 If 子句裡。","why_en":"The condition is about last week, so the if-clause needs 'had replaced'."},{"lvl":900,"s":"The guest gave orders to the staff as if he ___ the owner of the hotel, although he was only staying for one night.","zh":"那位房客對員工發號施令，好像他是飯店老闆一樣，雖然他只住一晚。","opts":["were","is","has been","will be"],"a":0,"guide":[{"q":"那位房客真的是飯店老闆嗎？","en":"Is the guest really the hotel owner?","opts":["是","不是"],"a":1,"say":"他不是老闆，所以 as if 後面是和事實相反的假設。"},{"q":"as if 表達與事實相反時，be 動詞用？","en":"After 'as if' for something untrue, which 'be' verb do we use?","opts":["were","is"],"a":0,"say":"as if 後面和 wish 一樣要往過去退一格，用 were。"}],"why_zh":"as if 表示「好像」，內容和事實相反時用假設語氣 were。is 表示他真的是老闆，和後面 only staying for one night 矛盾。","why_en":"'As if' with an untrue idea takes the subjunctive 'were'."}]},{"id":"nounclause","title_zh":"名詞子句","title_en":"Noun clauses","icon":"🧩","pattern":"that / whether / what / how / wh- + 子句（或 + to V）","rule_zh":"名詞子句可以當主詞或受詞。後面是「完整句子」、只是陳述事實時用 that；表示「是否」用 whether（或 if）。後面的句子缺主詞或受詞時用 what（＝the thing that）。疑問詞 + to V 是縮短的名詞子句，例如 how to use、where to go。","rule_en":"A noun clause works as a subject or object. Use 'that' before a complete statement, 'whether' for yes/no ideas, and 'what' when the clause is missing a subject or object. A wh- word + to V is a short noun clause.","spot_zh":"考題線索：空格在動詞（know, ask, decide, explain）後面或句首，後面接一個子句或 to V，選項是 that / what / whether / how 時，就是名詞子句題。","examples":[{"en":"I know that you are tired.","zh":"我知道你累了。"},{"en":"Can you tell me what you want for dinner?","zh":"你可以告訴我晚餐想吃什麼嗎？"},{"en":"I don't know whether she likes cats.","zh":"我不知道她喜不喜歡貓。"}],"qs":[{"lvl":700,"s":"The manager asked ___ the report would be ready by Friday.","zh":"經理問報告是否能在週五前準備好。","opts":["whether","what","that","which"],"a":0,"guide":[{"q":"空格後面的句子 the report would be ready 完整嗎？","en":"Is 'the report would be ready' a complete clause?","opts":["缺主詞或受詞","完整"],"a":1,"say":"子句完整，所以不用 what 或 which。"},{"q":"經理「問」的是一個是非問題嗎？","en":"Is the manager asking a yes/no question?","opts":["是，能不能準備好","不是"],"a":0,"say":"問「是否」要用 whether。"}],"why_zh":"asked 後面接是非問題，子句又完整，所以用 whether。that 是陳述用法，不能放在 ask 後面表示疑問。","why_en":"After 'asked' with a yes/no idea and a complete clause, we use 'whether'."},{"lvl":700,"s":"___ the meeting was canceled surprised everyone in the office.","zh":"會議被取消這件事讓辦公室裡的每個人都很驚訝。","opts":["What","That","If","Which"],"a":1,"guide":[{"q":"句子的主要動詞是哪一個？","en":"What is the main verb of the sentence?","opts":["was canceled","surprised"],"a":1,"say":"主要動詞是 surprised，前面整段都是主詞。"},{"q":"the meeting was canceled 這個子句完整嗎？","en":"Is 'the meeting was canceled' complete?","opts":["完整","缺東西"],"a":0,"say":"子句完整又是陳述事實，當主詞時用 That。"}],"why_zh":"名詞子句當主詞、內容是完整的事實陳述，要用 That。What 後面的子句必須缺主詞或受詞；If 不能放句首當主詞。","why_en":"A complete statement used as a subject starts with 'That'."},{"lvl":700,"s":"Please tell me ___ you need for the presentation.","zh":"請告訴我你做簡報需要什麼。","opts":["that","whether","what","if"],"a":2,"guide":[{"q":"need 後面有受詞嗎？","en":"Does 'need' have an object after it?","opts":["有","沒有"],"a":1,"say":"you need 後面缺受詞。"},{"q":"子句缺受詞時，要用哪個字開頭？","en":"Which word starts a clause that is missing its object?","opts":["that","what"],"a":1,"say":"what 本身可以當子句的受詞，意思是「……的東西」。"}],"why_zh":"you need 缺受詞，what 可以補上這個位置，所以選 what。that、whether、if 後面都要接完整句子。","why_en":"'You need' is missing an object, so 'what' is needed."},{"lvl":700,"s":"We are not sure ___ to contact about the broken printer.","zh":"我們不確定印表機壞了該聯絡誰。","opts":["that","what","if","whom"],"a":3,"guide":[{"q":"空格後面是一個子句，還是 to V？","en":"Is the blank followed by a clause or 'to V'?","opts":["to V","子句"],"a":0,"say":"後面是 to contact，要用「疑問詞 + to V」。"},{"q":"contact 的對象是人還是事情？","en":"Is the person you contact a person or a thing?","opts":["事情","人"],"a":1,"say":"聯絡的是人，所以用 whom to contact。"}],"why_zh":"疑問詞 + to V 可當名詞子句，contact 的對象是人，所以用 whom。that 和 if 不能接 to V；what 指事物，不符合語意。","why_en":"A wh- word + to V is needed, and we contact a person, so 'whom'."},{"lvl":700,"s":"The new employees learned how ___ the online booking system.","zh":"新員工學會了如何使用線上訂位系統。","opts":["to use","using","use","used"],"a":0,"guide":[{"q":"how 後面沒有主詞，要接什麼形式？","en":"'How' has no subject after it. What form follows?","opts":["V-ing","to V"],"a":1,"say":"疑問詞後面沒有主詞時，接 to V。"}],"why_zh":"how + to V 表示「如何做」，是縮短的名詞子句，所以用 to use。how using 和 how use 都不是正確結構。","why_en":"'How' + to V means 'the way to do something': how to use."},{"lvl":700,"s":"The latest survey shows ___ most customers prefer to shop online.","zh":"最新的調查顯示大多數顧客偏好在網路上購物。","opts":["what","that","about","which"],"a":1,"guide":[{"q":"most customers prefer to shop online 是完整的句子嗎？","en":"Is 'most customers prefer to shop online' complete?","opts":["是","不是"],"a":0,"say":"這是一個完整的句子，陳述調查結果。"},{"q":"show 後面接一個完整的事實，要用哪個連接詞？","en":"Which word introduces a complete fact after 'show'?","opts":["what","that"],"a":1,"say":"完整的陳述用 that 引導。"}],"why_zh":"shows 後面接完整句子當受詞，用 that。what 要接缺主詞或受詞的子句；about 是介系詞，不能接子句。","why_en":"A complete statement after 'shows' is introduced by 'that'."},{"lvl":700,"s":"Ms. Wang has not decided ___ she will attend the trade fair in Tokyo.","zh":"王小姐還沒決定是否要參加東京的商展。","opts":["that","what","whether","about"],"a":2,"guide":[{"q":"「還沒決定」的內容是確定的事實，還是「要或不要」？","en":"Is the undecided thing a fact or a 'yes or no' choice?","opts":["要或不要","確定的事實"],"a":0,"say":"還沒決定，所以是「是否」的選擇。"},{"q":"表示「是否」要用？","en":"Which word means 'if or not'?","opts":["that","whether"],"a":1,"say":"whether 表示「是否」。"}],"why_zh":"has not decided 表示還不確定，要用 whether（是否）。that 表示確定的事實，和「還沒決定」矛盾。","why_en":"'Not decided' needs a yes/no idea, so 'whether'."},{"lvl":700,"s":"The front desk clerk will explain ___ to get to the airport by shuttle bus.","zh":"櫃檯人員會說明如何搭接駁車去機場。","opts":["what","which","that","how"],"a":3,"guide":[{"q":"空格後面接的是 to V，可以搭配 that 嗎？","en":"The blank is followed by 'to V'. Can 'that' be used?","opts":["可以","不可以"],"a":1,"say":"that 後面不能接 to V，要用疑問詞。"},{"q":"說明的是「方法」還是「東西」？","en":"Is the clerk explaining a way or a thing?","opts":["方法","東西"],"a":0,"say":"去機場的方法，所以用 how to get。"}],"why_zh":"get to the airport 是講方法，用 how to get。what to get to 語意不通，that 不能接 to V。","why_en":"We explain the way to get there: how to get."},{"lvl":700,"s":"Do you know ___ the sales conference will be held this year?","zh":"你知道今年的業務大會在哪裡舉行嗎？","opts":["where","what","that","which"],"a":0,"guide":[{"q":"the sales conference will be held 有缺主詞或受詞嗎？","en":"Is 'the sales conference will be held' missing a subject or object?","opts":["沒有缺","缺受詞"],"a":0,"say":"被動句已經完整，不能用 what 或 which。"},{"q":"這裡想問的是會議的什麼資訊？","en":"What information about the conference is being asked?","opts":["地點","是不是事實"],"a":0,"say":"問地點用 where。"}],"why_zh":"子句完整、問的是地點，所以用 where。what 要接缺受詞的子句；that 不能表示疑問。","why_en":"The clause is complete and asks about a place, so 'where'."},{"lvl":700,"s":"___ we need now is a larger budget for advertising.","zh":"我們現在需要的是更多的廣告預算。","opts":["That","What","Which","Whether"],"a":1,"guide":[{"q":"we need now 後面有受詞嗎？","en":"Does 'we need now' have an object?","opts":["有","沒有"],"a":1,"say":"need 後面缺受詞。"},{"q":"哪個字可以同時當連接詞和 need 的受詞？","en":"Which word can join the clause and be the object of 'need'?","opts":["What","That"],"a":0,"say":"What＝the thing that，可以補上缺的受詞。"}],"why_zh":"we need 缺受詞，What 引導的子句當主詞，意思是「我們需要的東西」。That 後面必須是完整句子。","why_en":"'We need' lacks an object, so 'What' (the thing that) is correct."},{"lvl":900,"s":"The committee has yet to determine ___ the new branch should open in Taichung or Kaohsiung.","zh":"委員會尚未決定新分店應該開在台中還是高雄。","opts":["that","what","whether","where"],"a":2,"guide":[{"q":"句尾的 Taichung or Kaohsiung 給了什麼線索？","en":"What clue does 'Taichung or Kaohsiung' give?","opts":["兩個選擇之一","確定的事實"],"a":0,"say":"A or B 表示在兩者之間選擇。"},{"q":"哪個字常和 or 搭配表示「是 A 還是 B」？","en":"Which word pairs with 'or' to mean 'A or B'?","opts":["where","whether"],"a":1,"say":"whether A or B 是固定搭配。地點已經寫在句中，不能再用 where。"}],"why_zh":"whether...or... 表示「是……還是……」，子句又完整，所以選 whether。where 會和句中的 in Taichung 重複，that 不能表示選擇。","why_en":"'Whether ... or ...' expresses a choice between two options."},{"lvl":900,"s":"Management announced ___ employees who exceed their sales targets will receive an extra week of paid vacation.","zh":"管理階層宣布，超過業績目標的員工將獲得額外一週的帶薪假。","opts":["what","whether","which","that"],"a":3,"guide":[{"q":"這句的主詞和動詞在哪裡？who exceed... 是誰的說明？","en":"Where are the subject and verb? What does 'who exceed...' describe?","opts":["說明 employees","說明 Management"],"a":0,"say":"who exceed their sales targets 修飾 employees，子句主詞是 employees，動詞是 will receive。"},{"q":"子句 employees ... will receive an extra week 完整嗎？","en":"Is 'employees ... will receive an extra week' complete?","opts":["缺受詞","完整"],"a":1,"say":"子句完整，宣布的是確定的事實，用 that。"}],"why_zh":"announced 後接完整的事實陳述，用 that。中間的 who 子句只是修飾 employees，容易誤選 what 或 which。","why_en":"'Announced' is followed by a complete statement, so 'that'."},{"lvl":900,"s":"___ the new accounting software will actually reduce costs remains to be seen, according to the IT director.","zh":"根據資訊部主管的說法，新的會計軟體是否真的能降低成本還有待觀察。","opts":["Whether","That","What","If"],"a":0,"guide":[{"q":"remains to be seen 表示這件事已經確定了嗎？","en":"Does 'remains to be seen' mean it is already certain?","opts":["已經確定","還不確定"],"a":1,"say":"還有待觀察，表示「是否」還不知道。"},{"q":"放在句首當主詞、表示「是否」，要用 Whether 還是 If？","en":"At the start as a subject, 'Whether' or 'If'?","opts":["If","Whether"],"a":1,"say":"If 不能引導主詞子句，句首要用 Whether。"}],"why_zh":"remains to be seen 表示不確定，主詞子句要用 Whether。If 雖然也有「是否」的意思，但不能放句首當主詞；That 表示確定的事實，語意矛盾。","why_en":"A yes/no subject clause must begin with 'Whether', not 'If'."},{"lvl":900,"s":"The director is still considering ___ to reward the staff for completing the project ahead of schedule.","zh":"主管仍在考慮要如何獎勵提前完成專案的員工。","opts":["what","how","that","which"],"a":1,"guide":[{"q":"reward 後面已經有受詞 the staff 了嗎？","en":"Does 'reward' already have an object, 'the staff'?","opts":["有","沒有"],"a":0,"say":"reward the staff 已經完整，不缺受詞，所以不能用 what。"},{"q":"那主管在考慮的是什麼？","en":"So what is the director thinking about?","opts":["獎勵的方式","獎勵的東西"],"a":0,"say":"考慮獎勵的方式，用 how to reward。"}],"why_zh":"to reward the staff 已有受詞，不缺東西，要用表示方式的 how。what 會讓 reward 有兩個受詞，that 不能接 to V。","why_en":"'Reward the staff' is complete, so we need 'how' (the way)."},{"lvl":900,"s":"The memo did not specify ___ department would be responsible for handling customer complaints after the merger.","zh":"備忘錄並未具體說明合併後由哪個部門負責處理客訴。","opts":["that","whom","which","whether"],"a":2,"guide":[{"q":"空格後面緊接著一個名詞 department，空格需要什麼詞？","en":"A noun 'department' follows the blank. What kind of word is needed?","opts":["可以修飾名詞的疑問詞","連接完整句子的連接詞"],"a":0,"say":"空格要能直接放在名詞前面，像 which department。"},{"q":"that 或 whether 加上 department would be... 句子完整嗎？","en":"With 'that' or 'whether', is 'department would be...' complete?","opts":["完整","不完整，department 前少了限定詞"],"a":1,"say":"department 是單數可數名詞，單獨當主詞不完整，所以要用 which department。"}],"why_zh":"which + 名詞 引導名詞子句，表示「哪個部門」。that 和 whether 後面的 department 缺少限定詞，句子不完整；whom 不能修飾名詞。","why_en":"'Which' + noun introduces the clause: which department."}]},{"id":"inversion","title_zh":"倒裝句","title_en":"Inversion","icon":"🔃","pattern":"否定副詞 / Only + 副詞片語 + 助動詞 + 主詞 + V；Should / Had / Were + 主詞（省略 if）","rule_zh":"否定或限制的字（Not only, Never, Seldom, Rarely, Hardly, Under no circumstances, Only after...）放在句首時，後面要倒裝成「助動詞 + 主詞 + 動詞」，像問句一樣。假設句可以省略 if，把 Should、Had、Were 移到主詞前面，例如 Should you need help = If you should need help。","rule_en":"When a negative or limiting word starts the sentence, use question order: auxiliary + subject + verb. In conditionals, 'if' can be dropped and Should, Had or Were moves before the subject.","spot_zh":"考題線索：句首是 Not only、Never、Seldom、Only after、Not until，或句首空格後面直接接主詞（沒有 if），選項有 Should / Had / Were 時，就是倒裝題。","examples":[{"en":"Never have I seen such a big cake!","zh":"我從沒看過這麼大的蛋糕！"},{"en":"Should you need anything, just call me.","zh":"如果你需要什麼，打給我就好。"},{"en":"Had I known, I would have come earlier.","zh":"早知道的話，我就會早點來了。"}],"qs":[{"lvl":700,"s":"Not only ___ the sales target, but she also trained two new staff members.","zh":"她不但達成了業績目標，還訓練了兩位新員工。","opts":["did she meet","she met","she did meet","met she"],"a":0,"guide":[{"q":"句首是 Not only，後面要用一般語序還是倒裝？","en":"'Not only' starts the sentence. Normal order or inversion?","opts":["一般語序","倒裝"],"a":1,"say":"否定字 Not only 放句首，後面要倒裝。"},{"q":"倒裝的順序是？","en":"What is the order for inversion?","opts":["助動詞 + 主詞 + 原形動詞","動詞 + 主詞"],"a":0,"say":"像問句一樣：did + she + meet。"}],"why_zh":"Not only 放句首要倒裝，過去式借助動詞 did，變成 did she meet。she met 是一般語序，met she 不是正確的倒裝方式。","why_en":"'Not only' at the front needs question order: did she meet."},{"lvl":700,"s":"___ you have any questions, please contact our customer service team.","zh":"如果您有任何問題，請聯絡我們的客服團隊。","opts":["Were","Should","Had","Did"],"a":1,"guide":[{"q":"空格後面 you have 的動詞是什麼形式？","en":"What form is the verb in 'you have'?","opts":["原形動詞","過去分詞"],"a":0,"say":"have 是原形，前面需要能接原形的助動詞。"},{"q":"省略 if 的倒裝中，哪一個字後面接原形動詞？","en":"In inversion without 'if', which word is followed by a base verb?","opts":["Had","Should"],"a":1,"say":"Should you have... = If you should have...，表示「萬一、如果」。"}],"why_zh":"Should + 主詞 + 原形動詞 = If 主詞 should + 原形，常用在客服、通知類句子。Had 要接 p.p.，Were 後面也不接原形動詞（要接名詞、形容詞或 to V）。","why_en":"'Should you have' means 'If you have' and takes a base verb."},{"lvl":700,"s":"Seldom ___ such a large order from a new client.","zh":"我們很少從新客戶那裡接到這麼大的訂單。","opts":["we receive","we do receive","do we receive","receive we"],"a":2,"guide":[{"q":"Seldom（很少）是不是帶有否定意味的字？","en":"Is 'seldom' a negative word?","opts":["是","不是"],"a":0,"say":"seldom 是否定副詞，放句首要倒裝。"},{"q":"現在式的倒裝要借用哪個助動詞放在主詞前面？","en":"Which auxiliary goes before the subject in present-tense inversion?","opts":["do","did"],"a":0,"say":"現在式借用 do，變成 do we receive。"}],"why_zh":"Seldom 放句首要倒裝成 do we receive。we do receive 只是加強語氣，語序沒有倒裝。","why_en":"'Seldom' at the front requires 'do we receive'."},{"lvl":700,"s":"___ we known about the traffic jam, we would have left the hotel earlier.","zh":"要是我們早知道會塞車，我們就會早點離開飯店了。","opts":["If","Have","Did","Had"],"a":3,"guide":[{"q":"known 是什麼形式？","en":"What form is 'known'?","opts":["過去分詞","原形"],"a":0,"say":"known 是 p.p.，前面要有 have 或 had。"},{"q":"主句 would have left 是和過去事實相反，If 子句原本是？","en":"The main clause is past unreal. What was the original if-clause?","opts":["If we had known","If we have known"],"a":0,"say":"省略 If 後把 Had 移到句首：Had we known。"}],"why_zh":"If we had known 省略 If 後倒裝為 Had we known。If we known 少了 had，文法錯誤；Have 不符合過去假設。","why_en":"'Had we known' is 'If we had known' with inversion."},{"lvl":700,"s":"Only after the manager arrived ___ the meeting.","zh":"直到經理到了，我們才開始開會。","opts":["did we start","we started","we did start","started we"],"a":0,"guide":[{"q":"Only after + 子句 放在句首時，哪個部分要倒裝？","en":"With 'Only after + clause' at the front, which part is inverted?","opts":["after 後面的子句","後面的主要子句"],"a":1,"say":"after 子句保持一般語序，倒裝的是後面的主要子句。"},{"q":"主要子句是過去式，要借用哪個助動詞？","en":"The main clause is past. Which auxiliary do we borrow?","opts":["do","did"],"a":1,"say":"過去式借用 did：did we start。"}],"why_zh":"Only after... 放句首，主要子句要倒裝成 did we start。we started 是一般語序，不能接在 Only after 片語後面。","why_en":"'Only after...' at the front inverts the main clause: did we start."},{"lvl":700,"s":"Never ___ such excellent service at a restaurant.","zh":"我從來沒有在餐廳享受過這麼好的服務。","opts":["I have experienced","have I experienced","I experienced","experienced I"],"a":1,"guide":[{"q":"Never 放句首，後面的主詞和助動詞順序是？","en":"With 'Never' at the front, what is the order?","opts":["主詞 + 助動詞","助動詞 + 主詞"],"a":1,"say":"否定字在句首，助動詞要放到主詞前面。"}],"why_zh":"Never 放句首要倒裝，現在完成式把 have 移到主詞前：have I experienced。I have experienced 是一般語序。","why_en":"'Never' at the front moves 'have' before the subject."},{"lvl":700,"s":"Rarely ___ late for work, so everyone was surprised when he missed the morning meeting.","zh":"何先生很少上班遲到，所以他錯過晨會時大家都很驚訝。","opts":["Mr. Ho is","Mr. Ho was","is Mr. Ho","Mr. Ho has"],"a":2,"guide":[{"q":"Rarely 放句首時，be 動詞要放在主詞的前面還是後面？","en":"With 'Rarely' at the front, does 'be' go before or after the subject?","opts":["後面","前面"],"a":1,"say":"be 動詞直接移到主詞前面，不用借 do。"}],"why_zh":"Rarely 是否定副詞，句首要倒裝，be 動詞直接放到主詞前：is Mr. Ho。Mr. Ho is 和 Mr. Ho was 都沒有倒裝。","why_en":"'Rarely' at the front puts 'is' before the subject: is Mr. Ho."},{"lvl":700,"s":"___ the shipment arrive damaged, we will send a replacement immediately.","zh":"萬一貨物送達時有損壞，我們會立刻寄送替換品。","opts":["If","Had","Were","Should"],"a":3,"guide":[{"q":"主詞 the shipment 是單數，但動詞 arrive 沒有加 s，代表前面有什麼？","en":"'The shipment' is singular but 'arrive' has no -s. What does that show?","opts":["有助動詞","沒有助動詞"],"a":0,"say":"動詞是原形，表示前面有助動詞。"},{"q":"哪一個可以放句首、後面接主詞 + 原形動詞？","en":"Which one can start the sentence before subject + base verb?","opts":["Should","If"],"a":0,"say":"Should + 主詞 + 原形 = If 主詞 should + 原形。"}],"why_zh":"arrive 是原形，表示是 Should the shipment arrive 的倒裝（= If the shipment should arrive）。If the shipment arrive 缺了第三人稱 s，文法錯誤。","why_en":"The base verb 'arrive' shows inverted 'Should the shipment arrive'."},{"lvl":700,"s":"Hardly ___ the office when it started to rain heavily.","zh":"我一離開辦公室就開始下大雨。","opts":["had I left","I had left","I left","did I leave"],"a":0,"guide":[{"q":"Hardly 放句首，後面要倒裝嗎？","en":"Does 'Hardly' at the front need inversion?","opts":["要","不用"],"a":0,"say":"Hardly 是否定副詞，句首要倒裝。"},{"q":"「一……就……」的 Hardly...when 句型，先發生的動作要用什麼時態？","en":"In 'Hardly... when', what tense is the earlier action?","opts":["過去式","過去完成式"],"a":1,"say":"先離開辦公室，所以用過去完成式 had left，倒裝成 had I left。"}],"why_zh":"Hardly...when 表示「一……就……」，前面動作用過去完成式並倒裝：had I left。I had left 沒有倒裝；did I leave 時態不符合這個句型。","why_en":"'Hardly ... when' uses inverted past perfect: had I left."},{"lvl":700,"s":"Under no circumstances ___ share their passwords with anyone.","zh":"員工在任何情況下都不可以把密碼告訴任何人。","opts":["employees should","should employees","employees","do employees should"],"a":1,"guide":[{"q":"Under no circumstances 是否定片語嗎？","en":"Is 'Under no circumstances' a negative phrase?","opts":["不是","是"],"a":1,"say":"有 no，是否定片語，放句首要倒裝。"},{"q":"已經有助動詞 should 時，倒裝怎麼做？","en":"When 'should' is already there, how do we invert?","opts":["把 should 移到主詞前","另外加 do"],"a":0,"say":"直接把 should 移到主詞前：should employees share。"}],"why_zh":"否定片語 Under no circumstances 放句首要倒裝，把 should 移到主詞前。employees should 沒有倒裝；do 和 should 不能同時使用。","why_en":"A negative phrase at the front moves 'should' before the subject."},{"lvl":900,"s":"___ the board approved the budget last month, the lobby renovation would already be finished.","zh":"要是董事會上個月就核准了預算，大廳的整修現在早就完成了。","opts":["Unless","Should","Had","Were"],"a":2,"guide":[{"q":"approved 在這裡要當過去式還是過去分詞看？","en":"Should 'approved' be read as past tense or past participle here?","opts":["過去分詞，前面要有助動詞","一般過去式"],"a":0,"say":"主句是假設語氣，last month 和事實相反，要用 had + p.p.。"},{"q":"哪個字放句首可以代替 If ... had？","en":"Which word at the front replaces 'If ... had'?","opts":["Had","Were"],"a":0,"say":"Had the board approved = If the board had approved。"}],"why_zh":"上個月沒核准（過去）導致現在沒完成（現在），If 子句要用 had approved，省略 If 倒裝為 Had the board approved。Unless 語意相反，Were 和 Should 後面不接 p.p. 的主動用法。","why_en":"'Had the board approved' is the inverted past unreal condition."},{"lvl":900,"s":"Not until the final figures were released ___ how much the advertising campaign had actually cost.","zh":"直到最終數據公布，經理們才了解這次廣告活動實際上花了多少錢。","opts":["the managers realized","the managers did realize","realized the managers","did the managers realize"],"a":3,"guide":[{"q":"Not until + 子句 放句首，要倒裝哪一部分？","en":"With 'Not until + clause' at the front, which part is inverted?","opts":["until 後面的子句","後面的主要子句"],"a":1,"say":"until 子句維持一般語序，主要子句要倒裝。"},{"q":"主要子句是過去式，倒裝要用？","en":"The main clause is past. What do we use to invert?","opts":["did + 主詞 + 原形","主詞 + did + 原形"],"a":0,"say":"did the managers realize 是正確的倒裝。"}],"why_zh":"Not until... 放句首，主要子句要倒裝：did the managers realize。the managers did realize 只是強調語氣，沒有倒裝。","why_en":"After 'Not until...', the main clause inverts: did the managers realize."},{"lvl":900,"s":"So popular ___ that the hotel had to hire additional staff for the weekend sessions.","zh":"烹飪課太受歡迎了，飯店不得不為週末課程加聘人手。","opts":["was the cooking class","the cooking class was","the cooking class","was being the cooking class"],"a":0,"guide":[{"q":"原本的句子是 The cooking class was so popular that...，把 So popular 移到句首後要怎麼辦？","en":"Originally 'The class was so popular that...'. What happens when 'So popular' moves to the front?","opts":["主詞和 be 動詞倒裝","語序不變"],"a":0,"say":"So + 形容詞 放句首時，be 動詞要移到主詞前面。"}],"why_zh":"So + 形容詞 + that 句型把 So popular 移到句首時，要倒裝成 was the cooking class。the cooking class was 沒有倒裝；the cooking class 缺動詞。","why_en":"'So + adjective' at the front needs 'was + subject'."},{"lvl":900,"s":"___ the contract be signed by Friday, construction of the new warehouse will begin the following week.","zh":"如果合約能在週五前簽好，新倉庫的工程將在下一週開工。","opts":["If","Should","Had","Unless"],"a":1,"guide":[{"q":"空格後面是 the contract be signed，be 是原形，前面需要什麼？","en":"'The contract be signed' has base 'be'. What does it need in front?","opts":["一般連接詞","可以接原形的助動詞"],"a":1,"say":"原形 be 前面需要助動詞，If 和 Unless 後面應該是 is signed。"},{"q":"Should 和 Had，哪個後面接原形？","en":"Which takes a base verb, 'Should' or 'Had'?","opts":["Should","Had"],"a":0,"say":"Should the contract be signed = If the contract should be signed。"}],"why_zh":"be 是原形，只能接在 Should 後面形成倒裝（= If the contract should be signed）。If 或 Unless 後面要用 is signed；Had 要接 been。","why_en":"Base 'be' after the subject shows inverted 'Should the contract be signed'."},{"lvl":900,"s":"Only by reducing its operating costs ___ to remain competitive in the overseas market.","zh":"公司唯有降低營運成本，才能在海外市場保持競爭力。","opts":["the company will be able","the company is able","will the company be able","the company being able"],"a":2,"guide":[{"q":"Only by + V-ing 放句首時，後面要倒裝嗎？","en":"Does 'Only by + V-ing' at the front require inversion?","opts":["不用","要"],"a":1,"say":"Only + 副詞片語 放句首，後面主要子句要倒裝。"},{"q":"有助動詞 will 時，倒裝的順序是？","en":"With 'will', what is the inverted order?","opts":["will + 主詞 + be able","主詞 + will + be able"],"a":0,"say":"把 will 移到主詞前：will the company be able。"}],"why_zh":"Only by... 放句首要倒裝，把 will 移到主詞前：will the company be able。the company will be able 語意對但沒有倒裝，是最常見的陷阱。","why_en":"'Only by...' at the front requires 'will the company be able'."}]},{"id":"causative","title_zh":"使役動詞與感官動詞","title_en":"Causative and perception verbs","icon":"🤝","pattern":"make / have / let + 受詞 + V；get + 受詞 + to V；have / get + 物 + p.p.","rule_zh":"make（使、逼）、have（叫、請）、let（讓）+ 人 + 原形動詞。get 意思和 have 相近，但要接 to V；help 後面可接原形或 to V。如果受詞是「被處理的東西」，就用 have / get + 物 + p.p.。感官動詞（see, hear, watch）+ 受詞 + V／V-ing，受詞是被動時用 p.p.。","rule_en":"Make, have and let take object + base verb; get takes object + to V. Use have/get + thing + p.p. when the thing receives the action. Perception verbs like see and hear take object + V/V-ing, or p.p. for passive meaning.","spot_zh":"考題線索：空格前有 make / have / let / get / help / see / hear + 受詞，選項是同一個動詞的 V、to V、V-ing、p.p. 時，先看受詞是「做動作的人」還是「被處理的東西」。","examples":[{"en":"My mom made me clean my room.","zh":"我媽媽叫我打掃房間。"},{"en":"I had my hair cut yesterday.","zh":"我昨天去剪了頭髮。"},{"en":"Let me carry that bag for you.","zh":"讓我幫你提那個袋子。"}],"qs":[{"lvl":700,"s":"The manager made everyone ___ the safety training last week.","zh":"經理上週要求每個人都參加安全訓練。","opts":["attend","to attend","attending","attended"],"a":0,"guide":[{"q":"受詞 everyone 是自己去參加訓練，還是被參加？","en":"Does 'everyone' do the attending or receive it?","opts":["自己去參加","被參加"],"a":0,"say":"everyone 是做動作的人，所以用主動。"},{"q":"make + 人 + ？","en":"Make + person + what?","opts":["to V","原形動詞"],"a":1,"say":"使役動詞 make 後面接人 + 原形動詞。"}],"why_zh":"make + 人 + 原形動詞，所以是 attend。to attend 是 make 主動句最常見的陷阱，只有被動 be made to V 才用 to。","why_en":"'Make' + person + base verb: made everyone attend."},{"lvl":700,"s":"I had my car ___ at the garage near the office.","zh":"我把車送到辦公室附近的修車廠修理。","opts":["repair","repaired","repairing","to repair"],"a":1,"guide":[{"q":"my car 會自己修理東西嗎？","en":"Can 'my car' repair something by itself?","opts":["會","不會，是被修理"],"a":1,"say":"車子是被修理的東西。"},{"q":"have + 物 + 被處理，要用什麼形式？","en":"Have + thing + receiving the action: which form?","opts":["過去分詞 p.p.","原形動詞"],"a":0,"say":"have + 物 + p.p. 表示「請人把某物處理好」。"}],"why_zh":"車子是被修理的，所以用 have + 物 + p.p.：had my car repaired。repair 是給「人」做動作時才用。","why_en":"The car receives the action, so we use have + thing + p.p."},{"lvl":700,"s":"Please let me ___ if the client calls again this afternoon.","zh":"如果客戶今天下午又打來，請讓我知道。","opts":["knowing","to know","know","known"],"a":2,"guide":[{"q":"let 後面接人之後，動詞用什麼形式？","en":"After 'let' + person, what verb form follows?","opts":["原形動詞","to V","V-ing"],"a":0,"say":"let + 人 + 原形動詞，例如 let me know。"}],"why_zh":"let + 人 + 原形動詞，所以是 let me know。let 後面不能接 to V。","why_en":"'Let' + person + base verb: let me know."},{"lvl":700,"s":"We got the technician ___ the printer before the meeting started.","zh":"我們在會議開始前請技術人員檢查了印表機。","opts":["check","checked","checking","to check"],"a":3,"guide":[{"q":"technician 是做檢查的人，還是被檢查的東西？","en":"Is the technician doing the checking or being checked?","opts":["做檢查的人","被檢查"],"a":0,"say":"技術人員是做動作的人，所以用主動。"},{"q":"get + 人 + 主動動作，要接什麼？","en":"Get + person + active action: what form?","opts":["原形動詞","to V"],"a":1,"say":"get 和 make/have 不同，要接 to V。"}],"why_zh":"get + 人 + to V 表示「說服、請某人做」，所以是 got the technician to check。check 是 have/make 的用法，放在 get 後面是常見錯誤。","why_en":"'Get' + person + to V: got the technician to check."},{"lvl":700,"s":"Ms. Lee will have her assistant ___ the hotel reservations for the trip.","zh":"李小姐會請她的助理確認這趟出差的飯店訂房。","opts":["confirm","confirmed","to confirm","confirming"],"a":0,"guide":[{"q":"受詞 her assistant 是人，是做確認動作的那一方嗎？","en":"Is 'her assistant' the one who does the confirming?","opts":["不是","是"],"a":1,"say":"助理是做動作的人，所以用主動。"},{"q":"have + 人 + 主動動作 要接？","en":"Have + person + active action: which form?","opts":["原形動詞","to V"],"a":0,"say":"have + 人 + 原形動詞。"}],"why_zh":"have + 人 + 原形動詞，助理是做動作的人，所以是 confirm。confirmed 是用在 have + 物 + p.p.。","why_en":"'Have' + person + base verb: have her assistant confirm."},{"lvl":700,"s":"The company got the new brochures ___ by a local printing shop.","zh":"公司請一家本地印刷廠印製新的宣傳手冊。","opts":["print","printed","to print","printing"],"a":1,"guide":[{"q":"句子後面的 by a local printing shop 給了什麼線索？","en":"What clue does 'by a local printing shop' give?","opts":["手冊是被印的","手冊自己印東西"],"a":0,"say":"by + 執行者，代表手冊是被印製的。"},{"q":"get + 物 + 被處理，用哪一個形式？","en":"Get + thing + receiving the action: which form?","opts":["to V","p.p."],"a":1,"say":"get + 物 + p.p.，和 have + 物 + p.p. 一樣。"}],"why_zh":"手冊是被印的，加上 by 片語，要用 get + 物 + p.p.：got the brochures printed。to print 是 get + 人 的用法。","why_en":"The brochures receive the action, so get + thing + p.p.: printed."},{"lvl":700,"s":"The supervisor helped the new staff ___ the online system on their first day.","zh":"主管在新員工第一天幫助他們學習線上系統。","opts":["learning","learned","learn","learns"],"a":2,"guide":[{"q":"help + 人 後面可以接哪些形式？","en":"What forms can follow 'help' + person?","opts":["原形或 to V","V-ing"],"a":0,"say":"help + 人 + (to) V，原形和 to V 都可以。"}],"why_zh":"help + 人 + 原形動詞（或 to V），選項中只有 learn 正確。learning 和 learned 都不能接在 help + 人 後面。","why_en":"'Help' + person + base verb (or to V): help the staff learn."},{"lvl":700,"s":"The hotel lets guests ___ their luggage at the front desk after checkout.","zh":"飯店讓房客在退房後把行李寄放在櫃檯。","opts":["leaving","to leave","left","leave"],"a":3,"guide":[{"q":"let 是不是使役動詞？","en":"Is 'let' a causative verb?","opts":["是","不是"],"a":0,"say":"let 是使役動詞，表示「允許、讓」。"},{"q":"let + 人 + ？","en":"Let + person + what?","opts":["to V","原形動詞"],"a":1,"say":"let + 人 + 原形動詞：let guests leave。"}],"why_zh":"let + 人 + 原形動詞，所以是 leave。to leave 是 allow 的用法（allow guests to leave），不能用在 let 後面。","why_en":"'Let' + person + base verb: lets guests leave."},{"lvl":700,"s":"The director had the contract ___ by the legal team before signing it.","zh":"主管在簽約前請法務團隊審閱了合約。","opts":["reviewed","review","reviewing","to review"],"a":0,"guide":[{"q":"contract 是審閱別人，還是被審閱？","en":"Does the contract review something, or is it reviewed?","opts":["審閱別人","被審閱"],"a":1,"say":"合約是被法務團隊審閱的。"},{"q":"have + 物 + 被動，用？","en":"Have + thing + passive meaning: which form?","opts":["p.p.","原形"],"a":0,"say":"have + 物 + p.p.：had the contract reviewed。"}],"why_zh":"合約是被審閱的，用 have + 物 + p.p.，所以是 reviewed。review 只能用在 have + 人 的主動結構。","why_en":"The contract is reviewed, so have + thing + p.p.: reviewed."},{"lvl":700,"s":"The heavy traffic on the highway made us ___ the first session of the conference.","zh":"高速公路上的嚴重塞車讓我們錯過了會議的第一場議程。","opts":["to miss","miss","missing","missed"],"a":1,"guide":[{"q":"這句的使役動詞是哪一個？","en":"Which causative verb is in this sentence?","opts":["made","traffic"],"a":0,"say":"made 是使役動詞，表示「使得」。"},{"q":"make + 人 + 動詞，要用？","en":"Make + person + verb: which form?","opts":["to miss","miss"],"a":1,"say":"make + 人 + 原形，所以是 made us miss。"}],"why_zh":"make + 人 + 原形動詞，所以是 miss。to miss 是常見陷阱，主動的 make 後面不接 to。","why_en":"'Make' + person + base verb: made us miss."},{"lvl":900,"s":"Before signing the agreement, the CEO will have the financial terms ___ carefully by an outside consultant.","zh":"在簽署協議前，執行長會請外部顧問仔細檢視財務條款。","opts":["examine","examining","examined","to examine"],"a":2,"guide":[{"q":"have 後面的受詞是一個人，還是 the financial terms？","en":"Is the object of 'have' a person or 'the financial terms'?","opts":["一個人","the financial terms"],"a":1,"say":"受詞是財務條款，是被檢視的東西。"},{"q":"by an outside consultant 說明了什麼？","en":"What does 'by an outside consultant' show?","opts":["條款被顧問檢視","條款自己檢視"],"a":0,"say":"被動意義，用 have + 物 + p.p.。"}],"why_zh":"the financial terms 是被檢視的對象，句尾又有 by 片語，要用 have + 物 + p.p.：examined。examine 會變成條款自己去檢視，語意錯誤。","why_en":"The terms are examined by a consultant, so have + thing + p.p."},{"lvl":900,"s":"Employees were made ___ a confidentiality agreement before they could access the customer database.","zh":"員工被要求在存取客戶資料庫前簽署保密協議。","opts":["sign","signing","signed","to sign"],"a":3,"guide":[{"q":"were made 是主動還是被動？","en":"Is 'were made' active or passive?","opts":["主動","被動"],"a":1,"say":"were made 是 make 的被動式。"},{"q":"make 變成被動時，後面的原形動詞要怎麼變？","en":"When 'make' becomes passive, what happens to the base verb?","opts":["保持原形","要加 to"],"a":1,"say":"be made + to V，被動時要把 to 加回來。"}],"why_zh":"make + 人 + V 改成被動時要變成 be made + to V，所以是 to sign。sign 是主動 make 的用法，被動時是陷阱。","why_en":"Passive 'make' takes to V: were made to sign."},{"lvl":900,"s":"While waiting at the crowded airport gate, the passengers heard their names ___ over the loudspeaker.","zh":"在擁擠的機場登機門等候時，乘客們聽到廣播叫他們的名字。","opts":["called","calling","call","to call"],"a":0,"guide":[{"q":"heard 是哪一種動詞？","en":"What kind of verb is 'heard'?","opts":["感官動詞","使役動詞"],"a":0,"say":"hear 是感官動詞，後面接受詞 + V／V-ing／p.p.。"},{"q":"their names 是自己叫人，還是被叫？","en":"Do 'their names' call, or are they called?","opts":["自己叫人","被叫"],"a":1,"say":"名字是被叫的，所以用 p.p.。"}],"why_zh":"感官動詞 hear + 受詞 + p.p. 表示被動，名字是被廣播叫出來的，所以用 called。calling 和 call 會變成名字自己在叫人。","why_en":"Names are called, so perception verb + object + p.p.: heard their names called."},{"lvl":900,"s":"To speed up the hiring process, the HR manager got the applicants ___ their forms online in advance.","zh":"為了加快招募流程，人資經理請應徵者事先在網路上提交表格。","opts":["submit","to submit","submitted","submission"],"a":1,"guide":[{"q":"受詞 the applicants 是做提交動作的人嗎？","en":"Are 'the applicants' the ones who submit?","opts":["是","不是"],"a":0,"say":"應徵者是做動作的人，所以用主動。"},{"q":"get + 人 + 主動動作，要接？","en":"Get + person + active action: which form?","opts":["原形","to V"],"a":1,"say":"get + 人 + to V：got the applicants to submit。"}],"why_zh":"get + 人 + to V，應徵者是提交表格的人，所以是 to submit。submit 是 have/make 的用法；submitted 用在 get + 物 + p.p.。","why_en":"'Get' + person + to V: got the applicants to submit."},{"lvl":900,"s":"According to the lease, the landlord will not let the tenants ___ the walls of the office without written permission.","zh":"根據租約，房東不允許房客在沒有書面許可的情況下粉刷辦公室牆壁。","opts":["painting","to paint","paint","painted"],"a":2,"guide":[{"q":"let 的受詞是 the tenants 還是 the walls？","en":"Is the object of 'let' 'the tenants' or 'the walls'?","opts":["the walls","the tenants"],"a":1,"say":"let 的受詞是房客，牆壁是 paint 的受詞。"},{"q":"let + 人 + ？","en":"Let + person + what?","opts":["原形動詞","to V"],"a":0,"say":"let + 人 + 原形：let the tenants paint。"}],"why_zh":"let + 人 + 原形動詞，房客是粉刷的人，所以是 paint。to paint 是 allow 的用法；painted 會誤以為受詞是牆壁。","why_en":"'Let' + person + base verb: let the tenants paint."}]},{"id":"adverb","title_zh":"副詞的用法與位置","title_en":"Adverbs: form and position","icon":"⚡","pattern":"形容詞 + ly → 副詞；頻率副詞放在 be 動詞後、一般動詞前","rule_zh":"副詞用來修飾動詞、形容詞或其他副詞，大多是「形容詞 + ly」。頻率副詞（always, usually, never）放在 be 動詞後面、一般動詞前面。already 用在肯定句（已經）、yet 用在否定句和問句（還沒、了嗎）、still 表示「仍然」。hard 是「努力地」，hardly 是「幾乎不」，意思完全不同。","rule_en":"Adverbs describe verbs, adjectives or other adverbs, and many end in -ly. Frequency adverbs go after 'be' and before main verbs. Use 'already' in positive sentences, 'yet' in negatives and questions, and 'still' for something continuing; 'hard' means with effort, 'hardly' means almost not.","spot_zh":"考題線索：選項是同一個字的形容詞、副詞、名詞（careful / carefully / care），空格在動詞前後或形容詞前面時，通常要選 -ly 副詞；選項是 already / yet / still 時看肯定或否定。","examples":[{"en":"She always drinks coffee in the morning.","zh":"她總是在早上喝咖啡。"},{"en":"My brother runs very fast.","zh":"我哥哥跑得很快。"},{"en":"I have already eaten lunch.","zh":"我已經吃過午餐了。"}],"qs":[{"lvl":700,"s":"Ms. Kim ___ arrives at the office before eight o'clock.","zh":"金小姐通常在八點前抵達辦公室。","opts":["usually","usual","more usual","usualness"],"a":0,"guide":[{"q":"空格後面的 arrives 是什麼詞性？","en":"What part of speech is 'arrives'?","opts":["名詞","動詞"],"a":1,"say":"arrives 是動詞，修飾動詞要用副詞。"},{"q":"頻率副詞要放在一般動詞的前面還是後面？","en":"Does a frequency adverb go before or after a main verb?","opts":["前面","後面"],"a":0,"say":"頻率副詞放在一般動詞前面：usually arrives。"}],"why_zh":"空格修飾動詞 arrives，要用頻率副詞 usually。usual 是形容詞，不能修飾動詞。","why_en":"We need an adverb before the verb 'arrives': usually."},{"lvl":700,"s":"The new manager speaks English very ___.","zh":"新經理的英文說得非常流利。","opts":["fluent","fluently","fluency","more fluent"],"a":1,"guide":[{"q":"空格在說明「怎麼說」，修飾的是哪個字？","en":"The blank describes how he speaks. Which word does it modify?","opts":["speaks","English"],"a":0,"say":"修飾的是動詞 speaks。"},{"q":"修飾動詞要用？","en":"What modifies a verb?","opts":["形容詞","副詞"],"a":1,"say":"修飾動詞用副詞，所以是 fluently。"}],"why_zh":"空格修飾動詞 speaks，表示說話的方式，要用副詞 fluently。fluent 是形容詞，要放在名詞前或 be 動詞後。","why_en":"The blank describes the verb 'speaks', so we need the adverb fluently."},{"lvl":700,"s":"Have you finished the monthly sales report ___?","zh":"你完成每月業務報告了嗎？","opts":["still","since","yet","never"],"a":2,"guide":[{"q":"這個句子是肯定句、否定句還是問句？","en":"Is this a positive sentence, a negative, or a question?","opts":["肯定句","問句"],"a":1,"say":"這是現在完成式的問句。"},{"q":"完成式問句的句尾常用哪個字表示「了嗎」？","en":"Which word at the end of a perfect question means 'by now'?","opts":["yet","still"],"a":0,"say":"yet 用在問句和否定句的句尾。"}],"why_zh":"現在完成式的問句句尾用 yet，表示「……了嗎」。still 表示「仍然」，不放在這種問句的句尾。","why_en":"'Yet' is used at the end of perfect-tense questions."},{"lvl":700,"s":"The team worked ___ to finish the project before the deadline.","zh":"團隊努力工作，在截止日前完成了專案。","opts":["hardly","hardness","harden","hard"],"a":3,"guide":[{"q":"團隊是「努力地」工作，還是「幾乎沒」工作？","en":"Did the team work with effort or almost not at all?","opts":["努力地","幾乎沒有"],"a":0,"say":"他們在截止日前完成了，所以是努力工作。"},{"q":"「努力地」的副詞是？","en":"Which adverb means 'with effort'?","opts":["hardly","hard"],"a":1,"say":"hard 本身就是副詞，意思是「努力地」。"}],"why_zh":"hard 當副詞是「努力地」，worked hard 表示努力工作。hardly 是「幾乎不」，意思相反，是常見陷阱。","why_en":"'Hard' means with effort; 'hardly' means almost not."},{"lvl":700,"s":"The hotel room was ___ clean and comfortable.","zh":"飯店房間非常乾淨又舒適。","opts":["extremely","extreme","extremity","extremes"],"a":0,"guide":[{"q":"空格後面的 clean 是什麼詞性？","en":"What part of speech is 'clean' here?","opts":["形容詞","動詞"],"a":0,"say":"clean 在 was 後面是形容詞。"},{"q":"修飾形容詞要用？","en":"What modifies an adjective?","opts":["形容詞","副詞"],"a":1,"say":"修飾形容詞要用副詞 extremely。"}],"why_zh":"空格修飾形容詞 clean and comfortable，要用副詞 extremely。extreme 是形容詞，不能修飾另一個形容詞。","why_en":"An adverb modifies the adjectives: extremely clean."},{"lvl":700,"s":"I can ___ hear you because the phone line is so noisy.","zh":"電話線路太吵了，我幾乎聽不到你說話。","opts":["hard","hardly","harder","hardest"],"a":1,"guide":[{"q":"線路很吵，我是聽得很清楚，還是幾乎聽不到？","en":"With a noisy line, do I hear well or almost not at all?","opts":["聽得很清楚","幾乎聽不到"],"a":1,"say":"線路很吵，所以幾乎聽不到。"},{"q":"表示「幾乎不」的副詞是？","en":"Which adverb means 'almost not'?","opts":["hardly","hard"],"a":0,"say":"hardly 表示「幾乎不」。"}],"why_zh":"because the phone line is so noisy 說明聽不清楚，要用 hardly（幾乎不）。hard 是「努力地」，can hard hear 不合文法也不合語意。","why_en":"'Hardly' means almost not, which fits the noisy line."},{"lvl":700,"s":"The client ___ has not paid the invoice, so please send another reminder.","zh":"客戶仍然還沒付款，所以請再寄一次提醒。","opts":["already","yet","still","ever"],"a":2,"guide":[{"q":"空格在 has not 的前面，這個位置可以放 yet 嗎？","en":"The blank is before 'has not'. Can 'yet' go there?","opts":["可以","不可以"],"a":1,"say":"yet 通常放在否定句句尾，不放在助動詞前面。"},{"q":"「到現在仍然沒付」要用哪個字？","en":"Which word means the situation continues: 'even now not paid'?","opts":["still","already"],"a":0,"say":"still 放在否定助動詞前，表示「仍然還沒」。"}],"why_zh":"still + 否定 表示「仍然沒有」，放在 has not 前面。already 用在肯定句；yet 要放在句尾（has not paid the invoice yet）。","why_en":"'Still' before a negative means the problem continues."},{"lvl":700,"s":"Our sales have increased ___ since the new advertising campaign started.","zh":"自從新的廣告活動開始以來，我們的銷售量大幅增加。","opts":["significant","significance","signify","significantly"],"a":3,"guide":[{"q":"空格前面的 have increased 是什麼？","en":"What is 'have increased'?","opts":["動詞","名詞"],"a":0,"say":"have increased 是完整的動詞，後面不需要受詞。"},{"q":"動詞後面說明「增加的程度」要用？","en":"What describes how much a verb happened?","opts":["副詞","名詞"],"a":0,"say":"修飾動詞用副詞 significantly。"}],"why_zh":"increase 在這裡是不及物動詞，後面用副詞說明程度：significantly。significant 是形容詞，不能修飾動詞。","why_en":"The adverb significantly describes the verb 'increased'."},{"lvl":700,"s":"The shipment has ___ arrived, so you can check the items now.","zh":"貨物已經到了，所以你現在可以檢查品項。","opts":["already","yet","still","ever"],"a":0,"guide":[{"q":"這是肯定句還是否定句？","en":"Is this sentence positive or negative?","opts":["否定句","肯定句"],"a":1,"say":"has arrived 是肯定句，而且已經完成了。"},{"q":"肯定的完成式中，放在 has 和 p.p. 中間表示「已經」的是？","en":"In a positive perfect sentence, which word between 'has' and p.p. means 'by now'?","opts":["yet","already"],"a":1,"say":"already 用在肯定句，放在 has 和 p.p. 之間。"}],"why_zh":"肯定的完成式表示「已經」要用 already。yet 用在否定句和問句；still 不放在 has 和 p.p. 中間表示完成。","why_en":"'Already' is used in positive perfect sentences: has already arrived."},{"lvl":700,"s":"Mr. Chang is ___ late for meetings; he is a very punctual person.","zh":"張先生開會從不遲到，他是很守時的人。","opts":["always","never","often","usually"],"a":1,"guide":[{"q":"分號後面說他 very punctual（很守時），那他會常遲到嗎？","en":"He is very punctual. Is he often late?","opts":["常遲到","從不遲到"],"a":1,"say":"很守時的人從不遲到。"}],"why_zh":"後半句說他很守時，所以頻率副詞要用 never（從不），放在 be 動詞後面。always、often、usually 都和「守時」矛盾。","why_en":"A punctual person is never late."},{"lvl":900,"s":"The renovation of the main conference room was completed ___ ahead of schedule, allowing the event to proceed as planned.","zh":"主會議室的整修工程大幅提前完工，讓活動得以照計畫進行。","opts":["remark","remarkable","remarked","remarkably"],"a":3,"guide":[{"q":"was completed 已經是完整的被動句了嗎？","en":"Is 'was completed' already a complete passive verb?","opts":["是","還缺東西"],"a":0,"say":"主詞 + was completed 已經完整，空格是修飾用的。"},{"q":"空格修飾的是 ahead of schedule 這個副詞片語，要用什麼詞性？","en":"The blank modifies 'ahead of schedule'. What part of speech is needed?","opts":["副詞","形容詞"],"a":0,"say":"修飾副詞片語要用副詞 remarkably。"}],"why_zh":"空格修飾副詞片語 ahead of schedule，要用副詞 remarkably。remarkable 是形容詞，不能修飾副詞片語。","why_en":"An adverb, remarkably, modifies the phrase 'ahead of schedule'."},{"lvl":900,"s":"Although the product launch was announced months ago, the marketing materials have ___ to be finalized.","zh":"雖然產品發表會在幾個月前就宣布了，但行銷資料還沒定案。","opts":["already","since","ever","yet"],"a":3,"guide":[{"q":"Although 表示前後語意相反，行銷資料是已經完成還是還沒完成？","en":"'Although' shows contrast. Are the materials finished or not?","opts":["已經完成","還沒完成"],"a":1,"say":"宣布很久了，但資料還沒完成。"},{"q":"哪個片語表示「尚未」？","en":"Which phrase means 'still not done'?","opts":["have yet to V","have already to V"],"a":0,"say":"have yet to + V = 還沒有……，是多益常考的用法。"}],"why_zh":"have yet to be finalized 表示「尚未定案」，和 Although 的轉折相符。already 表示已經完成，和語意相反，且不能接 to V。","why_en":"'Have yet to' means 'have not yet', which fits the contrast."},{"lvl":900,"s":"The quarterly profits reported by the overseas branches were ___ higher than financial analysts had predicted.","zh":"海外分公司公布的季度獲利比財務分析師預測的高出許多。","opts":["considerably","considerable","consideration","considerate"],"a":0,"guide":[{"q":"空格後面的 higher 是什麼詞性？","en":"What part of speech is 'higher'?","opts":["比較級形容詞","名詞"],"a":0,"say":"higher 是比較級形容詞。"},{"q":"修飾比較級形容詞要用？","en":"What modifies a comparative adjective?","opts":["形容詞","副詞"],"a":1,"say":"比較級前面用副詞加強語氣：considerably higher。"}],"why_zh":"比較級 higher 前面要用副詞修飾，所以是 considerably。considerable 是形容詞，considerate 意思是「體貼的」，都不對。","why_en":"An adverb, considerably, modifies the comparative 'higher'."},{"lvl":900,"s":"Applicants who have ___ any experience in sales are encouraged to attend the introductory training session first.","zh":"幾乎沒有任何業務經驗的應徵者，建議先參加入門訓練課程。","opts":["hard","hardly","harder","hardness"],"a":1,"guide":[{"q":"要先參加「入門」訓練的人，經驗多還是少？","en":"Do people who need introductory training have a lot or little experience?","opts":["很少","很多"],"a":0,"say":"需要入門課程，表示經驗很少。"},{"q":"hardly any 的意思是？","en":"What does 'hardly any' mean?","opts":["很多","幾乎沒有"],"a":1,"say":"hardly any = 幾乎沒有。"}],"why_zh":"hardly any experience 表示「幾乎沒有經驗」，所以需要先上入門課程。hard 是「努力地」或「困難的」，不能放在 have 和 any 中間。","why_en":"'Hardly any' means almost no experience."},{"lvl":900,"s":"Ms. Ortiz, who manages the legal team, ___ reviews each contract personally before it is sent to overseas clients.","zh":"負責管理法務團隊的歐蒂茲小姐，會在合約寄給海外客戶前親自仔細審閱每一份。","opts":["careful","carefulness","carefully","more careful"],"a":2,"guide":[{"q":"去掉中間的 who manages the legal team，主詞後面的動詞是？","en":"Ignoring 'who manages the legal team', what is the main verb?","opts":["manages","reviews"],"a":1,"say":"主要動詞是 reviews，空格在它前面。"},{"q":"放在一般動詞前修飾它，要用？","en":"What goes before a main verb to describe it?","opts":["副詞","形容詞"],"a":0,"say":"副詞可以放在一般動詞前：carefully reviews。"}],"why_zh":"空格修飾主要動詞 reviews，要用副詞 carefully。careful 是形容詞，中間的 who 子句容易讓人看不出主要動詞。","why_en":"The adverb carefully modifies the main verb 'reviews'."}]}];
